if (!String.prototype.includes) {
	  String.prototype.includes = function(search, start) {
	    'use strict';

	    if (search instanceof RegExp) {
	      throw TypeError('first argument must not be a RegExp');
	    }
	    if (start === undefined) { start = 0; }
	    return this.indexOf(search, start) !== -1;
	  };
}
if (!Array.prototype.includes) {
	Array.prototype.includes = function(match){
		 return $.inArray(match,Object(this)) !== -1;
	}
}

// Function to prevent default action for zoom keys
function preventZoom(event) {
	try{
		if (sessionStorage.userdefinedcandconsole == 1 && ((event.ctrlKey || event.metaKey) && (event.keyCode === 187 || event.keyCode === 189 || event.keyCode === 48))) {
			event.preventDefault();
		}
	}catch(e){

	}
}
// Prevent zooming with Ctrl + and Ctrl -
document.addEventListener('keydown', preventZoom);
//Prevent zooming with mouse 
document.addEventListener('wheel', function(event) {
	try{
		if (event.ctrlKey && sessionStorage.userdefinedcandconsole == 1) {
        event.preventDefault();
    }
	}catch(e){
	}
}, { passive: false });


