		jQuery(document).on('mouseover keyup', '.tipIcon', function(e) {
			if(sessionStorage.operatingSystem !=undefined && sessionStorage.operatingSystem.toUpperCase() !== "ANDROID" && sessionStorage.operatingSystem.toUpperCase() !== "IOS"){
		var offset = $(this).offset();	
		var off_left = offset.left;	
		var off_top = offset.top;
		var objVal=jQuery(this).attr('objid');
		jQuery(".tooltipDiv .tooltipText").text(objVal);
		jQuery('.tooltipDiv').css('z-index',9999999);
		
		if($(this).parent().attr('class')==='queSteps'){
			jQuery('.tooltipDiv').show().offset({top:(off_top +20),left:(off_left+100)});
         }
		else{
		if(offset.left>$(window).width()/2){
			var off_right = ($(window).width() - ($(this).offset().left + $(this).outerWidth()));
			jQuery('.tooltipDiv').show();
			jQuery('.tooltipDiv').css('left','unset');
			jQuery('.tooltipDiv').css('top',offset.top>$(window).height()/2?off_top-40:off_top+40);
			jQuery('.tooltipDiv').css('right',off_right<=0?0:off_right-15);
		}
		else{
		jQuery('.tooltipDiv').show().offset({top:(offset.top>$(window).height()/2?off_top-40:off_top+40),left:(off_left-15<=0?15:off_left-15)});
		}
		}
		if($(this).parent().attr('class')==='highlight'){
			jQuery('.tooltipDiv').show().offset({top:(off_top-34)});
		}
		e.stopPropagation();
		}
		});
	jQuery(document).on('mouseout mouseup keydown focusout', '.tipIcon',function(e) {
		jQuery('.tooltipDiv').hide();
		});
