	$(document).on("paste",'.NumericTextField',function (e) {
		//if(this.activeElement.className.indexOf('keyboardInput')>-1){
		if(mockVar.allowCopyPaste == true){
		    const pasted = (e.originalEvent.clipboardData || window.clipboardData).getData("text");
		 
		    if (!/^[0-9.]+$/.test(pasted)) {
		        e.preventDefault();
		        return;
		    }
		    if ((this.value.length + pasted.length) > 15) {
		        e.preventDefault();
		    //}
		    }
		}else{
			e.preventDefault();console.log('pasting not allowed');
			return;
        }
			
		});
	
	
