//This function checks if the assessment is user defined cand console and if it requires virtual keyboard and then adds a virtual keyboard

$(document).ready(function() {
	//console.log("Check in session....asmt mode : "+sessionStorage.assessmentMode);
		if(typeof(sessionStorage.userdefinedcandconsole) == "undefined")
			sessionStorage.userdefinedcandconsole = 0;
		try{
			if(sessionStorage.userdefinedcandconsole == 1 && (document.URL).indexOf("configurationCheck.html") == -1){
				if(sessionStorage.orgId != "31583"){
		    		$(".BCLoader").hide();
		    		$(".normalLoader").show();
		    	} else {
		    		$(".BCLoader").show();
		    		$(".normalLoader").hide();
		    	}
				/*$(".normalLoader").css({"display":"none"});
				$(".BCLoader").css({"display":"block"});*/
				
			} else if((document.URL).indexOf("configurationCheck.html") == -1) {
				if(sessionStorage.orgId != "31583"){
		    		$(".BCLoader").hide();
		    		$(".normalLoader").show();
		    	} else {
		    		$(".BCLoader").show();
		    		$(".normalLoader").hide();
		    	}
				$(".BCLoader").css({"display":"none"});
				$("#pWait .normalLoader").css({"display":"flex"});
			}
		}catch(e){};
		if(sessionStorage.assessmentMode == "2"){
			if ('serviceWorker' in navigator) {
				  window.addEventListener('load', function() {
					 // console.log("Service Worker!");
				    navigator.serviceWorker.register('console-sw.js').then(function(registration) {
				     //console.log('ServiceWorker registration successful with scope: ', registration.scope);
				    }, function(err) {
				      console.log('ServiceWorker registration failed: ', err);
				    });
				  });
				}
		}
		if(sessionStorage.operatingSystem !=undefined && sessionStorage.operatingSystem.toUpperCase() == "MAC OS X"){
			//$("#remoteProctoringDiv").css({"height":"1px !important"}); //check this livefeed
			//$("#remoteProctoringFrame").css({"height":"1px !important"});
			$("#screenProctoringFrame").css({"height":"1px !important"});
		}
	});

