function checkIsQuesMandAndRevisitNo(){
	if(isComingFromRevisitCheck){
		isComingFromRevisitCheck = false;
		if(mockVar.autoSaveRequired == "true" || mockVar.autoSaveRequired == "false"){
			saveQuestionAutomatically();
		}
	}
	var isQuesMandAndRevisitNo = false;
	if((mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].isOptional== "false") || (mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].isOptional== "true" && mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].isSelected)){
	if(mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].groupAllQuestions == "true"){
		var questions = mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].questions;
		for(var i=0;i<questions.length;i++){
				if(typeof(questions[i].reVisitQues)!='undefined' && questions[i].reVisitQues=='false' && typeof(questions[i].isQuesMand)!= "undefined" && questions[i].isQuesMand=="true"){
					if( questions[i].quesParam.status != "answered" ){
						isQuesMandAndRevisitNo = true;
						break;
					}
				}
		}
	}else{	
		var questions = mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].questions;
		if( (mockVar.curQuesBean.comprehensionId == 0 && mockVar.curQuesBean.laqId == 0) || (mockVar.curQuesBean.comprehensionId != 0  && mockVar.compreLaqQues[quesIdIndexes[mockVar.curQuesBean.comprehensionId]].groupComprehensionLaqQuestions == "false") || (mockVar.curQuesBean.laqId != 0  && mockVar.compreLaqQues[quesIdIndexes[mockVar.curQuesBean.laqId]].groupComprehensionLaqQuestions == "false") ){ 
			if(typeof(mockVar.curQuesBean.reVisitQues)!='undefined' && mockVar.curQuesBean.reVisitQues=='false' && typeof(mockVar.curQuesBean.isQuesMand)!= "undefined" && mockVar.curQuesBean.isQuesMand=="true"){
				if(mockVar.curQuesBean.quesParam.status != "answered" && mockVar.curQuesBean.maxTime!=0){
					isQuesMandAndRevisitNo = true;
				}
			}}else{
				var questions = mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].questions;
				for(var i=0;i<questions.length;i++){
					if((questions[i].comprehensionId == mockVar.curQuesBean.comprehensionId && questions[i].comprehensionId!=0 && mockVar.compreLaqQues[quesIdIndexes[mockVar.curQuesBean.comprehensionId]].compremaxTime !=0 ) || (questions[i].laqId == mockVar.curQuesBean.laqId && questions[i].laqId!=0 && mockVar.compreLaqQues[quesIdIndexes[mockVar.curQuesBean.laqId]].compremaxTime !=0)){
						if(typeof(questions[i].reVisitQues)!='undefined' && questions[i].reVisitQues=='false' && typeof(questions[i].isQuesMand)!= "undefined" && questions[i].isQuesMand=="true"){
							if( questions[i].quesParam.status != "answered" && questions[i].maxTime!=0){
								isQuesMandAndRevisitNo = true;
								break;
					}
				}
				}}
			}
	}
	
	}
	return isQuesMandAndRevisitNo;
}

