function avoidKeyPressing(event){
	if(event.ctrlKey){
		alert('Open in new Tab is disabled.');
		if(event.preventDefault)
			event.preventDefault();
		return false;
	}else if(event.shiftKey){
		alert('Open in new Window is disabled.');
		if(event.preventDefault)
			event.preventDefault();
		return false;
	}else if(typeof(event.altKey)=='undefined'?(event.originalEvent!=undefined?event.originalEvent.altKey:event.originalEvent):event.altKey){
		alert('Saving this link is disabled.');
		if(event.preventDefault)
			event.preventDefault();
		return false;
	}
	return true;
}

