function checkFileExist(filePath){
	var response=true;
	$.ajax({
		type: "POST",
		url: filePath,
		async : false,
		dataType: navigator.userAgent.indexOf('msie')!=-1 ? "text" : "xml",
				success: function(data) {
					if (typeof data == "string") {
						QPxml = new ActiveXObject("Microsoft.XMLDOM");
						QPxml.async = false;
						QPxml.loadXML(data);
					} else {
						QPxml = data;
					}
				},
				error : function(){
					response =  false;
				}
	});
	return response;
}
function readAndReturnXML(filePath,isAssFile){
// alert(filePath);
	var xml="";
	var fileName =  filePath.substr(filePath.lastIndexOf('/')+1,filePath.length);
	//console.log("fileName:::"+fileName);
	//console.log("filePath:::"+filePath);
	if(typeof(fileURL) == "undefined" || typeof(fileURL[fileName])=="undefined" || fileURL[fileName]==undefined){
		$.ajax({
			type: "GET",
			url: filePath,
			async : false,
			dataType: ($.support.msie) ? "text" : "xml",
					success: function(data) {
						if (typeof data == "string") {
							xml = new ActiveXObject("Microsoft.XMLDOM");
							xml.async = false;
							xml.loadXML(data);
							storeAssessmentFile(fileName,xml,isAssFile);
						} else {
							xml = data;
							storeAssessmentFile(fileName,xml,isAssFile);
						}
						// alert(xml);
					},error : function(e){
					// alert('Gone To Error Page');
						//alert(e.status + " :: "+e.responseText);
						console.log("error while getting the data",e);
						setTimeout(function(){
							 window.location.href="error.html?E404"+(($.cookie("isApp")=="true")?"isApp":"")+(($.cookie("isLauncher")=="true")?"isLauncher":"");
						},50);
					}
		});
	}else{
		$.ajax({
			type: "GET",
			url: fileURL[fileName],
			async : false,
			dataType: ($.support.msie) ? "text" : "xml",
					success: function(data) {
						if (typeof data == "string") {
							xml = new ActiveXObject("Microsoft.XMLDOM");
							xml.async = false;
							xml.loadXML(data);
						} else {
							xml = data;
						}
						// alert(xml);
					},error : function(e){
						//console.log("error while getting the data",e);
						delete fileURL[fileName];
						xml = readAndReturnXML(filePath,isAssFile);
					}
		});
	}
	return xml;
}
function alignHeight() {
	var height;
	if($(window).width()<1000){
		$("#header").hide();
		height = $(window).height() - $("#header").height();
	}else{
		height = $(window).height() - ($("#header").height() + $("#footer").height());
	}
	$('#mainleft').css({ "height": height });
	$('#mainright').css({ "height": height });
	$('#feedbackTableDiv').height($('#mainleft').height() - $('#feedBackHeader').outerHeight(true) - $('#submitBtnDiv').outerHeight(true));
}

