	mockVar.AttemptStartTime = (typeof(mockVar.AttemptStartTime) != "undefined" ? mockVar.AttemptStartTime : (typeof(sessionStorage.startTime) != "undefined" ? sessionStorage.startTime : "NA"));
	mockVar.loginId = (typeof(sessionStorage.loginId) != "undefined" ? sessionStorage.loginId : "NA");
	mockVar.emailId = (typeof(sessionStorage.emailId) != "undefined" ? sessionStorage.emailId : "NA");
	mockVar.mobileNum = (typeof(sessionStorage.mobileNum) != "undefined" ? sessionStorage.mobileNum : "NA");
