function displayQuesInstru(){
	$('#viewQuesInstruDiv').hide();
	$('.viewQuesInstruDiv').hide();
	var instructionsShown = false;
	if(mockVar.curQuesBean.comprehensionId!=0){
		var isquesInstru=jQuery.isEmptyObject(compreInstru);
	}
	else  if(mockVar.curQuesBean.laqId!=0){
		var isquesInstru=jQuery.isEmptyObject(laqInstru);
	}
	else
	var isquesInstru=jQuery.isEmptyObject(quesInstru);
	if(typeof(sessionStorage.isAdaptive) == "undefined" || sessionStorage.isAdaptive == "NO" || sessionStorage.isAdaptive == "NA")
		var	isquesShow = showQuesInstructionsQuiz('isQuesShow');
	else
	var	isquesShow = true;
	if(isquesShow==false  && isquesInstru==false && typeof(mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].questions[iOAP.curQues].isQuesVisited)=='undefined' || mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].questions[iOAP.curQues].isQuesVisited === false){
		$('#viewQuesInstruDiv').show();
		$('.viewQuesInstruDiv').show();
		clearTimeout(mockVar.timeCounter);
		if(mockVar.curQuesBean.comprehensionId!=0 ){
		mockVar.timeCounter=compreInstruDetails[mockVar.curQuesBean.comprehensionId]["instructionTime"];
		}
		else if(mockVar.curQuesBean.laqId!=0){
        mockVar.timeCounter= laqInstruDetails[mockVar.curQuesBean.laqId]["instructionTime"];
		}
		else
		mockVar.timeCounter =   quesInstruDetails[mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].questions[iOAP.curQues].quesId]["instructionTime"];
		// mockVar.timeCounter = 60;
		instruTimeCounterForQues(mockVar.timeCounter); 
		showQuesInstructions();
		instructionsShown = true;
	}
	else if(isquesShow==false && isquesInstru==false){
		 $('#viewQuesInstruDiv').show();
		 $('.viewQuesInstruDiv').show();
	}
	if(mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].questions[iOAP.curQues].laqId!=0 && 	mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].questions[iOAP.curQues].laqId!= undefined){
		for(var ques=0; ques<mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].questions.length; ques++){
			if(mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].questions[ques].laqId==mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].questions[iOAP.curQues].laqId)
			mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].questions[ques].isQuesVisited=true;
			if(mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].questions[ques].laqId==mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].questions[iOAP.curQues].laqId && mockVar.compreLaqQues[mockVar.compreLaqQues.inArray(mockVar.curQuesBean.laqId,"quesId")].groupComprehensionLaqQuestions=="true")
			mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].questions[ques].isQuesViewed=true;
		}
	}
	if(mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].questions[iOAP.curQues].comprehensionId!=0 && 	mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].questions[iOAP.curQues].comprehensionId!= undefined){
		for(var ques=0; ques<mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].questions.length; ques++){
			if(mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].questions[ques].comprehensionId==mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].questions[iOAP.curQues].comprehensionId)
			mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].questions[ques].isQuesVisited=true;
			if(mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].questions[ques].comprehensionId==mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].questions[iOAP.curQues].comprehensionId && mockVar.compreLaqQues[mockVar.compreLaqQues.inArray(mockVar.curQuesBean.comprehensionId,"quesId")].groupComprehensionLaqQuestions=="true")
			mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].questions[ques].isQuesViewed=true;
		}
	}
	mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].questions[iOAP.curQues].isQuesVisited=true;
	mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].questions[iOAP.curQues].isQuesViewed=true;
	return instructionsShown;
}

function instruTimeCounterForQues(time){
	/*if(mockVar.ignoreElapsedTime){
		time+=1;
		$(".instruTimeCounter").hide();
	}*/
	mockVar.isQuesInstruPage=1;
	breakTimeStarted = true;
	mockVar.remainingInstruTime=time;
	if(ringTheBell && ringTheBellTimeLeft>0){
		ringTheBellTimeLeft=ringTheBellTimeLeft-1;
	}
	if(ringTheBell && ringTheBellTimeLeft<=0){
		timeOutSubmit();
	}else{
		if(isRightToLeftIsRequired){
			$(".instruTimeCounter").html(convertTime(time,-1, -1, -1) + "<b><span id='grpInstruTimer'>"+mockLabels.grpInstruTimer+"</span> </b>");
		} else {
			$(".instruTimeCounter").html( "<b><span id='grpInstruTimer'>"+mockLabels.grpInstruTimer+"</span> "+convertTime(time,-1, -1, -1)+"</b>");
		}
		if(time>0 && flagToStopQuesInstruTimerOnClickOfProceed== false){
			clearTimeout(mockVar.timeCounter);
			mockVar.timeCounter = setTimeout(function(){instruTimeCounterForQues(time-1);},1000);
			quesInsTimeSpent+=1;
			 if(quesInstruDetails[mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].questions[iOAP.curQues].quesId]["minInstructionTime"]>0){
				 if(quesInstruDetails[mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].questions[iOAP.curQues].quesId]["instructionTime"]-time>=quesInstruDetails[mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].questions[iOAP.curQues].quesId]["minInstructionTime"]){
						$('#proceedToGrpxx').attr('disabled',false);
						if(showSkipBtnForMinWaitTime){
				        $('#skipBtnForProofReadingGrpxx').hide();			
		                }
						if(titleHover)
						$("#proceedToGrpxx").attr("title",$(globalXmlvar).find('ProceedtoNext').text());
					}else{
						$('#proceedToGrpxx').attr('disabled',true);
						if(showSkipBtnForMinWaitTime){
				        $('#skipBtnForProofReadingGrpxx').show();			
		                }
						if(titleHover)
						$("#proceedToGrpxx").attr("title",$(globalXmlvar).find('enabledAfter').text()+convertTime(parseInt(quesInstruDetails[mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].questions[iOAP.curQues].quesId]["minInstructionTime"]-(quesInstruDetails[mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].questions[iOAP.curQues].quesId]["instructionTime"]-time)),-1, -1, -1)+' '+timerFormatLabel);					}
				}else if(Object.keys(compreInstruDetails).length>0 && mockVar.curQuesBean.comprehensionId!=0 && compreInstruDetails[mockVar.curQuesBean.comprehensionId]!=undefined && compreInstruDetails[mockVar.curQuesBean.comprehensionId]["minInstructionTime"]>0){
					 if(compreInstruDetails[mockVar.curQuesBean.comprehensionId]["instructionTime"]-time>=compreInstruDetails[mockVar.curQuesBean.comprehensionId]["minInstructionTime"]){
							$('#proceedToGrpxx').attr('disabled',false);
							if(showSkipBtnForMinWaitTime){
				        $('#skipBtnForProofReadingGrpxx').hide();			
		                }
							if(titleHover)
							$("#proceedToGrpxx").attr("title",$(globalXmlvar).find('ProceedtoNext').text());
						}else{
							$('#proceedToGrpxx').attr('disabled',true);
							if(showSkipBtnForMinWaitTime){
				        $('#skipBtnForProofReadingGrpxx').show();			
		                }
							if(titleHover)
							$("#proceedToGrpxx").attr("title",$(globalXmlvar).find('enabledAfter').text()+convertTime(parseInt(compreInstruDetails[mockVar.curQuesBean.comprehensionId]["minInstructionTime"]-(compreInstruDetails[mockVar.curQuesBean.comprehensionId]["instructionTime"]-time)),-1, -1, -1)+' '+timerFormatLabel);					}
				}
				else if(Object.keys(laqInstruDetails).length>0 && mockVar.curQuesBean.laqId!=0 && laqInstruDetails[mockVar.curQuesBean.laqId]!=undefined && laqInstruDetails[mockVar.curQuesBean.laqId]["minInstructionTime"]>0){
					 if(laqInstruDetails[mockVar.curQuesBean.laqId]["instructionTime"]-time>=laqInstruDetails[mockVar.curQuesBean.laqId]["minInstructionTime"]){
							$('#proceedToGrpxx').attr('disabled',false);
							if(showSkipBtnForMinWaitTime){
				        $('#skipBtnForProofReadingGrpxx').hide();			
		                }
							if(titleHover)
							$("#proceedToGrpxx").attr("title",$(globalXmlvar).find('ProceedtoNext').text());
						}else{
							$('#proceedToGrpxx').attr('disabled',true);
							if(showSkipBtnForMinWaitTime){
				        $('#skipBtnForProofReadingGrpxx').show();			
		                }
							if(titleHover)
							$("#proceedToGrpxx").attr("title",$(globalXmlvar).find('enabledAfter').text()+convertTime(parseInt(laqInstruDetails[mockVar.curQuesBean.laqId]["minInstructionTime"]-(laqInstruDetails[mockVar.curQuesBean.laqId]["instructionTime"]-time)),-1, -1, -1)+' '+timerFormatLabel);					}
				}	
			 else{
					$('#proceedToGrpxx').attr('disabled',false);
					if(showSkipBtnForMinWaitTime){
				        $('#skipBtnForProofReadingGrpxx').hide();			
		                }
					if(titleHover)
					$("#proceedToGrpxx").attr("title",$(globalXmlvar).find('ProceedtoNext').text());
				}
		}else if(flagToStopQuesInstruTimerOnClickOfProceed==false){
			mockVar.isQuesInstruPage=0;
			$('#proceedToGrpxx').attr('disabled',false);
			if(showSkipBtnForMinWaitTime){
				        $('#skipBtnForProofReadingGrpxx').show();			
		                }
			if(titleHover)
			$("#proceedToGrpxx").attr("title",$(globalXmlvar).find('ProceedtoNext').text());
		document.getElementById("proceedToGrpxx").click();
		}
	}
}

