function candidateOptionSequence(){	
	var optionSequence;
	var optionNoSequence;
	var optionValueSequence="";
	
	for(var g=0;g<mockVar.groups.length;g++){
		var group =  mockVar.groups[g];
		for(var s=0;s<group.secDetails.length;s++){
			var section = group.secDetails[s];
			var questions = section.questions;
			for(var q=0;q<questions.length;q++){
				optionSequence="";
				optionNoSequence="";
				optionValueSequence="";
				var question = questions[q];
				var options = question.options.length;
				mockVar.langIndex= mockVar.languages[o]!=undefined &&( mockVar.languages[o]== mockVar.langName)? o:-1;
				if(options==0){
					optionSequence="NA";
					optionNoSequence="NA";
					optionValueSequence="NA";
					
				}
				else
				{
					for(var o=0;o<options;o++){
						k = o+1;
						optionSequence = optionSequence+question.options[o].optId+" ";
						optionNoSequence = optionNoSequence+k+" ";
						if(o==0)
							{
							 optionValueSequence=(typeof(qpDetailsMockVar[question.quesId]!="undefined")?qpDetailsMockVar[question.quesId].options[question.options[o].optId].optLangBean[0].optText:question.options[question.options[o].optId].optLangBean[0].optText);
							}
						else
							{
						optionValueSequence=optionValueSequence+"@#tcsionoptionseperator#@"+(typeof(qpDetailsMockVar[question.quesId]!="undefined")?qpDetailsMockVar[question.quesId].options[question.options[o].optId].optLangBean[0].optText:question.options[question.options[o].optId].optLangBean[0].optText);
							}
					}
				}
				question.optionSequence= optionSequence.trim().replace(/ /g,";");
				question.optionNoSequence = optionNoSequence.trim().replace(/ /g,",");
				question.optionValueSequence = optionValueSequence;
			}
		}
	}}
