//sreejith ckeditor new 

function editCKEditor(CKEDITOR,id){
	var editor = CKEDITOR.instances[id];
	if (!editor) return;
	 editor.on('contentDom', function () {
		 var elem = document.querySelector('#quesAnsContent') || document.body;
		 var computedStyle = getComputedStyle(elem);
		  
		 editor.document.getBody().setStyles({
		 'font-family': computedStyle.fontFamily,
		 'font-size': '14px'
		 });
		if(quesIdIndexes[editor.name.split("answer")[1]]==0)//focus only for the first question not for the last question incase of groupallquestions.
	        	editor.focus();
	    attachEventsToEditable(editor);
	    });
	 
	  editor.on('contentDomUnload', function () {
		  detachEventsFromEditable(editor);
	    });
	  

	  editor.on('destroy', function () {
	          detachEventsFromEditable(editor);
	      });

	
	
}


function attachEventsToEditable(editor) {
    var editable = editor.editable ? editor.editable() : null;
    if (!editable) return;
    
    detachEventsFromEditable(editor);
    

    var handlers = {
            keyup: function (evt) { onKeyUpHandler(evt, editor); },
            mouseup: function (evt) { onMouseUpHandler(evt, editor); },
            focus: function (evt) { onFocusHandler(evt, editor); }
        };

    
    editor._editableHandlers = handlers;
    

    editable.on('keyup', handlers.keyup);
    editable.on('mouseup', handlers.mouseup);
    editable.on('focus', handlers.focus)

}


function detachEventsFromEditable(editor){
	    var editable = editor.editable ? editor.editable() : null;
	    var handlers = editor._editableHandlers;
	    if (editable && handlers) {
	    	try{
	      editable.removeListener('keyup', handlers.keyup);
	      editable.removeListener('mouseup', handlers.mouseup);
	      editable.removeListener('focus', handlers.focus);
	    	}
	    	catch(e){
	    		console.warn('detachEventsFromEditable error:', e);
	    	}
	    }
	    editor._editableHandlers = null;
}

function onKeyUpHandler(evt, editor) {
    run1(editor);
}

function onFocusHandler(evt, editor) {
    run1(editor);
}


function onMouseUpHandler(evt, editor) {
	var target = evt.data && evt.data.getTarget ? evt.data.getTarget() : null;
	if(target && target.is('button') && target.getAttribute('id')==='pasteBtncke')
	{
		run1(editor);
		insertTextAtCaret(editor.document.$.getElementById('pasteBtncke'));
		
	}
	else
		run1(editor);
}

