		var tempId = typeof($(".comprePositionClass div").attr("id")) != "undefined" ? $(".comprePositionClass div").attr("id") : "";
		var tempClass = typeof($(".comprePositionClass div").attr("class")) != "undefined" ? $(".comprePositionClass div").attr("class") : "";
