function markFlagForRevisitQuestion(curGroupCompreQues,count){
	i = 0;
	while(i<count){if(iOAP.secDetails[iOAP.curSection].questions[curGroupCompreQues].reVisitQues =='false' && iOAP.secDetails[iOAP.curSection].isOptional == 'true' && iOAP.secDetails[iOAP.curSection].isSelected && iOAP.secDetails[iOAP.curSection].questions[curGroupCompreQues].flagforReVistQues ==true){
		iOAP.secDetails[iOAP.curSection].questions[curGroupCompreQues].flagforReVistQues=false;
		iOAP.secDetails[iOAP.curSection].secCount=iOAP.secDetails[iOAP.curSection].secCount+1;
	}
	else if(iOAP.secDetails[iOAP.curSection].questions[curGroupCompreQues].reVisitQues =='false' && iOAP.secDetails[iOAP.curSection].isOptional == 'false' && iOAP.secDetails[iOAP.curSection].questions[curGroupCompreQues].flagforReVistQues ==true){
		iOAP.secDetails[iOAP.curSection].questions[curGroupCompreQues].flagforReVistQues=false;
		iOAP.secDetails[iOAP.curSection].secCount=iOAP.secDetails[iOAP.curSection].secCount+1;
	}
	if(!iOAP.secDetails[iOAP.curSection].questions[curGroupCompreQues].isQuesViewed && iOAP.secDetails[iOAP.curSection].secCount==iOAP.secDetails[iOAP.curSection].questions.length)
		mockVar.groups[mockVar.currentGrp].groupCount = mockVar.groups[mockVar.currentGrp].groupCount+1;
	curGroupCompreQues+=1;
	i+=1;
	}

}
