function fillSEQQues(compQues){
	var curQues = iOAP.curQues,
	str='',
	curSection = iOAP.secDetails[iOAP.curSection],
	compQuesText = (typeof(qpDetailsMockVar[compQues.quesId]) != "undefined" ? qpDetailsMockVar[compQues.quesId].quesLangBean[mockVar.langIndex].quesText : compQues.langData[mockVar.langIndex].quesText),
	quesOpts = curSection.questions[curQues].options,
	quesArr = new Array(),
	//correctseqques=curSection.questions[curQues].correctSeq,
	opnIdFound = false,opnIdValue=0;
	if(mockVar.enableVoiceOver=='YES'){
		inputTxt= formQuestionTextForVoiceOver(compQuesText);
	}
	if(compQuesText.indexOf('hasmedia@@')!=-1){
		compQuesText=replaceQuesText(compQuesText);}
	try{
		if(typeof(mockVar.compreLaqQues[quesIdIndexes[mockVar.curQuesBean.comprehensionId]].isShuffled)=="undefined" ){ //rakesh changes -- shuffling of options in seq type questions
		/*if(typeof(sessionStorage.isAdaptive)!="undefined" && sessionStorage.isAdaptive !="NO" && sessionStorage.isAdaptive !="NA" && typeof(mockVar.curQuesBean.arrayshuffled) == "undefined"){*/
			if(typeof(mockVar.compreLaqQues[quesIdIndexes[mockVar.curQuesBean.comprehensionId]].correctseq)!="undefined" && mockVar.compreLaqQues[quesIdIndexes[mockVar.curQuesBean.comprehensionId]].correctseq.length>0){
				quesOpts.sortBy('optId');
				for(var i=0;i<mockVar.compreLaqQues[quesIdIndexes[mockVar.curQuesBean.comprehensionId]].correctseq.length;i++){
					quesArr[mockVar.compreLaqQues[quesIdIndexes[mockVar.curQuesBean.comprehensionId]].correctseq[i]-1]=quesOpts[i];
				}
				quesOpts=[].concat(quesArr);
			}else{
				quesOpts = shuffleArray(quesOpts);
			
			}
			if(mockVar.compreLaqQues[quesIdIndexes[mockVar.curQuesBean.comprehensionId]].actualseq ==undefined){
				mockVar.compreLaqQues[quesIdIndexes[mockVar.curQuesBean.comprehensionId]].actualseq = quesOpts;
				}
			
			mockVar.compreLaqQues[quesIdIndexes[mockVar.curQuesBean.comprehensionId]].isShuffled = true;
			iOAP.secDetails[iOAP.curSection].questions[curQues].options = quesOpts;
		}
		/*if(mockVar.compreLaqQues[quesIdIndexes[mockVar.curQuesBean.comprehensionId]].actualseq !=undefined){
			quesOpts = mockVar.compreLaqQues[quesIdIndexes[mockVar.curQuesBean.comprehensionId]].actualseq ;
		}*/
	}catch(e){}
	mandatoryText = curSection.questions[curQues].isQuesMand == 'true' ? '<span style="color:red">* </span>':'';
	var textHighlighterGrpSecQuesId = mockVar.currentGrp+"_"+iOAP.curSection+"_"+(mockVar.compreLaqQues.inArray(compQues.quesId, 'quesId'))+"_"+mockVar.langIndex+"_CompreTextSelection";
	var displyQuesNo=curSection.questions[curQues].displayQuestionNo;
	var startQuesNo=(isOnline == 1 ? (curQues+1):mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].questions[iOAP.curQues].sequenceNumber);
	var endQuesNo=(isOnline == 1 ? (curQues+quesOpts.length):(mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].questions[iOAP.curQues].sequenceNumber + quesOpts.length - 1));
	var tempOpnIdValArray = [];
	str += '<div id="quesOuterDiv" style="clear:both">';
	str += '<div class="leftDiv" style="width:99.6%">';
	if(typeof(displyQuesNo) == "undefined" || displyQuesNo == "true" || displyQuesNo == ""){
		str +="<div role='heading' aria-level='2' class='divHeader'>";
		str +="<b><span aria-label='question number' class='questionNumber langLabel'>"+mandatoryText+""+mockLabels.questionNo+"</span>.<span id='startQ'>"+startQuesNo+"<span> - <span aria-label='question number' class='questionNumber langLabel'>"+mockLabels.questionNo+"</span>.<span id='endQ'>"+endQuesNo+"<span></b>";
		str +="</div>";
	}
	str +='<div align="right" style="float:right;"><a  href="javascript:;" id="scrollToBottom" title="Scroll Down" onclick="scrollToBottom()"><img width="28" height="28" align="right" alt="" src="images/Down.png" style=""></a></div>';
	str += "<div class='Ans_Area' style='clear:both;padding:5px'>";
	var hasOptionReplacement=compQuesText.indexOf('<ReplaceResponsePlaceHolder>')!=-1?true:false;
	hasOptionPlaceHolderPresentInQuestion = hasOptionReplacement;
	if(hasOptionReplacement)
		compQuesText = fillOptionPlaceHolders(compQuesText,quesOpts,"","SEQ","","","","",curSection.questions[curQues].quesId);
	str += '<div id="sequence_ques_text" class="compreText textHighlighter '+textHighlighterGrpSecQuesId+' '+(compQues.quesId)+'_QuesId" >'+voiceOverHtml+compQuesText+'</div>';
	if(!hasOptionReplacement){
		
	str +='<div class="que no-sec SEQQuestionDiv"><div class="que-col-full que-drag" id="fill-sequence-div"><ol role="list" aria-labelledby="sequence_ques_text" id="sortable" class="ui-sortable">';
	for(var i=0;i<quesOpts.length;i++){
		str += '<li role="listitem" aria-posinset="'+(i+1)+'" aria-setsize="'+quesOpts.length+'" aria-label="item '+(i+1)+'"  class="ui-state-default" onkeydown = "javascript: sequenceDrag(this, event);" tabindex="0" id="answers'+curSection.questions[curQues].quesId+'"><span class="listyle"></span>';
		slectedOpnId = curSection.questions[curQues].quesParam.selectedOptId;
		for(var j=0;j<quesOpts.length;j++){
			if(slectedOpnId!="" && quesOpts[j].optId==slectedOpnId){
				opnIdFound = true;
				opnIdValue = j;
				break;
			}
		}
		if(opnIdFound === true){
			if(!tempOpnIdValArray.includes(quesOpts[opnIdValue].optId)){
			str += '<span value="'+quesOpts[opnIdValue].optId+'" id="optionid_'+quesOpts[opnIdValue].optId+'">'+replaceQuesText((typeof(qpDetailsMockVar[curSection.questions[curQues].quesId]) != "undefined" ? qpDetailsMockVar[curSection.questions[curQues].quesId].options[quesOpts[opnIdValue].optId].optLangBean[mockVar.langIndex].optText :  quesOpts[opnIdValue].optLangBean[mockVar.langIndex].optText))+'</span></li>';
			opnIdFound = false;  
			tempOpnIdValArray.push(quesOpts[opnIdValue].optId);
			}
		}else{
			if(!tempOpnIdValArray.includes(quesOpts[i].optId)){
			str += '<span value="'+quesOpts[i].optId+'" id="optionid_'+quesOpts[i].optId+'">'+replaceQuesText((typeof(qpDetailsMockVar[curSection.questions[curQues].quesId]) != "undefined" ? qpDetailsMockVar[curSection.questions[curQues].quesId].options[quesOpts[i].optId].optLangBean[mockVar.langIndex].optText : quesOpts[i].optLangBean[mockVar.langIndex].optText))+'</span></li>';
			tempOpnIdValArray.push(quesOpts[i].optId);
			}
		}
		curQues++;	
	}
	str += '</ol></div></div>';
	}
		str += 	'</div><div align="right" style="float:right;clear:both"><a onclick="scrollToTop()" title="Scroll Up" id="scrollToTop"><img width="30" height="30" alt="" style="" src="images/Up.png"></a></div>';

	str +='</div></div>';
	setTimeout(function(){try{
		if(compQues.isVertical != "null" && compQues.isVertical != undefined && compQues.isVertical != "vertical" && compQues.additionalQuesType == "SEQUENCE"){
			sortingAxis = "x";
		} else {
			sortingAxis="y";
		}
		$("#sortable").sortable("destroy");//writing this to remove previously binded sortable;
		bindSequenceQuestionSortable();
		dynamicNumberingForSeq(true);
	}catch(e){bindSequenceQuestionSortable();dynamicNumberingForSeq(true);}},20);
	return str;
}
