function fillMTCQues(compQues,columnType,childQues){
	var curQues = iOAP.curQues,
	str='',
	curSection = iOAP.secDetails[iOAP.curSection],
	opnIdFound = false,opnIdValue='0',
	compQuesText = (typeof(qpDetailsMockVar[compQues.quesId]) != "undefined" ? qpDetailsMockVar[compQues.quesId].quesLangBean[mockVar.langIndex].quesText : compQues.langData[mockVar.langIndex].quesText),
	quesOpts = curSection.questions[curQues].options;
	if(mockVar.enableVoiceOver=='YES'){
		inputTxt= formQuestionTextForVoiceOver(compQuesText);
	}
	if(compQuesText.indexOf('hasmedia@@')!=-1){
		compQuesText=replaceQuesText(compQuesText);}
	mandatoryText = curSection.questions[curQues].isQuesMand == 'true' ? '<span style="color:red">* </span>':'';
	var textHighlighterGrpSecQuesId = mockVar.currentGrp+"_"+iOAP.curSection+"_"+(mockVar.compreLaqQues.inArray(compQues.quesId, 'quesId'))+"_"+mockVar.langIndex+"_CompreTextSelection";
	var otherOptCount=0;
	var tempOpnIdValArray = [];
	var regex = /(.+?)<left_column_tag>(.+?)<left_column_tag>.*<right_column_tag>(.+?)<right_column_tag>/g;
	var MTCParam = regex.exec(compQuesText);
	var compQuesText = MTCParam[1];
	var leftColName = MTCParam[2];
	var rightColName = MTCParam[3];
	var displyQuesNo=curSection.questions[curQues].displayQuestionNo;
	var startQuesNo=(isOnline == 1 ? (curQues+1):mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].questions[iOAP.curQues].sequenceNumber);
	var endQuesNo=(isOnline == 1 ? (curQues+childQues):(mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].questions[iOAP.curQues].sequenceNumber + childQues -1));
	// var endQuesNo=curQues+childQues;
	str += '<div id="quesOuterDiv" style="clear:both">';
	str += '<div class="leftDiv" style="width:99.6%">';
	if(typeof(displyQuesNo) == "undefined" || displyQuesNo == "true" || displyQuesNo == ""){
		str +="<div role='heading' aria-level='2' class='divHeader'>";
		if(startQuesNo == endQuesNo)
			str +="<b><span aria-label='question number' class='questionNumber langLabel'>"+mandatoryText+""+mockLabels.questionNo+"</span>.<span id='startQ'>"+startQuesNo+"<span></b>";
		else
			str +="<b><span aria-label='question number' class='questionNumber langLabel'>"+mandatoryText+""+mockLabels.questionNo+"</span>.<span id='startQ'>"+startQuesNo+"<span> - <span aria-label='question number' class='questionNumber langLabel'>"+mockLabels.questionNo+"</span>.<span id='endQ'>"+endQuesNo+"<span></b>";
		str +="</div>";
	}
	str +='<div align="right" style="float:right;"><a  href="javascript:;" id="scrollToBottom" title="Scroll Down" onclick="scrollToBottom()"><img width="28" height="28" align="right" alt="" src="images/Down.png" style=""></a></div>';
	str += "<div class='Ans_Area' style='clear:both;padding:5px'>";
	str += '<div class="compreText MTCQuestion textHighlighter '+textHighlighterGrpSecQuesId+' '+compQues.quesId+'_QuesId" aria-live="off">'+voiceOverHtml+compQuesText+'</div>';
	str += '<div class="que"><div class="que-col"><h4 id="left_column_tag_id" class="left_column_tag">'+leftColName+'</h4><ol>';
	var tempChildQuestionText = "";
	var tempChildQuestionQuestionId = "";
	for(var i=0;i<childQues;i++){
		tempChildQuestionText = "";
		//tempChildQuestionQuestionId = curSection.questions[curQues].quesId;
		tempChildQuestionText = (typeof(qpDetailsMockVar[curSection.questions[curQues].quesId]) != "undefined" ? qpDetailsMockVar[curSection.questions[curQues].quesId].quesLangBean[mockVar.langIndex].quesText :  curSection.questions[curQues].quesLangBeans[mockVar.langIndex].quesText);
		str += '<li id="MTC'+curSection.questions[curQues].quesId+'" class="MTC'+compQues.quesId+'">'+ replaceQuesText(tempChildQuestionText) +'</li>';
		curQues++;	
	}
	curQues = iOAP.curQues;
	str += '</ol></div>';
	if(columnType === "drag"){
		var prevcurQues =0;
		str += '<div id="mtc-drag" class="que-col  que-drag"><h4 id="right_column_tag_id" class="right_column_tag">'+rightColName+'</h4><ul aria-labelledby="right_column_tag_id" role="list" id="sortable" class="ui-sortable">';
		for(var i=0;i<childQues;i++){
			str += '<li role="listitem" aria-posinset="'+(i+1)+'" aria-setsize="'+childQues+'" aria-label="item '+(i+1)+'"  class="ui-state-default" onkeydown = "javascript: sortableKeyboard(this, event);" tabindex="0" id="answers'+curSection.questions[curQues].quesId+'">';
			slectedOpnId = curSection.questions[curQues].quesParam.selectedOptId;
			for(var j=0;j<quesOpts.length;j++){
				if(slectedOpnId!="" && quesOpts[j].optId==slectedOpnId){
					opnIdFound = true;
					opnIdValue = j;

					break;
				}
			}
			if(opnIdFound === true){
				if(!tempOpnIdValArray.includes(quesOpts[opnIdValue].optId)){
				str += '<div class="ui-icon-grip"></div><span value="'+quesOpts[opnIdValue].optId+'">'+replaceQuesText((typeof(qpDetailsMockVar[curSection.questions[curQues].quesId]) != "undefined" ? qpDetailsMockVar[curSection.questions[curQues].quesId].options[quesOpts[opnIdValue].optId].optLangBean[mockVar.langIndex].optText : quesOpts[opnIdValue].optLangBean[mockVar.langIndex].optText))+'</span></li>';
				opnIdFound = false;  
				tempOpnIdValArray.push(quesOpts[opnIdValue].optId);
				}
			}else{
				if(!tempOpnIdValArray.includes(quesOpts[i].optId)){
				str += '<div class="ui-icon-grip"></div><span value="'+quesOpts[i].optId+'">'+replaceQuesText((typeof(qpDetailsMockVar[curSection.questions[curQues].quesId]) != "undefined" ? qpDetailsMockVar[curSection.questions[curQues].quesId].options[quesOpts[i].optId].optLangBean[mockVar.langIndex].optText : quesOpts[i].optLangBean[mockVar.langIndex].optText))+'</span></li>';
				tempOpnIdValArray.push(quesOpts[i].optId);
				}
			}
			prevcurQues = curQues;
			curQues++;
			otherOptCount = i;		   
		}
		otherOptCount++;
		var extraOptions = true;
		for(var i=0;i<quesOpts.length;i++){
			for(var j=0;j<tempOpnIdValArray.length;j++){
				if(quesOpts[i].optId==tempOpnIdValArray[j]){
					extraOptions = false;
					break;
				}else{
					extraOptions = true;
				}
			}
			if(extraOptions){
				str += '<li class="ui-state-default" onkeydown = "javascript: sortableKeyboard(this, event);">';
				str += '<div class="ui-icon-grip"></div><span value="'+quesOpts[i].optId+'">'+replaceQuesText((typeof(qpDetailsMockVar[curSection.questions[prevcurQues].quesId]) != "undefined" ? qpDetailsMockVar[curSection.questions[prevcurQues].quesId].options[quesOpts[i].optId].optLangBean[mockVar.langIndex].optText : quesOpts[i].optLangBean[mockVar.langIndex].optText))+'</span></li>';
			}
		}
		str += '</ul></div></div></div><div align="right" style="float:right;clear:both"><a onclick="scrollToTop()" title="Scroll Up" id="scrollToTop"><img width="30" height="30" alt="" style="" src="images/Up.png"></a></div>';
		str +='</div></div>';
	}else if(columnType === "dropdown"){
		str += '<div class="que-col  que-dd"><h4 id="right_column_tag_id" class="right_column_tag">'+rightColName+'</h4><ul>';
		str += fillSeqMCQ(quesOpts,curSection,curQues,childQues);
		str += '</ul></div></div></div><div align="right" style="float:right;clear:both"><a onclick="scrollToTop()" title="Scroll Up" id="scrollToTop"><img width="30" height="30" alt="" style="" src="images/Up.png"></a></div>';
		str +='</div></div>';
	}
	return str;
}

