var allowedChars = new Array("+","-");

function numPadValidate(text) {
	var proceed = true;
	for(var i=0;i<allowedChars.length;i++){
		if(text.indexOf(allowedChars[i])>0){
			proceed=false;
		}
		if(text.split(allowedChars[i]).length>2){
			proceed = false;
		}
	}
	if(text.indexOf('.') > -1){
		var afterDot = text.split(".");
		if(afterDot.length==2){
			if(afterDot[1].length>2)
				proceed=false;
		}else if(afterDot.length>2){
			proceed=false;
		}
	}
	return proceed;
}
function closeHandsOnApp(res){
	$("#handsOn").hide();
	var tempStatus = "NA";
	handsOnCloseCallByHandsON = false;
	var response = res.split("_")[0];
	var tempQuestId = res.split("_")[1];
	handsOnProgrammingStatus = response;
	if(tempQuestId == iOAP.secDetails[iOAP.curSection].questions[iOAP.curQues].quesId){
		tempStatus = response == "Attempted" ? "answered" : iOAP.secDetails[iOAP.curSection].questions[iOAP.curQues].quesParam.status;	
		closeHandsOnAudit(mockVar.groups[mockVar.currentGrp].groupId,iOAP.secDetails[iOAP.curSection].secId,iOAP.secDetails[iOAP.curSection].questions[iOAP.curQues].quesId,currentGroupIndex,currentSectionIndex,iOAP.curQues,tempStatus,iOAP.secDetails[iOAP.curSection].questions[iOAP.curQues].timespent,response);

		if(response == "Attempted"){
			// mockVar.curQuesBean.quesParam.status = "answered";
			//auditlogCreation("Programming Ques","Programming question attempted successfully","Programming"); 
			executeCode();
			saveBackUp(false);//backup is called in order to avoid any loss of candidate data 
		} else if(response == "Next"){
			//closeHandsOnAudit(grpId,secId,quesId,tempCurrentGroupIndex,tempcurrentSectionIndex,tempGroupSecQuesIndex,status,timespent,actionDesc);
			fnSubmit('submitPrograming');
			fnSubmit('NEXT'); //changing as on attempted received not to move to next question
		}else if(response == "Attemptedandnext"){
			//if in future needed for programming post message
		}
		
	} else {
		
		var searchId = tempQuestId; 
		var questionObjectDetails = questionArr.find(function (item) {
			  return item.quesId === searchId;
			}); 
		var tempGrpId = questionObjectDetails.groupId;
		var tempGrpIndex = (mockVar.groups).findIndex(function (item) {
			  return item.groupId === tempGrpId;
			});
		var tempSectionId = questionObjectDetails.sectionId;
		var tempSecIndex = (mockVar.groups[tempGrpIndex].secDetails).findIndex(function (item) {
			  return item.secId === tempSectionId;
			});
		if(response == "Attempted"){
			mockVar.groups[tempGrpIndex].secDeails[tempSecIndex].questions[quesIdIndexes[tempQuestId]].quesParam.status="answered";
			mockVar.groups[tempGrpIndex].secDeails[tempSecIndex].questions[quesIdIndexes[tempQuestId]].quesParam.answer="--";
			mockVar.groups[tempGrpIndex].secDeails[tempSecIndex].questions[quesIdIndexes[tempQuestId]].quesParam.selectedOptId="";
			mockVar.groups[tempGrpIndex].secDeails[tempSecIndex].questions[quesIdIndexes[tempQuestId]].quesParam.isMarked=0;
			tempStatus = "answered";
		} else {
			tempStatus = mockVar.groups[tempGrpIndex].secDeails[tempSecIndex].questions[quesIdIndexes[tempQuestId]].quesParam.status;
		}
		var timeSpent = mockVar.groups[tempGrpIndex].secDeails[tempSecIndex].questions[quesIdIndexes[tempQuestId]].timespent;
		closeHandsOnAudit(tempGrpId,tempSectionId,tempQuestId,tempGrpIndex,tempSecIndex,quesIdIndexes[tempQuestId],tempStatus,timespent,response);
		}
	
	
	// $("#handsOn").css({"top":"0px","position":"absolute","display":"none"});
	// $("#handsOnAppWindow").attr("src","");
		
	// submitConfirmation('submit');
	
}

function closeHandsOnAudit(grpId,secId,quesId,tempCurrentGroupIndex,tempcurrentSectionIndex,tempGroupSecQuesIndex,status,timespent,actionDesc){
	var AuditJsonObject = new Object();
	AuditJsonObject.ActionName = "Programming Question";
	AuditJsonObject.ActionValue = "Programming Question";
	AuditJsonObject.ActionDesc = actionDesc;
	AuditJsonObject.GroupId = grpId;
	var currentDate = new Date();
	AuditJsonObject.Time = currentDate.yyyymmddHHmmss();
	AuditJsonObject.eventTimestamp = Date.now();
	AuditJsonObject.SectionId = secId;
	AuditJsonObject.QuestionId = quesId;
	AuditJsonObject.GroupIndex = tempCurrentGroupIndex;
	AuditJsonObject.SectionIndex = tempcurrentSectionIndex;
	AuditJsonObject.QuestionIndex = tempGroupSecQuesIndex;
	AuditJsonObject.quesType = "PROGRAMMING TEST";
	AuditJsonObject.status = status;
	AuditJsonObject.answer = "NA";
	AuditJsonObject.isMarked=0;
	AuditJsonObject.timespentInSeconds = timespent;
	AuditJsonObject.OptionSequence = "NA";	
	AuditJsonObject.Status = status;
	AuditJsonObject.SelectedOptionId = "NA";
	AuditJson.push(AuditJsonObject);
}
