function launchHandsOnApp(ques,quesId){
	var str = "";var xmlURL ="";var handsURL ="";
	var waterMarkString='';
	if(mockVar.WaterMark){
		waterMarkString='&showWaterMark=true&waterMark='+sessionStorage.waterMarkId;
	}else
		waterMarkString='&showWaterMark=false&waterMark=NA';
	if(programmingTime <= 5 ){
		if(sessionStorage.launchProgrammingType==undefined || sessionStorage.launchProgrammingType=='false')
			xmlURL = "/IBACC/MockCandidateAction.do?action=getMtopKey&orgId="+(mockVar.userOrgId!=undefined?mockVar.userOrgId:mockVar.orgId)+"&candidateIds="+(mockVar.candidate_Id);
		else
			xmlURL = "/IBACC/MockCandidateAction.do?action=getMtopKey&orgId="+(mockVar.userOrgId!=undefined?mockVar.userOrgId:mockVar.orgId)+"&candidateIds="+(sessionStorage.gblUserid);
		$.ajax({
		url:xmlURL,
		type: 'POST',
		async: false,
		dataType: 'text',
		success: function (data) {
			// console.log(data);
			programmingTime = 175;
			programmingMtopKey = data;
			// console.log("quesId "+quesId);
			fnSubmitCallRequired = true;
			if(sessionStorage.vm_url!="NA" || sessionStorage.handson_url!="NA")
				handsURL = sessionStorage.idlDomainURL+((sessionStorage.vm_url != "NA" && mockVar.curQuesBean.programmingLanguageName=="External VM Env")?sessionStorage.vm_url:sessionStorage.handson_url)+data+"&ques_id="+quesId+"&qpId="+mockVar.qpId+"&alm_assessment_id="+mockVar.mockId;
			else{
				var handsonURL="/LX/hands_on/launch_handson_event?content_player=true&map_id=&handsonid=&map_type=Hands-on&key=true&app_id=9519&mtop_sec_key=";
				handsURL = sessionStorage.idlDomainURL+handsonURL+data+"&ques_id="+quesId+"&qpId="+mockVar.qpId+"&alm_assessment_id="+mockVar.mockId;
			}
			mockVar.handsonid = sessionStorage.handsonid;
			if(sessionStorage.operatingSystem !=undefined && sessionStorage.operatingSystem.toUpperCase() == "ANDROID" || sessionStorage.operatingSystem.toUpperCase() == "IOS")
				handsURL = handsURL +"&mtop_launch=true";
			handsOnCloseCallByHandsON = true;
			if(mockVar.curQuesBean.quesParam!=undefined && mockVar.curQuesBean.quesParam.status=='answered')
				handsURL = handsURL +"&attempted=true";
			handsURL = handsURL+waterMarkString;
			handsURL = handsURL+(($.cookie("isLauncher")=="true")?"&isLauncher=true":"&isLauncher=false");
			if(quesId.indexOf(",") > 0){
				str = '<iframe id="handsOnAppWindow" src="'+handsURL+'" style="width:100%;height:99%;border:none !important"></iframe>';
			} else {
				$('#currentQues').html('<div  id="quesOuterDiv"><div  class="leftDiv" style="width:100%"><div class="refresh-message" style="display:none;">Content failed to load. Please click refresh to try again. <button onclick="refreshProgramConsole()">Refresh</button></div><iframe id="handsOnAppWindow" src="'+handsURL+'" style="width:100%;height:99%;border:none !important"></iframe></div></div>');
				}
			setTimeout(function(){
			if(mockVar.curQuesBean.quesType == "PROGRAMMING TEST" && ((typeof(sessionStorage.launchProgrammingType)!=undefined && sessionStorage.launchProgrammingType=='true') || sessionStorage.handson_url != "NA" || (sessionStorage.vm_url != "NA" && mockVar.curQuesBean.programmingLanguageName=="External VM Env")))
				$($(".Bttn_Area").children()).each(function(){if($(this).attr("class").indexOf("finalSubmit") == -1) $(this).hide();});
			quizPageHeight();
},10);
			setTimeout(function(){$(".refresh-message").show();},5000);
		},
		error : function(){
			
		}
	});
	} else {
		if(sessionStorage.idlDomainURL!="NA" &&(sessionStorage.vm_url!="NA" || sessionStorage.handson_url!="NA"))
			handsURL = sessionStorage.idlDomainURL+((sessionStorage.vm_url != "NA" && mockVar.curQuesBean.programmingLanguageName=="External VM Env")?sessionStorage.vm_url:sessionStorage.handson_url)+programmingMtopKey+"&ques_id="+quesId+"&qpId="+mockVar.qpId+"&alm_assessment_id="+mockVar.mockId;
		else{
			var handsonURL="/LX/hands_on/launch_handson_event?content_player=true&map_id=&handsonid=&map_type=Hands-on&key=true&app_id=9519&mtop_sec_key=";
			handsURL = sessionStorage.idlDomainURL+handsonURL+programmingMtopKey+"&ques_id="+quesId+"&qpId="+mockVar.qpId+"&alm_assessment_id="+mockVar.mockId;
		}
		handsOnCloseCallByHandsON = true;
		fnSubmitCallRequired = true;
		if(mockVar.curQuesBean.quesParam!=undefined && mockVar.curQuesBean.quesParam.status=='answered')
			handsURL = handsURL +"&attempted=true";
		handsURL = handsURL+waterMarkString;
		handsURL = handsURL+(($.cookie("isLauncher")=="true")?"&isLauncher=true":"&isLauncher=false");
		if(quesId.indexOf(",") > 0){
			str = '<iframe id="handsOnAppWindow" src="'+handsURL+'" style="width:100%;height:99%;border:none !important"></iframe>';
		} else {
			$('#currentQues').html('<div  id="quesOuterDiv"><div  class="leftDiv" style="width:100%"><div class="refresh-message" style="display:none;">Content failed to load. Please click refresh to try again. <button onclick="refreshProgramConsole()">Refresh</button></div><iframe id="handsOnAppWindow" src="'+handsURL+'" style="width:100%;height:99%;border:none !important"></iframe></div></div>');
			} setTimeout(function(){
		if(mockVar.curQuesBean.quesType == "PROGRAMMING TEST" && ((typeof(sessionStorage.launchProgrammingType)!=undefined && sessionStorage.launchProgrammingType=='true') || sessionStorage.handson_url != "NA" || (sessionStorage.vm_url != "NA" && mockVar.curQuesBean.programmingLanguageName=="External VM Env")))
			$($(".Bttn_Area").children()).each(function(){if($(this).attr("class").indexOf("finalSubmit") == -1) $(this).hide();});
		quizPageHeight();
},10);
		setTimeout(function(){$(".refresh-message").show();},5000);
	}
	return str;
}
function fillQuesNumber(ques){
	var str = '<div id="Questn_Innr_Div_section"><div id="Subjt_Div"></div>';
	if(ques.keyboardLayout !== undefined && ques.keyboardLayout !== "" && ques.keyboardLayout!== "false" && ques.keyboardLayout !="null"){
		str += '<span class="typKeybrdLayout" id="keybrdLayt">Keyboard Layout:'+ques.keyboardLayout+'</span>';
		$('#mKeybrdLayt').html('Keyboard Layout : '+ques.keyboardLayout);
		$('#mKeybrdLayt').show();
	}
	str += '<div id="Subdetail_Div"><div style="float:right;margin-right:5px;">';
	if(ques.quesType != 'PROGRAMMING TEST' && ques.quesType != 'TYPING TEST' && mockVar.langCount>1){
		str += "<div class='chooseLang'> <span class='viewLang'>"+mockLabels.viewIn+"&nbsp</span><select class='choose_lang auditlogSelect' aria-labelledby='viewLang' onchange='changeLang(this.value)' onmousedown='if(this.options.length>7){ this.size=0; }' onblur='this.size=0; this.removeAttribute('size');' onchange='this.size=0; this.removeAttribute('size'); changeLang(this.value);'> ";
		for(var i=0;i<mockVar.languages.length;i++){
			if(mockVar.languages[i]!=null && typeof(mockVar.languages[i])!='undefined'){
				var index = (0 in mockVar.languages) ? (parseInt(i)+1) : i;
				str +="<option";
				if(index==mockVar.curQuesBean.quesLangBeans[mockVar.langIndex].langId)
					str += " selected='selected'";
				str +=  " value='"+index+"'>"+mockVar.languages[i]+"</option>";
			}
		}
		str +="</select></div>";
	}
	str += '</div></div></div>';
	return str;
}

function fillLAQuesNumber(ques){
	var str = '<div id="Questn_Innr_Div_section"><div id="Subjt_Div"><b>';
	mandatoryText = ques.isQuesMand == 'true' ? '<span style="color:red">* </span>':'';
	if(ques.displayQuestionNo == "true" || ques.displayQuestionNo == "" || typeof(ques.displayQuestionNo) == "undefined")
		str += '<span aria-label="question number" class="questionNumber">'+mandatoryText+''+mockLabels.questionNo+'</span>. '+eval(isOnline == 1 ? (iOAP.curQues+1):ques.sequenceNumber);
	str +=  ($.trim(ques.quesText.split("@@&&")[0]).length <= 0 && mockVar.laQName.length >0 )?(" ("+mockVar.laQName+")"):"";
	str +='</b></div><div id="Subdetail_Div"><div style="float:right;margin-right:5px;">';
	if(mockVar.langCount>1){
		str += "<div class='chooseLang'><span class='viewLang'> "+mockLabels.viewIn+"&nbsp<select class='choose_lang auditlogSelect' aria-labelledby='viewLang' onchange='changeLang(this.value)' onmousedown='if(this.options.length>7){ this.size=0; }' onblur='this.size=0; this.removeAttribute('size');' onchange='this.size=0; this.removeAttribute('size'); changeLang(this.value);'> ";
		for(var i=0;i<mockVar.languages.length;i++){
			if(mockVar.languages[i]!=null && typeof(mockVar.languages[i])!='undefined'){
				str +="<option";
				if(i==mockVar.curQuesBean.quesLangBeans[mockVar.langIndex].langId)
					str += " selected='selected'";
				str +=  " value='"+i+"'>"+mockVar.languages[i]+"</option>";
			}
		}
		str +="</select></div>";
	}
	str += '</div></div></div>';
	return str;
}
function changeDefaultLang(langID){
	changeLang(langID);
	mockVar.defaultLang=langID;
	try{
	$('#defaultSelectedLanguage').val(langID);
	document.cookie = 'defaultLang=; Path=/; Expires=Thu, 01 Jan 1970 00:00:01 GMT';
	document.cookie = "defaultLang="+langID;
	sessionStorage.defaultLang = langID;
	var AuditJsonObject = new Object();
	AuditJsonObject.ActionName = "Default Language Change";
	var auditDesc = "Default language changes to "+mockVar.languages[langID];
	AuditJsonObject.ActionDesc = auditDesc;
	AuditJsonObject.GroupId = "NA";
	AuditJsonObject.SectionId = "NA";
	AuditJsonObject.QuestionId = "NA";
	AuditJsonObject.candidateName = sessionStorage.isOfflinePaper=='1' ? sessionStorage.username : $.cookie("username");
	AuditJsonObject.loginId = sessionStorage.isOfflinePaper=='1' ? sessionStorage.username : $.cookie("loginId");
	AuditJsonObject.OptionSequence = "NA";

	var currentDate = new Date();
	AuditJsonObject.Time = currentDate.yyyymmddHHmmss();
	AuditJsonObject.eventTimestamp = Date.now();
	AuditJsonObject.SelectedOptionId = "NA";
	AuditJsonObject.macAddress=macAddress;
	AuditJsonObject.mockVarLoginId = mockVar.loginId;
	if(!isExaminer){
	AuditJson.push(AuditJsonObject);
	}
	}catch(e){}
}
function changeLang(langID){
	// iOAP.viewLang[iOAP.curSection][iOAP.curQues].langID = langID;
	isLanguageChange=true;
	var langId = jQuery(".auditlogSelect option:selected").val();
	mockVar.defaultLang=langID;
	try{
	$('#defaultSelectedLanguage').val(mockVar.defaultLang);
	var auditDesc = "Default language changes to "+mockVar.languages[langId];
	var currentSectionDetails = mockVar.groups[currentGroupIndex].secDetails[currentSectionIndex];
	var currentQuestionDetails = currentSectionDetails.questions[currentQuestionIndex];
	var optionSequence = "";
	var AuditJsonObject = new Object();
	AuditJsonObject.ActionName = "Language Change";
	AuditJsonObject.ActionDesc = auditDesc;
	AuditJsonObject.GroupId = mockVar.groups[currentGroupIndex].groupId;
	AuditJsonObject.SectionId = currentSectionDetails.secId;
	AuditJsonObject.QuestionId = currentQuestionDetails.quesId;
	AuditJsonObject.candidateName = sessionStorage.isOfflinePaper=='1' ? sessionStorage.username : $.cookie("username");
	AuditJsonObject.loginId = sessionStorage.isOfflinePaper=='1' ? sessionStorage.username : $.cookie("loginId");
	var currentDate = new Date();
	AuditJsonObject.Time = currentDate.yyyymmddHHmmss();
	AuditJsonObject.eventTimestamp = Date.now();
	if(currentQuestionDetails.quesType == "MCQ" || currentQuestionDetails.quesType == "MSQ" ){
		var length = currentQuestionDetails.options.length;
		for(var i=0;i<length;i++){
			k = i + 1;
			optionSequence = optionSequence + k + ")"+ currentQuestionDetails.options[i].optId+" ";
			AuditJsonObject.OptionSequence = optionSequence;
		}
	}
	if(currentQuestionDetails.quesParam.status != "notanswered"){
		AuditJsonObject.SelectedOptionId = currentQuestionDetails.quesParam.selectedOptId.replace(/,/g , "@_@");
	} else {
		AuditJsonObject.SelectedOptionId = "NA";
	}
	AuditJsonObject.mockVarLoginId = mockVar.loginId;
	if(!isExaminer){
	AuditJson.push(AuditJsonObject);
	}
	}catch(e){
		
	}
	var quesLangIndex = mockVar.curQuesBean.quesLangBeans.inArray(langID.toString(),"langId");
	if(quesLangIndex == -1){
		isfinalSubmit = true;
		cnfPop('InfoPopup');
		$("#infoMsg2").html(mockLabels.quesNotAvailable.replace('@@langName@@',mockVar.languages[langID]));
		fillQuesContent();
		
		if(($('#sectionSummaryDiv').is(':visible') || $('#breakTimeDiv').is(':visible')))
			$(".collapsebel_panel").hide();
		// chkIfMaxQuesCrossed();
		if (jQuery(window).width() > 1000) {
			quizPageHeight();
		} else {
			setDIVHeight_resp(); 
		}
		var qsnStatus=mockVar.curQuesBean.quesParam.status;
		if(qsnStatus!='answer'&& qsnStatus!='markedAndAnswered'){
			if(qsnStatus=='marked'){
				resetOptionGrp();
				fnsubmitGroupQuestion('MARK');
			}
			else resetOptionGrp();
		}
	}
	else{
		mockVar.langIndex = quesLangIndex;
		saveJwplayerParam();
		getQuestion(langID);
	    fillNumberPanel();
	}
	if(mockVar.WaterMark){
		if(mockVar.storeCandResponse == 0 || mockVar.storeCandResponse == "0"){
			$(".mockCandId").html(mockWaterMark);
			waterMark(mockWaterMark);
		}else
			waterMark(sessionStorage.waterMarkId);
	}
	var languageName = mockVar.languages[jQuery(".auditlogSelect.choose_lang option:selected").val()];
	var languageCode = langCodeFromXML(languageName);
	$("#currentQues .leftDiv").attr("lang", languageCode );
	$("#currentQues .rightDiv").attr("lang", languageCode );
}

