function timerForOptionSectionSelection(){

	$('#showTimee').hide();
	proceedToNextAfterSecSelection = false;
	$('#showTime').hide();
	//convertTime(mockVar.groups[mockVar.currentGrp].timerForOptionalSecSelection,mockVar.groups[mockVar.currentGrp].givenTimerForOptionalSecSelection,0,mockVar.groups[mockVar.currentGrp].timerForOptionalSecSelection,mockVar.groups[mockVar.currentGrp].givenTimerForOptionalSecSelection);
	$("#showTimeForOptSec").html( "<b>"+mockLabels.timeLeft+"<span id='timeInMins'>"+convertTime(mockVar.groups[mockVar.currentGrp].timerForOptionalSecSelection,mockVar.groups[mockVar.currentGrp].givenTimerForOptionalSecSelection,0,mockVar.groups[mockVar.currentGrp].timerForOptionalSecSelection,mockVar.groups[mockVar.currentGrp].givenTimerForOptionalSecSelection)+"</span></b>");
	$("#showTimeeForOptSec").html( "<b>"+mockLabels.timeLeft+"<span id='timeInMins'>"+convertTime(mockVar.groups[mockVar.currentGrp].timerForOptionalSecSelection,mockVar.groups[mockVar.currentGrp].givenTimerForOptionalSecSelection,0,mockVar.groups[mockVar.currentGrp].timerForOptionalSecSelection,mockVar.groups[mockVar.currentGrp].givenTimerForOptionalSecSelection)+"</span></b>");
	if(sessionStorage.userdefinedassessmentleveltimer==0){
		$('#showTimeeForOptSec').show();
		$('#showTimeForOptSec').hide();
		}else{
			$('#showTimeeForOptSec').hide();
			$("#showTimeForOptSec").show();
		}
	//$("#timerForOptionalSecs").html("Please select optional sections before " + convertTime(mockVar.groups[mockVar.currentGrp].timerForOptionalSecSelection,-1,-1,-1,-1)+" else default sections will be selected");
	if(mockVar.groups[mockVar.currentGrp].timerForOptionalSecSelection <= 0){
		for(var i=0;i<iOAP.secDetails.length;i++){
			if(iOAP.secDetails[i].isOptional == 'true'){
				iOAP.secDetails[i].isDiabledForOptionalSection = true;
				iOAP.secDetails[i].isSelected = false;
			}
		}
		mockVar.groups[mockVar.currentGrp].secSelectedCount = 0;
		for(var i=0;i<mockVar.groups[mockVar.currentGrp].defaultOptionalSections.length;i++){
			iOAP.secDetails[parseInt(mockVar.groups[mockVar.currentGrp].defaultOptionalSections[i])-1].isSelected = true;
			 mockVar.groups[mockVar.currentGrp].secSelectedCount++;
			// $("#s"+parseInt(mockVar.groups[mockVar.currentGrp].defaultOptionalSections[i])-1).attr("disabled",false);
			 iOAP.secDetails[parseInt(mockVar.groups[mockVar.currentGrp].defaultOptionalSections[i])-1].isDiabledForOptionalSection = false;
			/*$("opt"+(parseInt(mockVar.groups[mockVar.currentGrp].defaultOptionalSections[i])-1)).click();
			$("#opt"+(parseInt(mockVar.groups[mockVar.currentGrp].defaultOptionalSections[i])-1)).attr("checked",true);*/
			//$("#opt"+(parseInt(mockVar.groups[mockVar.currentGrp].defaultOptionalSections[i])-1)).attr("disabled","disabled");
			/*$("opt_New"+(parseInt(mockVar.groups[mockVar.currentGrp].defaultOptionalSections[i])-1)).click();
			$("#opt_New"+(parseInt(mockVar.groups[mockVar.currentGrp].defaultOptionalSections[i])-1)).attr("checked",true);*/
			//$("#opt_New"+(parseInt(mockVar.groups[mockVar.currentGrp].defaultOptionalSections[i])-1)).attr("disabled","disabled");
			clearTimeout(mockVar.timeCounterForOptional);
		}
		proceedToNextAfterSecSelection = true;
		
		//$(".optionalSection").attr("disabled","disabled");
		$(".optionselectionButton").removeAttr("disabled");
		//$(".optionselectionButton")[0].click();
		//clearTimeout(mockVar.timeCounterForOptional);
		mockVar.groups[mockVar.currentGrp].secImageSelection = true;
		$(".optionselectionButton").hide();
		getQuestion(typeof(langId) == "undefined" ? mockVar.defaultLang : langId);
		fillNumberPanel();
		$(".optionalSection").attr("disabled","disabled");
		mockVar.isOptionalSecTimerPage = 0;
		mockVar.resumedFromOptSecTimePage = 0; 
		if(mockVar.storeCandResponse == 1)
			saveBackUp(false);
		$('#showTimeeForOptSec').hide();
		$('#showTimeForOptSec').hide();
		if(sessionStorage.userdefinedassessmentleveltimer==0){
			$('#showTimee').show();
			$('#showTime').hide();
			}else{
				$('#showTimee').hide();
				$("#showTime").show();
			}
	}
	else{
		mockVar.isOptionalSecTimerPage = 1;
		mockVar.resumedFromOptSecTimePage = 0;
		mockVar.timerForOptionalSecSelection -= 1;
		mockVar.groups[mockVar.currentGrp].timerForOptionalSecSelection  = mockVar.timerForOptionalSecSelection;
		
	}
	if(mockVar.groups[mockVar.currentGrp].timerForOptionalSecSelection>=0 && $(".SecSelectionContent").is(":visible") == true)
	mockVar.timeCounterForOptional = setTimeout(function(){timerForOptionSectionSelection();},1000);
	else{
		proceedToNextAfterSecSelection = true;
		$('#showTimeeForOptSec').hide();
		$('#showTimeForOptSec').hide();
		if(sessionStorage.userdefinedassessmentleveltimer==0){
			$('#showTimee').show();
			$('#showTime').hide();
			}else{
				$('#showTimee').hide();
				$("#showTime").show();
			}
		mockVar.isOptionalSecTimerPage = 0;
	}
}
function adjustOptionalSectionImages(){
	var len = $(".secselection img").length;
	var h1=0,h2 = 0,maxi = 0;
		setTimeout(function(){
		for(var i=0;i<len;i+=2){
			h1 = $(".secselection img")[i].height;
			h2 = 0;
			if(i+1<len)
				h2 = $(".secselection img")[i].height;
			maxi = Math.max(h1,h2);
			$($(".secselection")[i]).css("height",maxi+64);
			if(i+1<len)
				$($(".secselection")[i+1]).css("height",maxi+64);
		}
	},500);
}
