function arrangeGroupProgressBar(){
	var str = "";
	// var totalQuestionsCount = 0;
	var width = $(".queSteps").width();
	if(typeof(mockVar.show_progress_bar) != "undefined" && (mockVar.show_progress_bar == "YES" || mockVar.show_progress_bar == true || mockVar.show_progress_bar == "true")){
	var groupActive = "";
	var spanWidth = 0;
	try{questionPaperNumberOfStages = questionPaperNumberOfStages < mockVar.questionPaperNumberOfStages ? mockVar.questionPaperNumberOfStages : questionPaperNumberOfStages;}catch(e){}
	questionPaperNumberOfStages = questionPaperNumberOfStages < mockVar.groups.length ? mockVar.groups.length : questionPaperNumberOfStages;
	var widthPercentage = (parseInt($(".queSteps").width() / questionPaperNumberOfStages))-10;
	for(var i=0;i< questionPaperNumberOfStages;i++){
		if(typeof(mockVar.groups[i]) != "undefined"){
		spanWidth = (widthPercentage / mockVar.groups[i].totalNoOfQuestionsExcludingDummyQuestions) * mockVar.groups[i].visitedQuestionsExcludingDummyQUestions;
		str += '<div value="0" max="'+mockVar.groups[i].totalNoOfQuestionsExcludingDummyQuestions+'" class="module module'+i+' tipIcon" objid="'+((spanWidth/widthPercentage)*100).toFixed()+'%" style="width:'+widthPercentage+'px !important"><span style="width:'+spanWidth+'px !important"></span></div>';
		} else {
			str += '<div value="0" max="100" class="module module'+i+'" style="width:'+widthPercentage+'px !important"><span style="width:0px !important"></span></div>';
		}
		$(".queSteps").empty();
		$(".queSteps").append(str);
		showQueSteps();
	}
	}
}
