function storeTicketDetails(event){
	
	var URL = "/IBACC/MockAssessmentAction.do?action=saveChat&orgId="+mockVar.orgId;
	var paramsvalue = {};
	paramsvalue["mockId"] = sessionStorage.assessmentId;
	paramsvalue["candMasterId"]=sessionStorage.candMasterId;
	paramsvalue["attemptNo"]=sessionStorage.attemptId;
	if(document.getElementById('ticket_msg').value!="" && document.getElementById('ticket_msg').value!=null){
	paramsvalue["query_text"]= document.getElementById('ticket_msg').value;
	jQuery.ajax({
		url : URL,
		async : true,
		type : 'POST',
		data : paramsvalue,
		dataType : 'text',
		success : function(data) {
			alert("your message sent successfully!!!");
			$('#chat-popup').hide();
			document.getElementById('ticket_msg').value="";
			$('.overlay').hide();
		}
	});
	}
	else{
		alert("Message should not be empty");
	}
}

