function checkAutoSaveGroup(currentGroup){
	if(mockVar.groups[currentGroup].secDetails[iOAP.curSection].autoSave!=null && typeof(mockVar.groups[currentGroup].secDetails[iOAP.curSection].autoSave)!="undefined" && mockVar.groups[currentGroup].secDetails[iOAP.curSection].autoSave == "true"){
		saveQuestionAutomatically();
	}
}
function checkGroupBreakTime(timeOutFlag){
	//console.log("check grp break time");
	var returnFlag=false;
	if(mockVar.curQuesBean.keyboardType == "AudioFile"){
		var audioElementsArray = document.getElementsByTagName('Audio');
		for(var i=0;i<audioElementsArray.length;i++){
			if(audioElementsArray[i].id=='recordedAudio'){
				audioElementsArray[i].pause();
				break;
			}
		}
		if(recordingInProgress){
			stopAudioRecording(false,mockVar.curQuesBean.quesId,mockVar.currentGrp,iOAP.curSection);
			// saveAudioRecording();
		}
	}else if(mockVar.curQuesBean.keyboardType == "VideoFile"){
		var videoElementsArray = document.getElementsByTagName('Video');
		for(var i=0;i<videoElementsArray.length;i++){
			if(videoElementsArray[i].id=='recordedVideo'){
				videoElementsArray[i].pause();
				break;
			}
		}
		if(recordingInProgress){
			stopVideoRecording(false);
			// saveVideoRecording();
		}
	}
	if($('#pop-up').is(':visible')){ //to remove useful data popup when group time out
		$(".pop-up-background").fadeOut(500);
		$(".pop-up").fadeOut(500);
	 }
	if(timeOutFlag!=undefined && timeOutFlag)
		mockVar.currentGrp=currentTimerGrp;
	if(mockVar.currentGrp < mockVar.groups.length-1){
		if(!(mockVar.groups[mockVar.currentGrp].breakTime == 0)){
			mockVar.isBreakPage=1;
			if(mockVar.storeCandResponse){
				if(!isFinalSubmitStarted){
					saveBackUp(false);
				}
			}
			clearTimeout(mockVar.timeCounter);
			mockVar.timeCounter = mockVar.groups[mockVar.currentGrp].breakTime;
			if(mockVar.remainingBreakTime>0 && mockVar.resumedFromBreakPage==1 && (mockVar.groupAtInterruption==mockVar.currentGrp || mockVar.ignoreElapsedTime)){
				alreadySubmitCalled = false;
				breakTimeCounter(mockVar.remainingBreakTime);
				auditLogForBreakPage();
				submitConfirmation('break');
			}
			else if(mockVar.remainingBreakTime<=0  && mockVar.resumedFromBreakPage==1 && mockVar.groupAtInterruption==mockVar.currentGrp){
				saveQuestionAutomatically();
				// isComingFromSaveAutomaticallyForCompre=false;
				submitGroup(timeOutFlag);
			}
			else if(mockVar.resumedFromBreakPage==1 && mockVar.groupAtInterruption!=mockVar.currentGrp){
				// alert('Interrupted in break but current group is not the
				// same');
			}
			else{
				if(sessionStorage.mandateGroupUniformLaunch==1 && firstGroupBreakTime!=0 && firstGroupBreakTime!=undefined){
					submitConfirmation('break');
					mockVar.timeCounter = firstGroupBreakTime;
//					firstGroupBreakTime = 0;
					alreadySubmitCalled = false;
					breakTimeCounter(mockVar.timeCounter);
					$('#breakTimeCountDiv').attr('tabindex','-1');
					$('#breakTimeCountDiv').attr('style','outline: none !important');
					$('#breakTimeCountDiv').focus();
					auditLogForBreakPage();
					saveBackUp(false);
					closePop();
				}
				else{
					submitConfirmation('break');
					if(sessionStorage.mandateGroupUniformLaunch==1 && mockVar.time != 0){
						mockVar.timeCounter = mockVar.groups[mockVar.currentGrp].breakTime + mockVar.time;
					}else{
						mockVar.timeCounter = mockVar.groups[mockVar.currentGrp].breakTime;
					}
					alreadySubmitCalled = false;
					breakTimeCounter(mockVar.timeCounter);
					$('#breakTimeCountDiv').attr('tabindex','-1');
					$('#breakTimeCountDiv').attr('style','outline: none !important');
					$('#breakTimeCountDiv').focus();
					auditLogForBreakPage();
					saveBackUp(false);
					closePop();
				}
			}
		}else{
			saveQuestionAutomatically();
			// isComingFromSaveAutomaticallyForCompre=false;
			submitGroup(timeOutFlag);
		}
	}else{
		if(sessionStorage.isAdaptive=="YES" && sessionStorage.noOfAdaptiveStages!=undefined && sessionStorage.noOfAdaptiveStages !="1"){
				var curQuesData = {};
				var currentQues = {};
				var ans = "";
				var iscorrect = false;
				var tempQuestionCount = 1;
				var grpQuesLength = 0;
				var sectionObject = mockVar.groups[mockVar.currentGrp].secDetails;
				var evalCompre = 0;
				var pairwiseScore = false;
				var previousCompreId = 0;
				var firstSeqQuestionId = 0;
				for(var ts = 0; ts < sectionObject.length;ts++){
					var tempSectionQuestions = sectionObject[ts].questions;
					sectionObject[ts].firstQuestionId = {};
					sectionObject[ts].AnswercompreIds = {};
					for(var tq = 0;tq < tempSectionQuestions.length; tq++){
						curQuesData = {};
						var tempQuesData = tempSectionQuestions[tq];
						if(previousCompreId != tempQuesData.comprehensionId && tempQuesData.comprehensionId != 0  && mockVar.compreLaqQues[quesIdIndexes[tempQuesData.comprehensionId]].additionalQuesType == "SEQUENCE" && (mockVar.compreLaqQues[quesIdIndexes[tempQuesData.comprehensionId]].scoringPattern == "Pairwise" || mockVar.compreLaqQues[quesIdIndexes[tempQuesData.comprehensionId]].scoringPattern == "Shufflewise" )){
							//previousCompreId = tempQuesData.comprehensionId;
							sectionObject[ts].firstQuestionId[tempQuesData.comprehensionId] = tempQuesData.quesId;
							firstSeqQuestionId = tempQuesData.quesId;
							pairwiseScore = true;
						}
						ans = "";
						if(tempQuesData.quesType == "MCQ" || tempQuesData.quesType == "MSQ")
							ans = tempQuesData.quesParam.selectedOptId;
						else
							ans = tempQuesData.quesParam.answer;
						var correct_response = tempQuesData.correctAnswer;
						try{
						if(tempQuesData.comprehensionId != 0 &&  mockVar.compreLaqQues[quesIdIndexes[tempQuesData.comprehensionId]].additionalQuesType == "SEQUENCE" && (mockVar.compreLaqQues[quesIdIndexes[tempQuesData.comprehensionId]].scoringPattern == "Pairwise" || mockVar.compreLaqQues[quesIdIndexes[tempQuesData.comprehensionId]].scoringPattern == "Shufflewise")){
							sectionObject[ts].AnswercompreIds[tempQuesData.comprehensionId] = typeof(sectionObject[ts].AnswercompreIds[tempQuesData.comprehensionId]) == "undefined" ? tempQuesData.quesParam.selectedOptId : sectionObject[ts].AnswercompreIds[tempQuesData.comprehensionId]+","+tempQuesData.quesParam.selectedOptId;
						}
						}catch(e){};
						curQuesData["candidateCounter"] = tempQuestionCount++;
						curQuesData["question_response"] = ans;
						curQuesData["quesType"] = tempQuesData.quesType;
						curQuesData["currentResponseForStage"] = ans;
						curQuesData["marks"] = evaluateAnswer(tempQuesData,curQuesData);
						curQuesData["correct_response"] = correct_response;
						// curQuesData["marks"] =
						// iscorrect?tempQuesData.allottedMarks:tempQuesData.negMarks;
						curQuesData["total_marks"] = tempQuesData.quesType == "MCQ" || tempQuesData.quesType == "MSQ" ? tempQuesData.allottedMarks : 0;
						currentQues[tempQuesData.quesId+""] = curQuesData;
						try{
							//if(pairwiseScore && (tq >= tempSectionQuestions.length || (tempQuesData.comprehensionId != tempSectionQuestions[tq+1].comprehensionId)){
							if(tempQuesData.comprehensionId != 0 &&  mockVar.compreLaqQues[quesIdIndexes[tempQuesData.comprehensionId]].additionalQuesType == "SEQUENCE" && (mockVar.compreLaqQues[quesIdIndexes[tempQuesData.comprehensionId]].scoringPattern == "Pairwise" || mockVar.compreLaqQues[quesIdIndexes[tempQuesData.comprehensionId]].scoringPattern == "Shufflewise" )){
								var correctPairwiseData = sectionObject[ts].compreIds[tempQuesData.comprehensionId].split(",");
								var selectedPairsData = sectionObject[ts].AnswercompreIds[tempQuesData.comprehensionId].split(",");
								var correctCount = 0;
								var currentSeqIndex = -1;
								var prevSeqIndex = -1;
								if(correctPairwiseData.length == selectedPairsData.length){
								if(mockVar.compreLaqQues[quesIdIndexes[tempQuesData.comprehensionId]].scoringPattern == "Pairwise"){
									for(var spd=0;spd<selectedPairsData.length;spd++){
	
									if(spd==0 && correctPairwiseData.indexOf(selectedPairsData[spd]) == 0)
											correctCount++;
										currentSeqIndex = correctPairwiseData.indexOf(selectedPairsData[spd]);
										if(prevSeqIndex!= -1 && (prevSeqIndex + 1) == currentSeqIndex)
											correctCount++;
										prevSeqIndex = correctPairwiseData.indexOf(selectedPairsData[spd]);
								
									}
								}else if(mockVar.compreLaqQues[quesIdIndexes[tempQuesData.comprehensionId]].scoringPattern == "Shufflewise"){
									correctCount = returnShuffleCount(selectedPairsData,correctPairwiseData);
								}
								var pairWiseScoreSplit  = mockVar.compreLaqQues[quesIdIndexes[tempQuesData.comprehensionId]].scoringPattern == "Shufflewise" ? "<shuffleSeparator>" : "<pairSeparator>";
								var pairwiseScoreData =  mockVar.compreLaqQues[quesIdIndexes[tempQuesData.comprehensionId]].pairwiseScore.split(pairWiseScoreSplit);
								if(correctCount > 0 || (mockVar.compreLaqQues[quesIdIndexes[tempQuesData.comprehensionId]].scoringPattern == "Shufflewise" && correctCount ==0)){
									for(var psd=0;psd<pairwiseScoreData.length;psd++){
										if(pairwiseScoreData[psd]!="" && parseInt(pairwiseScoreData[psd].split("<marksSeparator>")[0].trim()) == correctCount){
											var pairwiseMarks = parseFloat(pairwiseScoreData[psd].split("<marksSeparator>")[1].trim());
											//console.log("pairwiseMarks"+pairwiseMarks);
											currentQues[sectionObject[ts].firstQuestionId[tempQuesData.comprehensionId]].marks = pairwiseMarks;
											//console.log(currentQues[sectionObject[ts].firstQuestionId[tempQuesData.comprehensionId]].marks);
											break;
										}
									}
									}
								
								}
								
								try{
									//.log("pariwise total marks");
									var pairWiseScoreSplitter  = mockVar.compreLaqQues[quesIdIndexes[tempQuesData.comprehensionId]].scoringPattern == "Shufflewise" ? "<shuffleSeparator>" : "<pairSeparator>";
									var pairwiseScoreSep =  mockVar.compreLaqQues[quesIdIndexes[tempQuesData.comprehensionId]].pairwiseScore.split(pairWiseScoreSplitter);
									var previousPairwiseMarks = 0;
										for(var psd=0;psd<pairwiseScoreSep.length;psd++){
												var pairwiseMarks = parseFloat(pairwiseScoreSep[psd].split("<marksSeparator>")[1].trim());
												if(pairwiseMarks>previousPairwiseMarks){
													//console.log("pairwiseMarks"+pairwiseMarks);
												currentQues[sectionObject[ts].firstQuestionId[tempQuesData.comprehensionId]].total_marks = pairwiseMarks;
												}
												previousPairwiseMarks = pairwiseMarks;
										}
									
								
								}catch(e){}
							}
							}catch(e){}
						previousCompreId = tempQuesData.comprehensionId;
						// nextQuestioncall(qpId,orgId,mockId,curQuesData);
					}
				}
				nextQuestioncall(sessionStorage.qp_id,sessionStorage.orgId,sessionStorage.assessmentId,currentQues);
				

		}else{
		if(isExaminer && !examinerOnlyOrExaminerViewLaunch && mockVar.groups[mockVar.currentGrp].isExaminerGroup){
			autoSubmitFromExaminerInteractionGroup = true;
		}
		submitMock("");
		returnFlag=true;
		}
	}
	
	return returnFlag;
}
function auditLogForBreakPage(){
	var AuditJsonObject = new Object();
	AuditJsonObject.ActionName = "BreakPage" ;
	AuditJsonObject.ActionDesc = "BreakPage appreared";
	AuditJsonObject.GroupId = mockVar.groups[currentGroupIndex].groupId;
	AuditJsonObject.SectionId = mockVar.groups[currentGroupIndex].secDetails[iOAP.curSection].secId;
	AuditJsonObject.QuestionId = mockVar.curQuesBean.quesId;
	AuditJsonObject.candidateName = sessionStorage.isOfflinePaper=='1' ? sessionStorage.username : $.cookie("username");
	AuditJsonObject.loginId = sessionStorage.isOfflinePaper=='1' ? sessionStorage.username : $.cookie("loginId");
	AuditJsonObject.OptionSequence = "NA";
	var currentDate = new Date();
	AuditJsonObject.Time = currentDate.yyyymmddHHmmss();
	AuditJsonObject.eventTimestamp = Date.now();
	AuditJsonObject.SelectedOptionId = "NA";
	AuditJsonObject.timespentInSeconds = "NA";
	AuditJsonObject.mockVarLoginId = mockVar.loginId;
	if(!isExaminer){
	AuditJson.push(AuditJsonObject);
}
}
