function afterSubmitGroup(){

	if(grpInstruDetails!=undefined && mockVar.groups[mockVar.currentGrp]!=undefined && grpInstruDetails[mockVar.groups[mockVar.currentGrp].groupId]!=undefined && typeof(grpInstruDetails[mockVar.groups[mockVar.currentGrp].groupId]["instructionTime"])!='undefined'&& grpInstruDetails[mockVar.groups[mockVar.currentGrp].groupId]["instructionTime"]!=0 && Object.keys(grpInstru[mockVar.groups[mockVar.currentGrp].groupId]).length>0){
		mockVar.isInstruPage=1;
		if(mockVar.storeCandResponse){
			if(!isFinalSubmitStarted){
				isGroupTransition=true;
				saveBackUp(false,true);
				isGroupTransition=false;
			}
		}
		clearTimeout(mockVar.timeCounter);
		// console.log(grpInstruDetails[mockVar.groups[mockVar.currentGrp].groupId]["instructionTime"]);
		mockVar.timeCounter =grpInstruDetails[mockVar.groups[mockVar.currentGrp].groupId]["instructionTime"];  
		if(mockVar.remainingInstruTime>0 && mockVar.resumedFromInstruPage==1 && mockVar.groupAtInterruption==mockVar.currentGrp ){
			instruTimeCounter(mockVar.remainingInstruTime);
			showGrpInstructions();
			document.getElementById('proceedToGrp').style.cursor='not-allowed';
			document.getElementById('proceedToGrp').style.pointerEvents = 'none';
			setTimeout(function(){
				document.getElementById("proceedToGrp").style.cursor='pointer'; 
				document.getElementById('proceedToGrp').style.pointerEvents = 'auto';
				$("#proceedToGrp").attr("role","button");
				$("#proceedToGrp").attr("tabindex","0");
			},1000);
		}
		else if(mockVar.remainingInstruTime<=0  && mockVar.resumedFromInstruPage==1 && mockVar.groupAtInterruption==mockVar.currentGrp){
			moveToGroupFromGrpInst();
		}
		else if(mockVar.resumedFromInstruPage==1 && mockVar.groupAtInterruption!=mockVar.currentGrp){
		
		}
		else{
			instruTimeCounter(mockVar.timeCounter);
			showGrpInstructions();
			document.getElementById('proceedToGrp').style.cursor='not-allowed';
			document.getElementById('proceedToGrp').style.pointerEvents = 'none';
			setTimeout(function(){
				document.getElementById("proceedToGrp").style.cursor='pointer'; 
				document.getElementById('proceedToGrp').style.pointerEvents = 'auto';
				$("#proceedToGrp").attr("role","button");
				$("#proceedToGrp").attr("tabindex","0");
			},1000);
		}
		}
	else if(secInstruDetails!=undefined && mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection]!=undefined && secInstruDetails[mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].secId]!=undefined && typeof(secInstruDetails[mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].secId]["instructionTime"])!='undefined' && secInstruDetails[mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].secId]["instructionTime"]!=0 && Object.keys(secInstru[mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].secId]).length>0){
		mockVar.isSecInstruPage=1;
		mockVar.isInstruPage=0;
		mockVar.isQuesInstruPage=0;
		if(mockVar.storeCandResponse){
			if(!isFinalSubmitStarted){
				isGroupTransition=true;
				saveBackUp(false,true);
				isGroupTransition=false;
			}
		}
		clearTimeout(mockVar.timeCounter);
		// console.log(grpInstruDetails[mockVar.groups[mockVar.currentGrp].groupId]["instructionTime"]);
		mockVar.timeCounter =secInstruDetails[mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].secId]["instructionTime"]; 
		if(mockVar.remainingInstruTime>0 && mockVar.resumedFromSecInstruPage==1 && mockVar.secAtInterruption==iOAP.curSection){
			instruTimeCounterForSec(mockVar.remainingInstruTime);
			showSecInstructions();
			document.getElementById('proceedToGrp').style.cursor='not-allowed';
			document.getElementById('proceedToGrp').style.pointerEvents = 'none';
			setTimeout(function(){
				document.getElementById("proceedToGrp").style.cursor='pointer'; 
				document.getElementById('proceedToGrp').style.pointerEvents = 'auto';
				$("#proceedToGrp").attr("role","button");
				$("#proceedToGrp").attr("tabindex","0");
			},1000);
		}
		else if(mockVar.remainingInstruTime<=0  && mockVar.resumedFromSecInstruPage==1 && mockVar.secAtInterruption==iOAP.curSection){
			moveToGroupFromGrpInst();
		}
		else if(mockVar.resumedFromSecInstruPage==1 && mockVar.secAtInterruption==iOAP.curSection){
		}
		else{
			instruTimeCounterForSec(mockVar.timeCounter);
			showSecInstructions();
			document.getElementById('proceedToGrp').style.cursor='not-allowed';
			document.getElementById('proceedToGrp').style.pointerEvents = 'none';
			setTimeout(function(){
				document.getElementById("proceedToGrp").style.cursor='pointer'; 
				document.getElementById('proceedToGrp').style.pointerEvents = 'auto';
				$("#proceedToGrp").attr("role","button");
				$("#proceedToGrp").attr("tabindex","0");
			},1000);
		}	
	}
	else if(secInstruDetails!=undefined && mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection]!=undefined && secInstruDetails[mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].secId]!=undefined && typeof(secInstruDetails[mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].secId]["instructionTime"])=='undefined' && secInstruDetails[mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].secId]["instructionTime"]!=0 && Object.keys(secInstru[mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].secId]).length>0){
		// for those assessments in which
		// sec instru are present but time 
		// is not
		secInstruDisplay('backwardcompatability');
	}
	else{
			// Current Group Check
		if(mockVar.groups[mockVar.currentGrp].isExaminerGroup!=undefined){// To
																			// Check
																			// whether
																			// assessment
																			// is
																			// created
																			// before
																			// video
																			// call
																			// implementation
																			// or
																			// after
				if(!isExaminer){
					if(mockVar.groups[mockVar.currentGrp].isExaminerGroup){
					clearTimeout(mockVar.timeCounter);
					mockVar.MaxGrpEnabled=mockVar.currentGrp;
					showExaminerDivForCandidate();
					}else{
					moveToGroupFromGrpInst();
					}
				}else{
				if(mockVar.groups[mockVar.currentGrp].isExaminerGroup){
					moveToGroupFromGrpInst();
					if(mockVar.groups[mockVar.currentGrp].indicatePresenceOfExaminerGroup){
					// Button to join video call to be displayed to
					// the candidate
					}else{
					// Nrml group
					}
				}else{
				if(mockVar.groups[mockVar.currentGrp].isSubmitted){
				// Console depends upon permissions for examiner
				moveToGroupFromGrpInst();
				}else{
				// Dont allow to navigate
				
				}
				}
				}
		}else{
		moveToGroupFromGrpInst();
		}
	
	}
	saveBackUp();

}
