function eventBlock(event){
	event.preventDefault();
	if(event.stopPropagation){
		event.stopPropagation();
	}else{
		event.returnValue=false;
	}
}

function groupWidthCalculate(){
	var calculategroupwidth = $(window).width() - 275 - $('.components-section').width();
	var calculateinnerwidth=0,grpval=0,hiddenval=false;
	jQuery("#groups .allSections").each(function(){
		calculateinnerwidth = calculateinnerwidth + jQuery(this).outerWidth(true) + 5;
		grpval++;
		if(calculateinnerwidth>calculategroupwidth){
			if(mockVar.currentGrp>=(grpval-1) && !hiddenval){
				var getlastindex=grpval-1;
				var getfirstindex=jQuery(".group-panel").find(".allSections:visible:first").index()+1;
				while(getfirstindex != (getlastindex+1))
				{
					jQuery(".group-panel").find(".allSections").eq(getfirstindex-1).hide();
					getfirstindex++;
				}	
				var calculategroupwidthcompare = $(window).width() - 275 - $('.components-section').width();
				var innerwidth=0;
				hiddenval=true;
				getlastindex=getlastindex-1;
				jQuery("#groups .allSections:gt("+getlastindex+")").each(function(){
					innerwidth += jQuery(this).outerWidth(true);
					if(innerwidth<calculategroupwidthcompare)
					{
						jQuery(this).show();
					}else{
						return false;
					}
				});
				jQuery(".group-arrow-left-disabled").attr("class","group-arrow-left");
				jQuery(".group-arrow-left").attr("tabindex","0");
				if(jQuery(".group-panel").find(".allSections:last").is(":visible")){
					jQuery(".group-arrow-right").attr("class","group-arrow-right-disabled");
					jQuery(".group-arrow-right-disabled").attr("tabindex","-1");
				}
			}else{
				if(mockVar.currentGrp<(grpval-1) && !hiddenval){
					jQuery(this).hide();
					jQuery(this).nextAll().hide();
					jQuery(".components-section .group-arrow-right-disabled").attr("class","group-arrow-right");
				}
			}
		}
	});

}


function sectionWidthCalculate(){
	if(isDeakin)return;
	if(jQuery(window).width()>1000)
		var calculatesubjectwidth = $(window).width() - 285;
	// jQuery(".subject-selection").css("width",calculatesubjectwidth-4);
	var calculatesubjectinnerwidth=0;
	jQuery("#sections .subject-name").each(function(){
		calculatesubjectinnerwidth = calculatesubjectinnerwidth + 11 + jQuery(this).outerWidth(true);
		if(calculatesubjectinnerwidth>=calculatesubjectwidth && navSection==false){
			jQuery(this).hide();
			jQuery(this).nextAll().hide();
			jQuery(".subject-arrow-right-disabled").attr("class","subject-arrow-right");
			jQuery(".subject-arrow-right").attr("tabindex","0");
		}
		else{		
			if(navSection==true ){
				if($(this).css('display') != 'none' && calculatesubjectinnerwidth<calculatesubjectwidth){
					$(this).hide();
				}
				else{
					$(this).show();
				}
			}
		}
	});
}

function hideUnneededTabArrows() {
    var availableWidth = $(".Lft_Section").width();
    var hasHiddenSections = $("#sections .subject-name:hidden").length > 0;
    var hasHiddenGroups= $("#groups .allSections:hidden").length > 0;

    var groupTabsWidth = 0;
    $("#groups .allSections").each(function () {
        groupTabsWidth += $(this).outerWidth(true);
    });

    var sectionTabsWidth = 0;
    $("#sections .subject-name").each(function () {
        sectionTabsWidth += $(this).outerWidth(true);
    });

    // Hide group arrows only when every group fits.
    if (groupTabsWidth <= availableWidth && !hasHiddenGroups) {
        $(".group-arrow-left-disabled, .group-arrow-left, " +
          ".group-arrow-right-disabled, .group-arrow-right").hide();
    }else{
    	 $(".group-arrow-left-disabled, .group-arrow-left, " +
         ".group-arrow-right-disabled, .group-arrow-right").show();
    }

    // Hide section arrows only when every section fits.
    if (sectionTabsWidth <= availableWidth && !hasHiddenSections) {
        $(".subject-arrow-left-disabled, .subject-arrow-left, " +
          ".subject-arrow-right-disabled, .subject-arrow-right").hide();

        $(".subject-section-rightarrow").hide();
    }else{
    	$(".subject-arrow-left-disabled, .subject-arrow-left, " +
        ".subject-arrow-right-disabled, .subject-arrow-right").show();

      $(".subject-section-rightarrow").show();
    }
}

function optSecCheck(secId,event){
	var counter = 0;
	for(var i=0;i<iOAP.secDetails.length;i++){
		if(iOAP.secDetails[i].isSelected){
			counter++;
		}
	}
	counter++;
	if(counter>iOAP.maxNoOptSec){
		event.preventDefault();
		if(event.stopPropagation){
			event.stopPropagation();
		}else
			event.returnValue=false;
		secChangeConfirmation();
	}else{
		if(!$("#sections .subject-name input").hasClass("mandatoryClass")){
			iOAP.secDetails[secId].isSelected = true;
			enableOptButtons();
			changeSection(secId);
		}else{
				var str="<table align='center'>";
				str +='<tr><td>'+$(globalXmlvar).find('MandatoryQuesMsg').text()+'</td></tr></table>';
				$("#infoMsg2").html(str);
				cnfPop('InfoPopup');
				eventBlock(event);
		}
	}
}

function optSecUncheck(secId,event){
	event.preventDefault();
	if(event.stopPropagation){
		event.stopPropagation();
	}else{
		event.returnValue=false;
	}
	var str= "";
	str ="<center><p style='margin-top:5%'><i>"+mockLabels.deselectOptSect+"</i></p><br/>";
	str +="<table align='center' style='width: 0px!important;margin-top:5%'>";
	var rightD = "right";
	var leftD = "left";
	str +='<tr><td style="text-align:'+(isRightToLeftIsRequired ? rightD : leftD)+';padding-right:2px"><input onclick="resetSection('+secId+');afterResetSection();" type="button" class="btn btn-primary btn-primary-blue" style="margin-right: 0px" title="'+mockLabels.yes+'" value="'+mockLabels.yes+'"/></td><td  style="text-align:'+(isRightToLeftIsRequired ? leftD : rightD)+';padding-left:2px"><input onclick="showModule(';
	str +="'Questn_Area'";
	str +=')" type="button" class="btn btn-primary btn-primary-blue" style="margin-left:0px" title="'+mockLabels.no+'" value="'+mockLabels.no+'"/></td></tr></table></center>';
	$("#sectionSummaryDiv").html(str);
	showModule('sectionSummaryDiv');
	if(iOAP.curSection !=secId){
		getAlertData(secId);
	}
	if($(window).width()<1000){
		$('#sectionSummaryDiv').height($(window).height() - jQuery("#header").outerHeight(true));
		$('.subheader_tab,.grup_components,.q_tab,.btntab').hide();
	}
}
function getAlertData(secId){
	var str=""; var c=0;var d = new Array();
	if(iOAP.secDetails[secId].groupAllQuestions == "false"){
		for(var x=0;x<iOAP.secDetails[secId].questions.length;x++){
			if(iOAP.secDetails[iOAP.curSection].questions[x].flagforReVistQues != null && typeof(iOAP.secDetails[iOAP.curSection].questions[x].flagforReVistQues)!='undefined'){
				if(iOAP.secDetails[secId].questions[x].flagforReVistQues==false){
					c++;
					d.push(x+1);
				}
			}
		}
	}else{
		if(iOAP.secDetails[iOAP.curSection].questions[0].flagforReVistQues != null && typeof(iOAP.secDetails[iOAP.curSection].questions[0].flagforReVistQues)!='undefined'){
			if(iOAP.secDetails[secId].questions[0].flagforReVistQues==false){
				c++;
			}
		}
	}
	if(c!=0 && iOAP.secDetails[secId].groupAllQuestions == "false"){
		str="<table align='center' style='margin-top:5%'>";
		str +='<tr><td>Question ';
		for(var m=0;m<d.length;m++)
			str +=d[m]+',';
		str=str.trim();
		str=str.substring(0,str.length - 1);
		str+=' cannot be Revisited even though you reset the Section.</td></tr></table>';
		$("#infoMsg2").html(str);
		cnfPop('InfoPopup');
	}else if(c!=0 && iOAP.secDetails[secId].groupAllQuestions == "true"){
		str="<table align='center' style='margin-top:5%'>";
		str +='<tr><td>You cannot Revisit the section even though you reset the Section.</td></tr></table>';
		$("#infoMsg2").html(str);
		cnfPop('InfoPopup');
	}

}
function resetSection(secId){
	var counter = 0;
	// var langIdCount=0;
	/*
	 * for(var langId=0;langId<mockVar.languages.length;langId++){
	 * if(mockVar.languages[langId]!=null &&
	 * typeof(mockVar.languages[langId])!='undefined'){ langIdCount++;
	 */
	for(var j=0;j<iOAP.secDetails[secId].questions.length;j++){
		iOAP.secDetails[secId].questions[j].quesParam.answer = '';
		iOAP.secDetails[secId].questions[j].quesParam.selectedOptId = '';
		iOAP.secDetails[secId].questions[j].typedWord = '';
		if(iOAP.secDetails[secId].questions[j].quesParam.status != 'notAttempted'){
			iOAP.secDetails[secId].questions[j].quesParam.status="notanswered";
			counter++;
		}
		if(iOAP.secDetails[secId].questions[j].flagforReVistQues!=null && iOAP.secDetails[secId].questions[j].flagforReVistQues==true && iOAP.secDetails[secId].questions[j].isQuesMand!=null && iOAP.secDetails[secId].questions[j].isQuesMand=='true'){
			iOAP.secDetails[secId].questions[j].isQuesMandUnanswered = true;
		}			
	}
	if(iOAP.secDetails[secId].questions[iOAP.curQues].flagforReVistQues!=null && iOAP.secDetails[secId].questions[iOAP.curQues].flagforReVistQues==false)
		iOAP.secDetails[secId].questions[iOAP.curQues].flagforReVistQues= true;
	/*
	 * } }
	 */
	$('#code').val('');
	$('#answer').val('');
	$("#noOfWords").text('');
	iOAP.secDetails[secId].answered = 0;
	// we are dividing here because the counter counts in all the languages.
	iOAP.secDetails[secId].notanswered = counter; 
	iOAP.secDetails[secId].marked = 0;
	iOAP.secDetails[secId].markedAndAnswered= 0;
	iOAP.secDetails[secId].isSelected = false;
	if(iOAP.secDetails[secId].secCount == iOAP.secDetails[secId].questions.length)
		$("#opt"+secId).attr("disabled","disabled");
}

