function questionSwiperFunc(activeQuestionIndex) {
    var mySwiper4 = document.querySelector('.questionsSwiperGrp'+mockVar.currentGrp+'Sec'+iOAP.curSection+'').swiper
    if(mySwiper4){
    	mySwiper4.destroy(true, true);
    }
    if($(window).width() > 767){ // replace this width condition with skinning usecase ex:  examlab/ilearn
    mySwiper4 = new Swiper('.questionsSwiperGrp'+mockVar.currentGrp+'Sec'+iOAP.curSection+'', {
        autoplay: false,
        slidesPerView: 9,
        spaceBetween: 10,
        observer: true,
        observeParents: true,
        navigation: {
            nextEl: '.queSwiperRightActionGrp'+mockVar.currentGrp+'Sec'+iOAP.curSection+'',
            prevEl: '.queSwiperLeftActionGrp'+mockVar.currentGrp+'Sec'+iOAP.curSection+'',
        },
        on: {
        	init:function(swiper){
                var clickedIndex = swiper.clickedIndex;
                swiper.slideTo(activeQuestionIndex-1, 1000)
           },
           click: function (swiper, e) {
                var clickedIndex = swiper.clickedIndex;
                swiper.slideTo(clickedIndex, 1000);
            },
            resize: function () {

            },
        },
    });
}
    
    else{
        mySwiper4 = new Swiper('.questionsSwiperGrp'+mockVar.currentGrp+'Sec'+iOAP.curSection+'', {
            autoplay: false,
            slidesPerView: "auto",
            spaceBetween: 10,
            observer: true,
            observeParents: true,
           /* navigation: {
                nextEl: '.queSwiperRightActionGrp'+mockVar.currentGrp+'Sec'+iOAP.curSection+'',
                prevEl: '.queSwiperLeftActionGrp'+mockVar.currentGrp+'Sec'+iOAP.curSection+'',
            },*/
            on: {
            	init:function(swiper){
                    var clickedIndex = swiper.clickedIndex;
                    swiper.slideTo(activeQuestionIndex-2, 2000);
               },
               click: function (swiper, e) {
                    var clickedIndex = swiper.clickedIndex;
                    swiper.slideTo(clickedIndex-2, 2000);
                },
                resize: function () {

                },
            },
        });

    }
   // mySwiper4.slideTo(activeQuestionIndex-2);
    setTimeout(function(){
        $('.divHeader').html('<span aria-label="question number" class="questionNumber">'+mockLabels.questionNo+'</span>. '+$(".currActiveQues").html()+ '<span aria-label="question number" class="questionNumberOf"> '+mockLabels.questionNoOf+' </span> '+mySwiper4.slides.length);
    },0)
}
function bindSequenceQuestionSortable(){
	if(sortingAxis == "x"){
		var widthForSeqHelper = 0;
		$("#sortable").sortable({
			start:function(event,ui){
				widthForSeqHelper = $(ui.item).outerWidth();
				},
			sort : function(){
				if(sortingAxis == "x"){
					if(widthForSeqHelper == 0)
						widthForSeqHelper = $(".ui-state-default.ui-sortable-helper").outerWidth()-1;
				$(".ui-state-default.ui-sortable-helper").css({"width":(widthForSeqHelper+1),"height":"auto","z-index":2});
				var $list = $(this).children('li');
	            $list.each(function(){
	            var $li = $(this);
	            var index1 = $list.filter('.ui-sortable-helper').index();
	            if( !$li.is('.ui-sortable-helper') ){
	                var index = $li.index();
	                index = index < index1 ? index + 1 : index;
	                $li.val(index);
	                if( $li.is('.ui-sortable-placeholder') ){
	                    $list.filter('.ui-sortable-helper').val(index);
	                }
	            }
	        });
				}
	        },update: function(e, ui) {
	        	dynamicNumberingForSeq(false)
	        },
	        //containment : "parent",
			axis:sortingAxis
			});
	} else {
	$("#sortable").sortable({
		scroll:true,
		start: function() {},
		sort : function(){ // added by sreejith
			if(sortingAxis == "y"){
			var $list = $(this).children('li');
            $list.each(function(){
            var $li = $(this);
            var index1 = $list.filter('.ui-sortable-helper').index();
            if( !$li.is('.ui-sortable-helper') ){
                var index = $li.index();
                index = index < index1 ? index + 1 : index;
                $li.val(index);
                if( $li.is('.ui-sortable-placeholder') ){
                    $list.filter('.ui-sortable-helper').val(index);
                }
            }
        });
			}
        },update: function(e, ui) {
        	dynamicNumberingForSeq(false)
        },
        //containment : "parent",
		drag: function() {},
		stop: function() {
			var l = $('#sortable li').length;
		}
	});
	}
	$("#sortable").disableSelection();
	var $start_counter = $("#event-start"),
	$drag_counter = $("#event-drag"),
	$stop_counter = $("#event-stop");
}
