var isComingFromSaveAutomaticallyForCompre = false;
function saveQuestionAutomatically(){
		if(iOAP.secDetails[iOAP.curSection].groupAllQuestions == "true" ){
		/*
		 * for(var i=0;i<mockVar.curSectionQuestions.length;i++){
		 * if((mockVar.curSectionQuestions[i].quesType =="SA" ||
		 * mockVar.curSectionQuestions[i].quesType =="COMPREHENSION@@SA" ||
		 * mockVar.curSectionQuestions[i].quesType =="LA@@SA") &&
		 * mockVar.curSectionQuestions[i].keyboardType == 'Alphanumeric'){
		 * fnsubmitGroupQuestion('saveSA'); } }
		 */
			if(iOAP.secDetails[iOAP.curSection].autoSave!=null && typeof(iOAP.secDetails[iOAP.curSection].autoSave)!="undefined" && iOAP.secDetails[iOAP.curSection].autoSave == "true" ||  mockVar.autoSaveRequired == "true" || mockVar.autoSaveRequired == "false"){
				if(mockVar.autoSaveRequired == "true" || mockVar.autoSaveRequired == "false"){
					isComingFromSaveAutomaticallyForCompre = true;
					fnsubmitGroupQuestion('saveSA');
				}
				else if(iOAP.secDetails[iOAP.curSection].autoSave!=null && typeof(iOAP.secDetails[iOAP.curSection].autoSave)!="undefined" && iOAP.secDetails[iOAP.curSection].autoSave == "true")
				fnsubmitGroupQuestion('NEXT');
			}
		}else{
			
			if((mockVar.curQuesBean.quesType =="SA" || mockVar.curQuesBean.quesType =="COMPREHENSION@@SA" || mockVar.curQuesBean.quesType =="LA@@SA") && mockVar.autoSaveRequired == "oldAssForBackwardComp" &&  mockVar.curQuesBean.keyboardType == 'Alphanumeric'){
				if(mockVar.curQuesBean.comprehensionId != 0 || mockVar.curQuesBean.laqId != 0){
					// var compreLaqCount= 0;
					var compreLaqID = 0;
					if(typeof(mockVar.compreLaqQues[compreLaqID])!= "undefined"){
						/*
						 * for(var j=0;j<mockVar.curSectionQuestions.length;j++){
						 * if(mockVar.curQuesBean.comprehensionId!=0){
						 * if(mockVar.curQuesBean.comprehensionId ==
						 * mockVar.curSectionQuestions[j].comprehensionId){
						 * compreLaqCount++; } }else
						 * if(mockVar.curQuesBean.laqId!=0){
						 * if(mockVar.curQuesBean.laqId ==
						 * mockVar.curSectionQuestions[j].laqId){
						 * compreLaqCount++; } } }
						 */
						for(var k=0;k<mockVar.compreLaqQues.length;k++){
							if(mockVar.curQuesBean.comprehensionId == mockVar.compreLaqQues[k].quesId){
								compreLaqID = k;
								break;
							} else if(mockVar.curQuesBean.laqId == mockVar.compreLaqQues[k].quesId){
								compreLaqID = k;
								break;
							}
						}
						if( typeof(mockVar.compreLaqQues[compreLaqID].groupComprehensionLaqQuestions) != "undefined" && mockVar.compreLaqQues[compreLaqID].groupComprehensionLaqQuestions != "" && ((mockVar.compreLaqQues[compreLaqID].groupComprehensionLaqQuestions == "true") && (mockVar.compreLaqQues[compreLaqID].quesId == mockVar.curQuesBean.laqId  || mockVar.compreLaqQues[compreLaqID].quesId == mockVar.curQuesBean.comprehensionId)) ){
							isComingFromSaveAutomaticallyForCompre = true;
							fnsubmitGroupQuestion('saveSA');
							
						}
						// fnSubmit('saveSA');
						else{
							fnSubmit('saveSA');
						}
					}
				}else{
					fnSubmit('saveSA');
				}
			}else if(mockVar.curQuesBean.quesType =="PROGRAMMING TEST" ){
				fnSubmit('savePrograming');
			}
			else if((mockVar.autoSaveRequired == "false" || mockVar.autoSaveRequired == "true") && mockVar.autoSaveQuesDic!=undefined){
				try{
				var isCompreQues = (mockVar.curQuesBean.comprehensionId!=0 || mockVar.curQuesBean.laqId!=0)?true:false;
				if(isCompreQues){
					
					
					if(mockVar.compreLaqQues[mockVar.questionIndexDetails[mockVar.curQuesBean.comprehensionId!=0?mockVar.curQuesBean.comprehensionId:mockVar.curQuesBean.laqId]].groupComprehensionLaqQuestions == "true"){
						
						if(mockVar.curQuesBean.comprehensionId!=0){
							var addType = mockVar.compreLaqQues[mockVar.questionIndexDetails[mockVar.curQuesBean.comprehensionId]].additionalQuesType;
							if(addType == "" || mockVar.autoSaveQuesDic[addType]){
								isComingFromSaveAutomaticallyForCompre = true;
								fnsubmitGroupQuestion('saveSA');
							}
						}
						else{
							isComingFromSaveAutomaticallyForCompre = true;
							fnsubmitGroupQuestion('saveSA');
						}
						
					}
					else{
						if(mockVar.autoSaveQuesDic[mockVar.curQuesBean.quesType] ||  mockVar.autoSaveQuesDic[mockVar.curQuesBean.comprehensionId!=0?"COMPREHENSION":"LAQ"]){
							fnSubmit('saveSA');
						}
					}
				}else{
					if(mockVar.autoSaveQuesDic[mockVar.curQuesBean.quesType] ){
						if(mockVar.curQuesBean.quesType == "SA" && mockVar.curQuesBean.keyboardType!="FileUpload")
							fnSubmit('saveSA');
						else if(mockVar.curQuesBean.quesType!="SA")
							fnSubmit('saveSA');
					}
				}
			}catch(e){}}
			
		

		
	}
}
