function submitMock(action){
	try{
	 if((sessionStorage.isSecured=="true" &&  sessionStorage.LauncherApps != '6' && ( sessionStorage.operatingSystem=='Mac OS' || sessionStorage.operatingSystem=='Mac OS X' || sessionStorage.operatingSystem=='iOS') && sessionStorage.isPaperDevice == "false")){
		 window.webkit.messageHandlers.stopProctoring.postMessage("stopProctoring") ;
		 }
	}catch(e){
		console.log(e);
	}
	if(sessionStorage.assessmentMode == "2" && caches != undefined){
		caches['delete'](cacheName).then(function(){
			//console.log("cache deleted successfully!!");
		});
	}
	isStopped = true;
	if(mockVar.storeCandResponse == 1){
		saveCandResponse(action);
	}else{
		isFinalSubmitStarted = true;
		mockScoreCalc();
		moveToScoreCardDisplay();
	}
	$('.courseInfoPop').hide();
	theEnd = true;
}

function moveToScoreCardDisplay(){
	if(typeof(mockVar.displayScoreCard)!='undefined' && mockVar.displayScoreCard == 1){
		showScoreCard();
		if(document.URL.indexOf("autoMock") >= 0){
			setTimeout(function(){
				window.location.href = "close.html?"+document.URL.split("html?")[1];
			},document.URL.indexOf("navigationTime")>0?(parseInt(document.URL.split("navigationTime=")[1].split("&")[0])*1000):15000);
		}
	}else{
		if(sessionStorage.photoVerificationRequiredAtEnd=="YES")
		{
			setTimeout(function(){
				window.location.href = "photoVerification.html?"+document.URL.split("html?")[1]+"@@SUBMIT";
			},1000);
		}else
		{
		if(typeof(sessionStorage.scanTime) != "undefined" && sessionStorage.scanTime > 0)
			moveToScanAndUpload();
		else
			moveToFeedback();
		}
	}
	
}
function moveToScanAndUpload(){
	timeSpentOnQrCode(false);
	try{IBA.stopProctoring();}catch(e){
		console.log(e);

	}
	var tempMockVar = {};
	tempMockVar.storeCandResponse = mockVar.storeCandResponse;
	tempMockVar.langName = mockVar.langName;
	tempMockVar.languages = mockVar.languages;
	tempMockVar.defaultLang = mockVar.defaultLang;
	tempMockVar.orgId = mockVar.orgId ;
	tempMockVar.mockId = mockVar.mockId;
	tempMockVar.subscribedFor = mockVar.subscribedFor;
	tempMockVar.candMasterId = mockVar.candMasterId;
	tempMockVar.attemptId = mockVar.attemptId;
	tempMockVar.useDefaultFeedback = mockVar.useDefaultFeedback;
	tempMockVar.isFeedBackRequired = mockVar.isFeedBackRequired;
	sessionStorage.tempMockVar = JSON.stringify(tempMockVar);
	isRedirected = true;
	clearTimeOutMethodCalled = true;
	clearTimeout(mockVar.timeCounter);
	$('.headergrup').hide();
	$('.save_buttoncontainer_2').hide();
	$('.mob_save').hide();
	if(sessionStorage.scanFileType == 3 && (sessionStorage.operatingSystem.toUpperCase() == "WINDOWS" || sessionStorage.operatingSystem.toUpperCase() == "LINUX" || sessionStorage.operatingSystem.toUpperCase() == "UNIX")){
		$('#qrCode').qrcode(sessionStorage.scanCopyURL);
		$('#qrCodeDiv').css({"display":"block"});
		$('#scanCopyUrlValue').append(sessionStorage.scanCopyURL);
		$('#scanCopyUrlValue').css({"display":"block"});
		if(typeof(sessionStorage.userdefinedcandconsole) != "undefined" && sessionStorage.userdefinedcandconsole ==0){
			$('#qrCodeMessage').append($(globalXmlvar).find('qrCodeMessage1').text());}
		else{
			$('#qrCodeMessage').append("Dear Candidate, Please scan the above QR code using your mobile device, capture/scan your written responses and upload the same on to the system.<br/><span style='color:blue;font-style:italic'>Note:Please close this window upon capturing the responses.</span>");}
	} else {
		$('#qrCode').qrcode(sessionStorage.scanCopyURL);
		$('#qrCodeDiv').css({"display":"block"});
		$('#scanCopyUrlValue').append(sessionStorage.scanCopyURL);
		$('#scanCopyUrlValue').css({"display":"block"});
		if(typeof(sessionStorage.userdefinedcandconsole) != "undefined" && sessionStorage.userdefinedcandconsole ==0){
		$('#qrCodeMessage').append($(globalXmlvar).find('qrCodeMessage2').text());
		$('#qrCodeButton').val($(globalXmlvar).find('qrCodeButton').text());
	    }
		else{
			$('#qrCodeMessage').append("Dear Candidate, Please choose any of the following options:<br/>1)To capture/scan your written responses using the mobile device and upload the same on to the system,<br/> please scan the above QR code or launch the URL shown to proceed further.<br/><span style='color:blue;font-style:italic'>Note:Please close this window upon capturing the responses.</span><br/>(OR)<br/>2)To capture/scan your written responses using this device, please click the below button to proceed.");}
		$('#qrCodeButtonDiv').css({"display":"block"});
		//moveToScanAndUploadPage(paramsDetails);
	}
	
}
var exitAfterQRCodeTimeElapsed = false;
function timeSpentOnQrCode(isConfigPage){
	if(typeof(mockVar.timeFormat) == "undefined"){
		mockVar.timeFormat = "MM:SS";
		timerFormatLabel = $(globalXmlvar).find('mmssSpan').text();
	}
		
	 if(typeof(sessionStorage.scanTime) != "undefined"){	
		 $('.timeForQrCode').empty();
		 $('.timeForQrCode').append(convertTime(sessionStorage.scanTime) + timerFormatLabel);
    	}
	 setTimeout(function() {
  		sessionStorage.scanTime = sessionStorage.scanTime - 1;
  		if(sessionStorage.scanTime > 0){
  			timeSpentOnQrCode(isConfigPage);
  		} else {
  			if(isConfigPage)
  				window.close();
  			$('#qrCodeDiv').hide();
  			cnfPop('submitOnlineAssessment');
  			exitAfterQRCodeTimeElapsed = true;
  			$("#submitOnlineMsg").html($(globalXmlvar).find('Eexpired').text());
  		}
  	},1000);
}
function moveToScanAndUploadPage(){
	jQuery.ajax({
		url: "/IBACC/MockAssessmentIBAAction.do",
		async: false,
		type: 'GET',
		dataType: 'text',
	    data:{
			action: 'isResponseUploadPending',
			orgId: sessionStorage.orgId,
			mockId: sessionStorage.assessmentId,
			candMasterId: sessionStorage.cand_master_id,
			attemptNo: sessionStorage.attemptId
		},
		success: function(data) {

			var paramsDetails = 'top=0, left=0';
			paramsDetails += ', width=' + screen.width + ', height=' + screen.height + ',statusbar=no,toolbar=yes,location=no,directories=no,menubar=no,resizable=no';
			paramsDetails += ', scrollbars=yes, status=no, fullscreen=yes';

			if(data=='true') 
				setTimeout(function(){window.open("/OnlineAssessment/scanCopyUpload.html", "_self", paramsDetails);},50);
			else
				setTimeout(function(){window.open("/OnlineAssessment/error.html?Eexpired", "_self", paramsDetails);},50);
		}
	});
}
function moveToFeedback(){
	if(!isProofReadingMock){
		if(mockVar.storeCandResponse == 1){
			setCookie(mockVar.langName);
			var isMockIRC = (sessionStorage.assessType=='Mock')? true : false;
			if(typeof(mockVar.defaultLang)!="undefined" && typeof(mockVar.languages)!="undefined"){
				document.cookie = "defLangName=" + mockVar.languages[mockVar.defaultLang] + ";";}
			else{
				document.cookie = "defLangName=" + sessionStorage.viewLangName  + ";";
			}
			var encodedParam=mockVar.orgId + "@@" + mockVar.mockId;
			if(document.URL.indexOf("eID=")>-1){
				encodedParam=document.URL.split('quiz.html?')[1];
			}
			if((typeof(mockVar.isFeedBackRequired) == "undefined" || mockVar.isFeedBackRequired == "NO" || mockVar.isFeedBackRequired == "0") && !isMockIRC){
					if(mockVar.isSecured == "true" && sessionStorage.assessType == "Actual"){
					//deleteLauncher();
						}
					window.location.href = "close.html?"+encodedParam+"@@"+mockVar.subscribedFor+"#"+(($.cookie("isApp")=="true")?"isApp":"")+(($.cookie("isLauncher")=="true")?"isLauncher":"");
			}else{
				if((typeof(mockVar.isFeedBackRequired) == "undefined" || mockVar.isFeedBackRequired == "NO" || mockVar.isFeedBackRequired == "0") && isMockIRC && (mockVar.isSecured == "true")){
					
					mockSummaryPage();
				}
				else if((typeof(mockVar.isFeedBackRequired) == "undefined" || mockVar.isFeedBackRequired == "NO" || mockVar.isFeedBackRequired == "0")){
					window.location.href = "close.html?"+encodedParam+"@@"+mockVar.subscribedFor+"#"+(($.cookie("isApp")=="true")?"isApp":"")+(($.cookie("isLauncher")=="true")?"isLauncher":"");
				}
				else{
				window.location.href = "FeedBack.html?"+encodedParam+"@@"+mockVar.subscribedFor+"@@"+mockVar.candMasterId+"@@"+mockVar.attemptId+"@@"+mockVar.useDefaultFeedback;
				}
			}
		}else{
			validateScoresInMock();
		}
		}
	else if(document.URL.indexOf("autoMock") >= 0){
		setTimeout(function(){
			window.location.href = "close.html?"+document.URL.split("html?")[1];
		},document.URL.indexOf("navigationTime")>0?(parseInt(document.URL.split("navigationTime=")[1].split("&")[0])*1000):15000);
	}
	else{
		window.close();
		try{

			IBA.exit();
			}catch(e){
				
			}
		}
}
function mockSummaryPage(){
	var URL = "/IBACC/MockAssessmentIBAAction.do?action=IBAMockSummaryPage&orgId="+mockVar.orgId+"&mockId="+sessionStorage.assessmentId+"&attemptId="+sessionStorage.attemptId+"&candId="+sessionStorage.cand_master_id ;
	var paramsvalue = {};
	paramsvalue["mockId"] = sessionStorage.assessmentId;
	paramsvalue["candMasterId"]=sessionStorage.cand_master_id;
	paramsvalue["attemptNo"]=sessionStorage.attemptId;
	jQuery.ajax({
		url : URL,
		async : true,
		type : 'POST',
		data : paramsvalue,
		dataType : 'text',
		success : function(data) {
			if(data!="" ){
			sessionStorage.summaryData= data;
			window.location.href = "MockIRCSummary.html?"+mockVar.orgId +"@@"+mockVar.mockId+"@@"+sessionStorage.cand_master_id+"@@"+mockVar.attemptId;
			}
			else
				{
				window.location.href = "close.html?"+mockVar.orgId +"@@"+mockVar.mockId+"@@"+mockVar.subscribedFor+"#"+(($.cookie("isApp")=="true")?"isApp":"")+(($.cookie("isLauncher")=="true")?"isLauncher":"");
				}
			
		},
	error: function(){
		//error page
		window.location.href="error.html?E103"+(($.cookie("isApp")=="true")?"isApp":"")+(($.cookie("isLauncher")=="true")?"isLauncher":"");
	}
	});
}
