function fnSubmit(action,noQuesLeft,isTImeElapsed){
	 isTimeElapsedToCheckMandQuesWithRevisitNo = isTImeElapsed;
	 if(typeof(mockVar.curQuesBean.saAllowReRecord)=='undefined' || typeof(mockVar.curQuesBean.saReRecordCount)=='undefined' || typeof(mockVar.curQuesBean.NumberOfRecordingsMade)=='undefined' ){
		 mockVar.curQuesBean.saAllowReRecord=true;
		 mockVar.curQuesBean.saReRecordCount=-1;
		 mockVar.curQuesBean.NumberOfRecordingsMade=0;
	 }
	 if(typeof(sessionStorage.userdefinedcandconsole) != "undefined" && sessionStorage.userdefinedcandconsole==1 && mockVar.curQuesBean.quesType == "SA" && mockVar.curQuesBean.keyboardType == "AudioFile" && recordingInProgress){
		 !isDeakin? $('#recordingUploadLoader').show():$('.savingYourResponse').show();
		 stopAudioRecording(false,mockVar.curQuesBean.quesId,mockVar.currentGrp,iOAP.curSection);
	 } else if(mockVar.curQuesBean.quesType == "SA" && (mockVar.curQuesBean.keyboardType == "AudioFile" || mockVar.curQuesBean.keyboardType == "VideoFile") && recordingInProgress && !mockVar.curQuesBean.saAllowReRecord){
		 if(mockVar.storeCandResponse == 1)
			 !isDeakin? $('#recordingUploadLoader').show():$('.savingYourResponse').show();
		 methodToCallPostAudioVideoResponseUploading = "fnSubmit";
		 methodToCallPostAudioVideoResponseUploadingArgs = [action,noQuesLeft,isTImeElapsed];
		 if(mockVar.curQuesBean.keyboardType == "AudioFile")
			stopAudioRecording(false,mockVar.curQuesBean.quesId,mockVar.currentGrp,iOAP.curSection);
		 else
			stopVideoRecording(true);
		 
	 } else if((typeof(sessionStorage.userdefinedcandconsole) == "undefined" || sessionStorage.userdefinedcandconsole== 0) || (mockVar.curQuesBean.quesType != "SA" || mockVar.curQuesBean.keyboardType != "AudioFile") || (resumeQuesId == mockVar.curQuesBean.quesId && mockVar.curQuesBean.quesType == "SA" && typeof(mockVar.curQuesBean.keyboardType) != "undefined" && mockVar.curQuesBean.keyboardType == "AudioFile")) {
		 fnSubmitNew(action,noQuesLeft,isTImeElapsed);
	 } else if(typeof(sessionStorage.userdefinedcandconsole) != "undefined" && sessionStorage.userdefinedcandconsole==1 && mockVar.curQuesBean.quesType == "SA" && (mockVar.curQuesBean.keyboardType == "AudioFile" || mockVar.curQuesBean.keyboardType == "VideoFile") && !recordingInProgressRequired){
         fnSubmitNew(action,noQuesLeft,isTImeElapsed);
     }
	 if(sessionStorage.IBASkinningReq=='true'){
		 adjustUIibaSkinning();
	 }
	 //focusMainQues(action);
	 triggerNumberPanel("currentQues");
}
