function fillMaxOptQuesCrossedGroup(quesToBeConsidered,totalQuestions,isGroup){
	var str= "",alertMsg = "";
	if(isGroup=="grpLimit"){
		if(mockVar.isMarkedForReviewConsidered == "YES"){
			alertMsg = mockLabels.QuestionLimitMessageWithMarkedForReviewAtGroupLevel;
		}else{
			alertMsg = mockLabels.QuestionLimitMessageOnlyAnsweredAtGroupLevel;
		}
	}
	else{
	if(mockVar.isMarkedForReviewConsidered == "YES"){
		alertMsg = mockLabels.maxQuesCrossedWithMarkReview;
	}else{
		alertMsg = mockLabels.maxQuesCrossedWithoutMarkReview;
	}
	}
	str = '<div role="alert" class="warningMsgDivMaxQuesCross" id="warningMsgDiv" style="display: flex; align-items: center; background-color:#F5F6CE; border:1px solid #FE9A2E; padding: 1%; margin: 1%; font-size: 12px">';
	str += '<span style="margin: 10px;"><img src="images/warning-icon.png" /></span>';
	str += '<span><b>Note : </b>';
	str += alertMsg.replace('@@quesToBeConsidered@@',quesToBeConsidered).replace('@@totalQuestions@@',totalQuestions);
	str += '</span></div>';
	 $('#warningMsgDiv').remove();
	 $("#groupWarning").append(str);
	/*
	 * if( mockVar.curQuesBean.comprehensionId != 0 ||mockVar.curQuesBean.laqId !=
	 * 0){ $("#warning").prepend(str); } else $("#quesAnsContent").prepend(str);
	 */
}
function updateVisitedCount(quesId){
	try{
		if(typeof(mockVar.visitedQuestions) == "undefined")
			mockVar.visitedQuestions = [];
		if(mockVar.visitedQuestions.indexOf(quesId) == -1){
			mockVar.visitedQuestions.push(quesId);
			if(typeof(iOAP.secDetails[iOAP.curSection].visitedCount) == "undefined")
				iOAP.secDetails[iOAP.curSection].visitedCount = 0;
			if(mockVar.curQuesBean.issubjectivequestion == "true")
				iOAP.secDetails[iOAP.curSection].visitedCount++;
		}
		}catch(e){}
}
