function closeTimeInterval(){
	if (mockVar.timeCounterReplay != undefined)clearTimeout(mockVar.timeCounterReplay);	
	$('.overlay').hide();
	$('.confrmPopup').hide();
}

function startReplayCounter(reCounter){
	if(reCounter>-1){
			var min = Math.floor(reCounter/60);
			var sec = reCounter%60;
			var str = 'Please wait for <b>';
			if(min<10&&sec<10){
				if(min==0){
					str = str +'0'+sec+' Sec</b>';
				}
				else{
					str = str + '0' + min+' Min 0'+sec+' Sec</b>';
				}
				
			}
			else if(min<10&&sec>9){
				if(min==0){
					str = str +sec+' Sec</b>';
				}
				else{
					str = str + '0' + min+' Min '+sec+' Sec</b>';
				}
				
			}
			else if(sec<10&&min>9){
				str = str + min+' Min 0'+sec+' Sec</b>';
			}
			else{
				str = str + min+' Min '+sec+' Sec</b>';
			}
			$("#infoMsg2").html(str+' to replay.');
			mockVar.timeCounterReplay=setTimeout(function(){startReplayCounter(reCounter-1);},1000);
	}
	else{
		closeTimeInterval();
	}
}
function setTimeIntervalCounter(timeIntervalToReplay,i,j,type){
	if(type == "claq"){
		if(timeIntervalToReplay>-1)
		{
			mockVar.compreLaqQues[i].jwAudioVideo[j].timeIntervalToReplay = mockVar.compreLaqQues[i].jwAudioVideo[j].timeIntervalToReplay-1;
			mockVar.timeIntervalCounter = setTimeout(function(){setTimeIntervalCounter(timeIntervalToReplay-1,i,j,"claq");},1000);
		}
		else
		{
			this.mockVar.compreLaqQues[i].jwAudioVideo[j].timeIntervalToReplay = this.mockVar.compreLaqQues[i].timeIntervalToReplay;
			// if (mockVar.timeIntervalCounter !=
			// undefined)clearTimeout(mockVar.timeIntervalCounter);
		}
	}
	else{
		if(timeIntervalToReplay>-1)
		{
			mockVar.curSectionQuestions[i].jwAudioVideo[j].timeIntervalToReplay = mockVar.curSectionQuestions[i].jwAudioVideo[j].timeIntervalToReplay-1;
			mockVar.timeIntervalCounter = setTimeout(function(){setTimeIntervalCounter(timeIntervalToReplay-1,i,j,"");},1000);
		}
		else
		{
			this.mockVar.curSectionQuestions[i].jwAudioVideo[j].timeIntervalToReplay = this.mockVar.curSectionQuestions[i].timeIntervalToReplay;
			// if (mockVar.timeIntervalCounter !=
			// undefined)clearTimeout(mockVar.timeIntervalCounter);
		}
	}
}
