var outFocusTime=0;
var onFocusTime=0;
var outFocused = false;
var timeDifference=0;
var mockVarTimeWhenOutFocused = 0;
var timerStarted = true;
var ignoreTImerDiscrepancy = false;
window.addEventListener("blur", function(event) {
	if(timerStarted){
		outFocusTime= new Date().getTime();mockVarTimeWhenOutFocused= mockVar.time; outFocused= true;
		}
	});
window.addEventListener("focus", function(event) {
	if(timerStarted){
		if(outFocused){
			onFocusTime= new Date().getTime();timeDifference =onFocusTime-outFocusTime;  outFocused=false;
			}
		}
	});

function examTimerHalted(){
	if(!ignoreTImerDiscrepancy && timeDifference>0 && mockVar.storeCandResponse == 1 && !isFileUploadStarted && !isStopped && !isOfflineIBA){
		if((parseInt(timeDifference/1000)-(mockVarTimeWhenOutFocused-mockVar.time))>15){
		timeDifference = 0;
		saveBackUp(false);
		toErrorPage=true;
		var AuditJsonObject = new Object();
		AuditJsonObject.ActionName = "Candidate moved out of the Exam Window";
		AuditJsonObject.ActionDesc = "Assessment moved to error page";
		AuditJsonObject.GroupId = "NA";
		AuditJsonObject.SectionId = "NA";
		AuditJsonObject.QuestionId = "NA";
		AuditJsonObject.SelectedOptionId = "NA";
		AuditJsonObject.OptionSequence = "NA";
		AuditJsonObject.candidateName = sessionStorage.isOfflinePaper=='1' ? sessionStorage.username : $.cookie("username");
		AuditJsonObject.loginId = sessionStorage.isOfflinePaper=='1' ? sessionStorage.username : $.cookie("loginId");
		var currentDate = new Date();
		AuditJsonObject.Time = currentDate.yyyymmddHHmmss();
		AuditJsonObject.eventTimestamp = Date.now();
		AuditJsonObject.mockVarLoginId = mockVar.loginId;
		if(!isExaminer){
		AuditJson.push(AuditJsonObject);
		}
		isFileUploadStarted = false;
		breakTimeStarted = false;
		window.location.href ="error.html?E143"+(($.cookie("isApp")=="true")?"isApp":"")+(($.cookie("isLauncher")=="true")?"isLauncher":"");
		}
	}
}
