function breakTimeCounter(time){
	if(mockVar.isBreakPage)
		mockVar.resumedFromBreakPage = 1;
	else
		mockVar.resumedFromBreakPage = 0;
	breakTimeStarted = true;
	mockVar.remainingBreakTime=time;
	if(ringTheBell && ringTheBellTimeLeft>0){
		ringTheBellTimeLeft=ringTheBellTimeLeft-1;
	}
	if(ringTheBell && ringTheBellTimeLeft<=0){
		timeOutSubmit();
	}else{
		isDeakin?circleTimerDeakin("Break",time,mockVar.groups[mockVar.currentGrp].breakTime):'';
		$("#breakTimeCounter").html( "<b>"+mockLabels.breakTimeLeft+convertTime(time , -1)+"</b>");
		if(time>0){
			clearTimeout(mockVar.timeCounter);
			mockVar.timeCounter = setTimeout(function(){breakTimeCounter(time-1);},1000);

		}else{
			if(!alreadySubmitCalled)
			submitGroup();
		}
	}
}
var alreadySubmitCalled = false;
$("#proceedToNextGrp").click(function(){alreadySubmitCalled=true;});
