function removeActiveLinks(){
	const isGrpInstruVisible = $("#grpInstruction").is(":visible");
	const isSecInstruVisible = $("#secInstruction").is(":visible");
	const isQuesInstruVisible = $("#quesInstruction").is(":visible");
	if(isQuesInstruVisible){
		auditLogForQuesInstruHyperLink("Question Instruction Page HyperLink viewed",quesInstructionTimerForHyperLink);
	}
	if(isSecInstruVisible){
		auditLogForQuesInstruHyperLink("Section Instruction Page HyperLink closed","NA");
	}
	quesInstructionTimerForHyperLink = 0;
	m_iframeCount=0;
	for(var i=0;i<mockVar.activeLinkList.length;i++){
		$("#"+mockVar.activeLinkList[i]).removeAttr('style');
	}
	$(".overlaypopup").fadeOut();
	$(".maximg_popup").fadeOut();
	try{
	stopPlayingVideo();
	}
	catch(e){}
	if((isQuesInstruVisible || isSecInstruVisible || isGrpInstruVisible) && (sessionStorage.enableVoiceOver==='YES' || mockVar.enableVoiceOver==='YES')){
		instantiateVOobj();
		fillQuesContent();
	}
	try{
		if($("#instructionsDiv").is(":visible")){
			magnifier.hide();
	      window.magnifier?.hide();
		 magnifier = new HTMLMagnifier({ width: 300 });
		}
		
			
		}
		catch(e){
		}
}

function showSecInstructionsQuiz(flag){
	$('.mContent').removeClass('watermark mContent2');
	$('.preGrpInst span').text(secInstruLabel);
	breakTimeStarted = true;
	currentGroupIndex = mockVar.currentGrp;
	currentSectionIndex = iOAP.curSection;
	var str="";
	var content1="The instructions are not available in the chosen language";
	var valSec = true;
	// if(($(window).width()<1000 || "ontouchstart" in document.documentElement)
	// && !($(window).width()>1300)){
	if($(window).width()<1000){	
	if(Object.keys(secInstru[mockVar.groups[currentGroupIndex].secDetails[currentSectionIndex].secId]).length>2){
			str += "<div class='instView'> <span class='viewIn'>"+mockLabels.viewIn+"</span>&nbsp; <select onchange='changeSecInst(this.value)'> ";

			for(var i=0;i< Object.keys(secInstru[mockVar.groups[currentGroupIndex].secDetails[currentSectionIndex].secId]).length;i++){
				langId=  Object.keys(secInstru[mockVar.groups[currentGroupIndex].secDetails[currentSectionIndex].secId])[i];
				if(mockVar.languages[langId]!=null && typeof(mockVar.languages[langId])!='undefined'){
					str +="<option";
					if(langId==mockVar.defaultLang)
						str += " selected='selected'";
					str +=  " value='"+langId+"'>"+mockVar.languages[langId]+"</option>";
				}
			}
			str +="</select></div>";
		}
		// if(flag!='isSecShow'){
		$('#InstruContent').empty();
		$('.iconRemoveSign ').click();
		$('.viewInstructionsDiv').empty();
		// }
		str+="<div class='viewInstructionsDiv preGrpinstruContent'>";
		str+="<div class='popUpIns' style='margin-bottom: 10px;'>Section Instructions</div>";
		for(var i=1; i<=Object.keys(secInstru[mockVar.groups[currentGroupIndex].secDetails[currentSectionIndex].secId]).length;i++){
			langId = Object.keys(secInstru[mockVar.groups[currentGroupIndex].secDetails[currentSectionIndex].secId])[i-1];
			content = secInstru[mockVar.groups[currentGroupIndex].secDetails[currentSectionIndex].secId][langId];
			if(mockVar.enableVoiceOver=='YES'){
				inputTxt=formQuestionTextForVoiceOver(content);
			}
			str+="<div class='SecInst"+langId+" instructionMedia'  style='display:none;height:100%; text-align: left;'>"+voiceOverHtml+replaceQuesText(content)+"</div>";
			if(content1!=content){
			valSec= false;
			}
		}
		str+="</div>";
		$(".mContent").html(str);
		if(!valSec && flag!='isSecShow'){
			$(".mpop1").fadeIn('slow');
			$('.overlay').show();
			$(".mpop1 table").css({'text-align':'left'});
		}

	}

	else {
		$(".secInst").empty();
		for(var i=0;i< Object.keys(secInstru[mockVar.groups[currentGroupIndex].secDetails[currentSectionIndex].secId]).length;i++){
			langId=  Object.keys(secInstru[mockVar.groups[currentGroupIndex].secDetails[currentSectionIndex].secId])[i];
			if(mockVar.languages[langId]!=null && typeof(mockVar.languages[langId])!='undefined'){
				o = new Option(mockVar.languages[langId], langId);
				$(o).html(mockVar.languages[langId]);
				$(".secInst").append(o);
			}
		}
		if(Object.keys(secInstru[mockVar.groups[currentGroupIndex].secDetails[currentSectionIndex].secId]).length>1)
			$(".instView").show();
		else
			$(".instView").hide();
		
		// if(flag!='isSecShow'){
		$('#InstruContent').empty();
		$('.iconRemoveSign ').click();
		$('.viewInstructionsDiv').empty();
		// }
		for(var i=1; i<=Object.keys(secInstru[mockVar.groups[currentGroupIndex].secDetails[currentSectionIndex].secId]).length;i++){
			langId = Object.keys(secInstru[mockVar.groups[currentGroupIndex].secDetails[currentSectionIndex].secId])[i-1];
			content = secInstru[mockVar.groups[currentGroupIndex].secDetails[currentSectionIndex].secId][langId];
			if(mockVar.enableVoiceOver=='YES'){
				inputTxt=formQuestionTextForVoiceOver(content);
			}
			$('.viewInstructionsDiv').append("<div class='SecInst"+langId+" instructionMedia'  style='display:none;height:100%; text-align: left;'>"+voiceOverHtml+replaceQuesText(content)+"</div>");	
			if(content1!=content){
			valSec= false;
			}
		}
	}
	$('.SecInst'+ Object.keys(secInstru[mockVar.groups[currentGroupIndex].secDetails[currentSectionIndex].secId])[0]).show();
	$('.viewInstructionsDiv').css({height:(($(window).height()-($(window).height()*0.2))-25)+'px',width:(($(window).width()-($(window).width()*0.2))-5)+'px'});
		if(flag==undefined )
		playMedia(); // undefined meaning it is coming from the hyperlink
		else 
		$('.viewInstructionsDiv').empty();
		
		instantiateVOobj();
	return valSec;
}


