function getIEVersion() {
	try{
		var rv = -1;
		if (navigator.appName == 'Microsoft Internet Explorer') {
			var MSIEOffset = window.navigator.userAgent.indexOf("MSIE ");
			if (MSIEOffset == -1) {
				rv = -1;
			} else {
				rv = parseFloat(window.navigator.userAgent.substring(MSIEOffset + 5, window.navigator.userAgent.indexOf(";", MSIEOffset)));
			}
		}
		return rv;
	}catch(e) {
		return false;
	}
}

// This function is used to check Browser is Compatible or not for Candidate
// Machine.
function checkIEVersion(){
	try{
		var currentIEVersion = getIEVersion();
		if((currentIEVersion >=7 && currentIEVersion != -1) || (($.support.msie || navigator.userAgent.indexOf("Trident")!=-1) && $.support.version>=7)) {
			return true;
		}else {
			return false;
		}
	}catch(e) {
		return false;
	}
}

