		if(mockVar.timeFormat=='MM:SS')
			timerFormatLabel=$(globalXmlvar).find('mmssSpan').text();
		else if(mockVar.timeFormat=='HH:MM:SS')
			timerFormatLabel=$(globalXmlvar).find('hhmmssSpan').text();
		else if(mockVar.timeFormat=='HH:MM')
			timerFormatLabel=$(globalXmlvar).find('hhmmSpan').text();
