function checkRPVideosActivity(){
	try{
		if(sessionStorage.browserProctoring !=undefined && sessionStorage.browserProctoring.toUpperCase()=='YES' && sessionStorage.remoteProctoring == "1"){
			var freqTime = parseInt(sessionStorage.gapBetweenRecordings)+parseInt(sessionStorage.durationOfRecording)+(60*3);
			setTimeout(function(){
				try{
					if(currentRemoteProctoringId == 0 || previousCurrentRemoteProctoringId < currentRemoteProctoringId){
						previousCurrentRemoteProctoringId = currentRemoteProctoringId;
						checkRPVideosActivity();
						if(currentRemoteProctoringId==0)
							currentRemoteProctoringId++;
					} else if((mockVar.storeCandResponse == "1" || mockVar.storeCandResponse == 1)&& !isAssessmentSubmitted) {

						cnfPop('backupAlerts');hideCloseAndOkayForSecuredAssessments();
						$("#backupAlertMsg").html($(globalXmlvar).find('RPVideosInactive').text());
						if(sessionStorage.isSecured=="true" && sessionStorage.LauncherApps != '6' && sessionStorage.operatingSystem !=undefined && (sessionStorage.operatingSystem=='Mac OS' || sessionStorage.operatingSystem=='Mac OS X' || sessionStorage.operatingSystem=='iOS') && sessionStorage.isPaperDevice == "false")
						{
							$(".shiftEsc").html($(globalXmlvar).find('shiftEscMac').text());
							//$(".okayOrNoButtonWindowClosePopup").show();

						}
					}
				}catch(e){
					console.log(e);
				}
			},freqTime*1000);
		}
	}catch(e){
		console.log(e);
	}

}
