function cnfPop(id,finalSubmit){
	if(mockVar.isCAT && sessionStorage.userdefinedcandconsole=='0' && id=='revisitPopup') {
		fnSubmit('NEXT');
		return;
		}
	 lastFocusedElement = document.activeElement;
	if($('#shortCutPopup').is(':visible')){$('#shortCutPopup').hide();}
	if(sessionStorage.IBASkinningReq == 'true' && (id == 'confirmProceedPopup')){
		$('#'+id).show();
		if(finalSubmit=='true'){
			$('.confirmationText').html('<h4>You have successfully<h4><h3>submitted your exam.</h3>');
			$('.commanmodal-footer').html('<button type="button" class="primaryBtnClr viewExamSummaryAction" onclick="">View Exam Summary</button>');
		}
		$('.groupDescriptionPopup').html($(globalXmlvar).find('group').text()+' '+(mockVar.currentGrp+1)+' - '+$(globalXmlvar).find('Section').text()+' '+(iOAP.curSection+1)+': '+iOAP.secDetails[iOAP.curSection].secName);
	}
	else{
	$('#loadCalc').hide();
	$('.overlay').show();
	$('#'+id).show();
	var pLft = ( $(window).width() - $('#'+id).width() )/2;
	var pTop = ( $(window).height() - $('#'+id).height() )/2;
	$('#'+id).css({'left':pLft+'px'});
	$('#'+id).css({'top':pTop+'px'});
		adjustFocusCnfPop(id);
	}
	setTimeout(() => {
		  $('#'+id).focus();
		}, 200);
}

function adjustFocusCnfPop(id){
	$('.cnfPopHdr').attr('aria-hidden','true');
	$('.cnfPopBdy').attr('aria-hidden','true');
	$('.cnfPopBtnPnl').attr('aria-hidden','true');
	const btnId = lastClickedElement?lastClickedElement.id:'';
	trapFocusUtilityForCnfPop(id,btnId);
	setTimeout(function(){
		$('.cnfPopHdr').attr('aria-hidden','false');
	    $('.cnfPopBdy').attr('aria-hidden','false');
		$('.cnfPopBtnPnl').attr('aria-hidden','false');
	},200);
}

