function isAssessmentMock(){
	var URL =document.URL;
	var mockId = "";
	if(URL.indexOf("quiz.html?") >=0){
		var params = URL.split("quiz.html?");
		if(params[1].indexOf("eID=")==-1)
			mockId = $.trim(params[1]).split("@@")[1];
		else
			mockId=sessionStorage.assessmentId;
	} else if(URL.indexOf("quiz.html") >=0){
		mockId = $.cookie("assessmentId") == undefined ? sessionStorage.assessmentId : $.cookie("assessmentId");
		mockId = ((mockId == undefined || mockId == "") ? "M" : mockId);			
		currentMockId = mockId;
	}
	if(mockId!=undefined ? (mockId.indexOf("M")!=-1) : false){
		validateQuizPageUrl(true);
	}
}
