function disablePlayOnClick(videoJsObject){
	if(document.getElementById("revisitGroup")){
	revisitNotAllowedGroupSubmitPopUpLive=false;
	$("#InfoPopup .cnfPopBtnPnl").html("<a class='greenBtn cnfPopNo Ok' onclick='closeTimeInterval();'  onkeypress='clickThisElement(this,event);' role='button' tabindex='0'>Ok</a>");
	$(".popClose").show();
	}
	var videoJSPlayer =  videoJsObject.player();
	var playerOptions = videoJsObject.player().options();
	var playerId = videoJsObject.player().id();
	if(playerId.startsWith('VideoJS-instructionMedia'))
		return false;
	if(!playerOptions.IBAParams.isCompreLaqMedia){
		var i = playerOptions.IBAParams.mediaPosition_i,j =playerOptions.IBAParams.mediaPosition_j;
		
		if (mockVar.curSectionQuestions[i].noOfReplays >=0 && mockVar.curSectionQuestions[i].jwAudioVideo[j].noOfReplays == mockVar.curSectionQuestions[i].noOfReplays) {
			if(videojs(playerId).isFullscreen())
				videojs(playerId).exitFullscreen();
			if(showPopupInCC){
				cnfPop('InfoPopup');
				$("#infoMsg2").html($(globalXmlvar).find('videoReplaysExceeded').text());
			}
			return true;
		} else if (mockVar.curSectionQuestions[i].jwAudioVideo[j].timeIntervalToReplay>-1&&mockVar.curSectionQuestions[i].jwAudioVideo[j].timeIntervalToReplay<mockVar.curSectionQuestions[i].timeIntervalToReplay){
		
			if(videojs(playerId).isFullscreen())
			  videojs(playerId).exitFullscreen();
            if(showPopupInCC){
                cnfPop('InfoPopup');
                $("#InfoPopup .cnfPopBtnPnl").html("<a class='greenBtn cnfPopNo Ok' onclick='closeTimeInterval();'  onkeypress='clickThisElement(this,event);' role='button' tabindex='0'>Ok</a>");
            }
            reCounter = mockVar.curSectionQuestions[i].jwAudioVideo[j].timeIntervalToReplay+1;
            startReplayCounter(reCounter);
            return true;
        }
		else if (mockVar.curSectionQuestions[i].allowedProgression.toLowerCase() == "false") {
			var jwpId =playerId;
			if (is_ie10 == false)
				videojs(jwpId).controlBar.progressControl.disable();
			else
				videojs(jwpId).controlBar.progressControl.hide();
		}
		if(!videoJSPlayer.paused() && mockVar.curSectionQuestions[i].isControlEnable == "false" )
			return true;
		 return false;
	}else{
		var i = playerOptions.IBAParams.mediaPosition_i,j =playerOptions.IBAParams.mediaPosition_j;
		if (mockVar.compreLaqQues[i].noOfReplays >=0 && mockVar.compreLaqQues[i].jwAudioVideo[j].noOfReplays == mockVar.compreLaqQues[i].noOfReplays) {
			if(videojs(playerId).isFullscreen())
				  videojs(playerId).exitFullscreen();
			if(showPopupInCC){
				cnfPop('InfoPopup');
				$("#infoMsg2").html($(globalXmlvar).find('videoReplaysExceeded').text());
			}
			return true;
		} else if (mockVar.compreLaqQues[i].jwAudioVideo[j].timeIntervalToReplay>-1&&mockVar.compreLaqQues[i].jwAudioVideo[j].timeIntervalToReplay<mockVar.compreLaqQues[i].timeIntervalToReplay){
		
	
			if(videojs(playerId).isFullscreen())
			  videojs(playerId).exitFullscreen();
            if(showPopupInCC){
                cnfPop('InfoPopup');
                $("#InfoPopup .cnfPopBtnPnl").html("<a class='greenBtn cnfPopNo Ok' onclick='closeTimeInterval();'  onkeypress='clickThisElement(this,event);' role='button' tabindex='0'>Ok</a>");
            }
            reCounter = mockVar.compreLaqQues[i].jwAudioVideo[j].timeIntervalToReplay+1;
            startReplayCounter(reCounter);
            return true;
        }else if (mockVar.compreLaqQues[i].allowedProgression.toLowerCase() == "false") {
			var jwpId = playerId;
			if (is_ie10 == false)
				videojs(jwpId).controlBar.progressControl.disable();
			else
				videojs(jwpId).controlBar.progressControl.hide();
		}
		if(!videoJSPlayer.paused() && mockVar.compreLaqQues[i].isControlEnable == "false" )
			return true;
		 return false;
	}
}
function checkAndAdd(name) {
	if (!Array.prototype.some) {
		Array.prototype.some = function(func) {
			for (var i in this) {
				if (func(i)) return true;
			}
			return false;
		};
	}
	// var curSec = iOAP.secDetails[iOAP.curSection];
	var jwQuesId = name.split("_")[1];
	var cLaq = name.split("_")[2];
	if (cLaq !== "Claq") {
		for (var i = 0; i < mockVar.curSectionQuestions.length; i++) {
			if (mockVar.curSectionQuestions[i].quesId == jwQuesId) {
				var found = mockVar.curSectionQuestions[i].jwAudioVideo.some(function(el) {
					return el.jwplayerId == name;
				});
				if (!found) { mockVar.curSectionQuestions[i].jwAudioVideo.push({ jwplayerId: name, jwplayerVol: 1,jwplayerPosn: "", noOfReplays: -1, timeIntervalToReplay: mockVar.curSectionQuestions[i].timeIntervalToReplay }); }
				break;
			}
		}
	} else {
		if (mockVar.compreLaqQues.length != 0) {
			for (var i = 0; i < mockVar.compreLaqQues.length; i++) {
				if (mockVar.compreLaqQues[i].quesId == jwQuesId) {
					var found = mockVar.compreLaqQues[i].jwAudioVideo.some(function(el) {
						return el.jwplayerId == name;
					});
					if (!found) { mockVar.compreLaqQues[i].jwAudioVideo.push({ jwplayerId: name, jwplayerVol: 1,jwplayerPosn: "", noOfReplays: -1, timeIntervalToReplay: mockVar.compreLaqQues[i].timeIntervalToReplay }); }
					break;
				}
			}
		}
	}
}
