function makeMediaDiv(content){
	if (content.indexOf("<audio>") != -1) {
		var newAudioFile = new Array();
		newAudioFile = content.match(/(<audio>.+?<audio>)/g);
		if(newAudioFile!=null){
			for (var i = 0; i < newAudioFile.length; i++) {
				while (content.indexOf(newAudioFile[i]) != -1) {
					content = content.replace(newAudioFile[i], "<div class='UsefuljwAudioVideo' id='jwAudio"+counter.value()+"' title='hasmedia@@tkcimages/" + newAudioFile[i].split("<audio>")[1] + "hasmedia@@'></div>");
					try{
						if(isProofReadingMock =="true")getFileInBlob('/tkcimages/'+ newAudioFile[i].split("<audio>")[1], newAudioFile[i].split("<audio>")[1],"","")
					}catch(e){
						console.log(e);
					}
					counter.increment();
				}
			}
		}
	}
	if (content.indexOf("<video>") != -1) {
		var newVideoFile = new Array();
		newVideoFile = content.match(/(<video>.+?<video>)/g);
		if(newVideoFile!=null){
			for (var i = 0; i < newVideoFile.length; i++) {
				while (content.indexOf(newVideoFile[i]) != -1) {
					content = content.replace(newVideoFile[i], "<div class='UsefuljwAudioVideo' id='jwVideo"+counter.value()+"' title='hasmedia@@tkcimages/" + newVideoFile[i].split("<video>")[1] + "hasmedia@@'></div>");
					try{
						if(isProofReadingMock =="true")getFileInBlob('/tkcimages/'+ newVideoFile[i].split("<video>")[1], newVideoFile[i].split("<video>")[1],"","")
					}catch(e){
						console.log(e);
					}
					counter.increment();
				}
			}
		}
	}
	return content;
}



// Added by sai for extra time
function divideScribeTimeForGroups(flag){
	var auditExtraTimeObj = {};
	if(flag){
		clearTimeout(mockVar.timeCounter);
		for(var i=0;i<mockVar.groups.length;i++){
			mockVar.groups[i].minTime=Math.round(mockVar.groups[i].minTime+((mockVar.groups[i].minTime*parseFloat(scribeExtraTime))/100));
			mockVar.groups[i].breakTime = Math.round(mockVar.groups[i].breakTime+((mockVar.groups[i].breakTime*parseFloat(scribeExtraTime))/100));
			mockVar.groups[i].maxTime=Math.round(mockVar.groups[i].maxTime+((mockVar.groups[i].maxTime*parseFloat(scribeExtraTime))/100));
			if(i<mockVar.currentGrp){
				mockVar.groups[i].isViewable=true;
				mockVar.groups[i].isEditable=true;
			}
			auditExtraTimeObj["AssignedExtraTimeForGroup "+mockVar.groups[i].groupName] = mockVar.groups[i].maxTime;
			for(var j=0;j<mockVar.groups[i].secDetails.length;j++){
				for(var k=0;k<mockVar.groups[i].secDetails[j].questions.length;k++){
					if(mockVar.groups[i].secDetails[j].questions[k].maxTime>0){
						mockVar.groups[i].secDetails[j].questions[k].maxTime=Math.round(mockVar.groups[i].secDetails[j].questions[k].maxTime+((mockVar.groups[i].secDetails[j].questions[k].maxTime*parseFloat(scribeExtraTime))/100));
						auditExtraTimeObj["AssignedExtraTimeForQues "+mockVar.groups[i].secDetails[j].questions[k].quesId] = mockVar.groups[i].secDetails[j].questions[k].maxTime;
					}
				}
			}
		}
		mockVar.nonTimeBoundTime=Math.round(mockVar.nonTimeBoundTime+((mockVar.nonTimeBoundTime*parseFloat(scribeExtraTime))/100));
		mockVar.time=Math.round(mockVar.time+((mockVar.time*parseFloat(scribeExtraTime))/100));
		mockVar.completeTime=Math.round(mockVar.completeTime+((mockVar.completeTime*parseFloat(scribeExtraTime))/100));
		auditExtraTimeObj["AssignedExtraCompleteTime "] = mockVar.completeTime;
		mockVar.scribeExtraTimeConsumed=1;
		try{auditlogCreation("Assigned Extra Time",JSON.stringify(auditExtraTimeObj),"Assigned Extra Time");}catch(e){console.log(e);}
		//console.log("divide scribe for groups::"+mockVar.completeTime);
		if(!isExaminer){
			timer(26732);// Timer should not be displayed to the examiner as he can
					// resume after candidate consume the whole time
		}else{
			enableOrDisableSubmitForExaminer();
		}
	}
	else{
		if(mockVar.groupConfigArray!=undefined && mockVar.groupConfigArray.length>0 && mockVar.nonTbTime!=undefined && mockVar.nonTbTime>=0){
			//console.log("divide candextratime for groups::");
			divideCandExtraTime();
		}
	}
}
function divideCandExtraTime(){
	var auditExtraTimeObj = {};
	var timeForCurrentGrp=0;
	clearTimeout(mockVar.timeCounter);
	for(var i=0;i<mockVar.groups.length;i++){
		mockVar.groups[i].groupextratime = (mockVar.groups[i].groupextratime ?? 0) + parseFloat(candidateExtraTime); //defect_501250 fix
		//console.log(typeof mockVar.groups[i].extratime);
		mockVar.groups[i].minTime=Math.round(mockVar.groups[i].minTime+((mockVar.groupConfigArray[i].minTime*parseFloat(candidateExtraTime))/100));
		mockVar.groups[i].maxTime=Math.round(mockVar.groups[i].maxTime+((mockVar.groupConfigArray[i].maxTime*parseFloat(candidateExtraTime))/100));
		if(i<mockVar.currentGrp){
			mockVar.groups[i].isViewable=true;
			mockVar.groups[i].isEditable=true;
		}
		auditExtraTimeObj["AssignedExtraTimeForGroup "+mockVar.groups[i].groupName] = mockVar.groups[i].maxTime;
		for(var j=0;j<mockVar.groups[i].secDetails.length;j++){
			for(var k=0;k<mockVar.groups[i].secDetails[j].questions.length;k++){
				if(mockVar.groups[i].secDetails[j].questions[k].maxTime>0){
					mockVar.groups[i].secDetails[j].questions[k].maxTime=Math.round(mockVar.groups[i].secDetails[j].questions[k].maxTime+((mockVar.groups[i].secDetails[j].questions[k].maxTime*parseFloat(candidateExtraTime))/100));
					auditExtraTimeObj["AssignedExtraTimeForQues "+mockVar.groups[i].secDetails[j].questions[k].quesId] = mockVar.groups[i].secDetails[j].questions[k].maxTime;
				}
			}
		}
	}
	if(parseInt(mockVar.groupConfigArray[mockVar.currentGrp].maxTime)!=0){
		timeForCurrentGrp=Math.round((mockVar.groupConfigArray[mockVar.currentGrp].maxTime*parseFloat(candidateExtraTime))/100);
	}else{
		timeForCurrentGrp=Math.round((mockVar.nonTbTime*parseFloat(candidateExtraTime))/100);
	}
	mockVar.nonTimeBoundTime=Math.round(mockVar.nonTimeBoundTime+(mockVar.nonTbTime*parseFloat(candidateExtraTime))/100);
	mockVar.time=Math.round(mockVar.time+timeForCurrentGrp);
	if(mockVar.totalDurationOfAssessment!=undefined)
		mockVar.completeTime=Math.round(mockVar.completeTime+((mockVar.totalDurationOfAssessment*parseFloat(candidateExtraTime))/100));
	else
		mockVar.completeTime=Math.round(mockVar.completeTime+((mockVar.completeTime*parseFloat(candidateExtraTime))/100));
	auditExtraTimeObj["AssignedExtraCompleteTime "] = mockVar.completeTime;
	mockVar.candidateExtraTimeConsumed=1;
	//console.log("divide canextratime for groups::"+mockVar.completeTime);
	try{auditlogCreation("Assigned Extra Time",JSON.stringify(auditExtraTimeObj),"Assigned Extra Time");}catch(e){console.log(e);}
	if(!isExaminer){   
		if($('#instruTimeDiv').is(":visible") || $('#quesInstruTimeDiv').is(":visible")){ // added
																							// by
																							// sreejith
																							// -
																							// for
																							// extra
																							// time
			if($('.preGrpInst span').text().split(' ')[0]=='Section')
			     instruTimeCounterForSec(mockVar.remainingInstruTime);
			else
			if($('.preGrpInst span').text().split(' ')[0]=='Group')
				instruTimeCounter(mockVar.remainingInstruTime);	
			/*if($('#quesInstru').text().split(':')[0].trim()=='Question Instructions')
				instruTimeCounterForQues(mockVar.remainingInstruTime);*/
			if($('#quesInstru').hasClass("quesInstruc"))
				instruTimeCounterForQues(mockVar.remainingInstruTime);
		} // end - sreejith
		else
		timer(26792);// Timer should not be displayed to the examiner as he can
				// resume after candidate consume the whole time
	}else{
		enableOrDisableSubmitForExaminer();
	}
}

(function() {
	var params = {},
	r = /([^&=]+)=?([^&]*)/g;
	function d(s) {
		return decodeURIComponent(s.replace(/\+/g, ' '));
	}
	var match, search = window.location.search;
	while (match = r.exec(search.substring(1))) {
		params[d(match[1])] = d(match[2]);

		if(d(match[2]) === 'true' || d(match[2]) === 'false') {
			params[d(match[1])] = d(match[2]) === 'true' ? true : false;
		}
	}
	window.params = params;
})();

function addStreamStopListener(stream, callback) {
	var streamEndedEvent = 'ended';
	if ('oninactive' in stream) {
		streamEndedEvent = 'inactive';
	}
	stream.addEventListener(streamEndedEvent, function() {
		callback();
		callback = function() {};
	}, false);
	stream.getAudioTracks().forEach(function(track) {
		track.addEventListener(streamEndedEvent, function() {
			callback();
			callback = function() {};
		}, false);
	});
	stream.getVideoTracks().forEach(function(track) {
		track.addEventListener(streamEndedEvent, function() {
			callback();
			callback = function() {};
		}, false);
	});
}



