function saveGrpAllAns(){
	getCurrentGrpSecQuestId(false,0);
	var selectedAnswer="";
	var groupAnswers = new Array();
	// var wordCountForSA = "";
	var proceed = true;
	var section = iOAP.secDetails[iOAP.curSection];
	var hasOptionalQuestion = section.hasOptionalQuestion;
	var quesToBeConsidered = 0;
	var selectedOptId = '';
	for(var i=0;i<section.questions.length;i++){
		if(section.questions[i].quesType =="SA" && section.questions[i].keyboardType != "FileUpload"){
			
			/*
			 * if(section.questions[i].keyboardType=="Alphanumeric" &&
			 * section.questions[i].plainOrRichText!= null &&
			 * section.questions[i].plainOrRichText=="RichText") selectedAnswer =
			 * CKEDITOR.instances['answer'+section.questions[i].quesId].getData();
			 */
			if(section.questions[i].keyboardType=="Alphanumeric" && section.questions[i].plainOrRichText!= null &&  section.questions[i].plainOrRichText=="RichText" && CKEDITOR.instances['answer'+section.questions[i].quesId] != undefined){
				if(CKEDITOR.instances['answer'+section.questions[i].quesId].getData().indexOf("<html><head><title></title></head><body></body></html>")!=0 && CKEDITOR.instances['answer'+section.questions[i].quesId].getData().indexOf("<html><head><title></title></head><body><p>\uFFFD</p></body></html>")!=0){
					selectedAnswer = CKEDITOR.instances['answer'+section.questions[i].quesId].getData().split("\uFFFD").join("");
					section.questions[i].responseWordCount=responseWordCount("RichText", selectedAnswer); 
				}
				else{
					selectedAnswer ="";
					section.questions[i].responseWordCount=0;
				}
			}else{
				if(document.getElementById('answer'+section.questions[i].quesId)!=undefined){
				selectedAnswer = document.getElementById('answer'+section.questions[i].quesId).value;
				section.questions[i].responseWordCount=responseWordCount("PlainText", selectedAnswer); 

				}
				else
					{
				selectedAnswer ="";	
				section.questions[i].responseWordCount=0;
					}
			}
			
			// mockVar.curSectionQuestions[i].quesParam.answer = selectedAnswer;
			/*
			 * if(mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].questions[i].selectedAnswerList !=
			 * 'undefined')
			 * mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].questions[i].selectedAnswerList =
			 * mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].questions[i].selectedAnswerList
			 * +"@"+selectedAnswer;
			 */
			selectedOptionsAndAnswersList(mockVar.currentGrp,iOAP.curSection,i,selectedAnswer,"");
			groupAnswers.push(new groupAnswerBean(section.questions[i].quesId,selectedAnswer));
			mockVar.curSectionQuestions[i].quesParam.langID = mockVar.curSectionQuestions[i].quesLangBeans[mockVar.langIndex].langId;
			// selectedAnswer.push(new answerKeyBean(keyName,keyVal));
			// wordCountForSA =
			// $("#noOfWords"+section.questions[i].quesId).text();
			// mockVar.curSectionQuestions[i].typedWord =
			// $('#noOfWords'+section.questions[i].quesId).html()==undefined?$('#noOfWords'+section.questions[i].quesId).text():$('#noOfWords'+section.questions[i].quesId).html().split('
			// ')[0];
			mockVar.curSectionQuestions[i].typedWord = $('#noOfWords'+section.questions[i].quesId).html()==undefined?($('#noOfWords').html()!=undefined ? $('#noOfWords').html().split(' ')[0]:'0'):$('#noOfWords'+section.questions[i].quesId).html().split('<')[1].split('>')[1];
		}
		else if(section.questions[i].quesType =="MCQ" || section.questions[i].quesType =="MSQ"){
			selectedAnswer = "";
			selectedOptId ="";

			if((section.questions[i].quesType =="MSQ") || ((typeof(qpDetailsMockVar[section.questions[i].quesId]) != "undefined" ? qpDetailsMockVar[section.questions[i].quesId].quesLangBean[mockVar.langIndex].quesText : section.questions[i].quesLangBeans[mockVar.langIndex].quesText).indexOf('<ResponsePlaceHolder>')==-1)){
				var answers = document.getElementsByName('answers'+section.questions[i].quesId);
				// keyName =section.questions[i].quesId;
				for(var j=0;j<answers.length;j++){
					if(answers[j].checked==true){   
						selectedAnswer = answerTxt(j,answers,selectedAnswer);
						// selectedAnswer =
						// ($(answers[j]).parent().next('span').text()) +
						// "<ANS_SEP>" + selectedAnswer;
						selectedOptId = (answers[j].value) + "," + selectedOptId;
					}
				}

			}else{
				if($("option:selected",$("#answers"+section.questions[i].quesId)).val()!='select' && $("option:selected",$("#answers"+section.questions[i].quesId)).val()!='choose'){
					selectedAnswer=$("option:selected",$("#answers"+section.questions[i].quesId)).text()+"<ANS_SEP>";
					selectedOptId=$("option:selected",$("#answers"+section.questions[i].quesId)).val()+",";
				}
			}




			if(selectedAnswer !=""){
				selectedAnswer = selectedAnswer.substring(0,selectedAnswer.length-9);
			}
			// Added by Boddu Rakesh
			if(selectedOptId!=''){
				selectedOptId = selectedOptId.substring(0,selectedOptId.length-1);
			}
			selectedOptionsAndAnswersList(mockVar.currentGrp,iOAP.curSection,i,selectedOptId,"id");
			// mockVar.curSectionQuestions[i].quesParam.answer = selectedAnswer;
			groupAnswers.push(new groupAnswerBean(section.questions[i].quesId,selectedAnswer,selectedOptId));
			// mockVar.curSectionQuestions[i].quesParam.selectedOptId =
			// selectedOptId;
			mockVar.curSectionQuestions[i].quesParam.langID = mockVar.curSectionQuestions[i].quesLangBeans[mockVar.langIndex].langId;
		}
	} 
	if(proceed){
		for(var m=0;m<section.questions.length;m++){
			for(var n=0;n<groupAnswers.length;n++){
				if(groupAnswers[n].quesId == section.questions[m].quesId){
					mockVar.curSectionQuestions[m].quesParam.answer = groupAnswers[n].answer;
					if(section.questions[m].quesType == "MCQ" || section.questions[m].quesType == "MSQ"){
						mockVar.curSectionQuestions[m].quesParam.selectedOptId = groupAnswers[n].optionId;
					}
				}
			}
		}
		if(section.maxOptQuesToAns != ""){
			// if(mockVar.isMarkedForReviewConsidered == "YES"){
			var counter = 0;
			for(var i=0;i<iOAP.secDetails[iOAP.curSection].questions.length;i++){
				// var quesStatus =
				// iOAP.secDetails[iOAP.curSection].questions[i].quesParam.status
				// ;
				if(iOAP.secDetails[iOAP.curSection].questions[i].quesType!= "PROGRAMMING TEST"){
					if( !(iOAP.secDetails[iOAP.curSection].questions[i].quesParam.answer == null 
							||  iOAP.secDetails[iOAP.curSection].questions[i].quesParam.answer == '' )){
						counter++;
					}
				}
			}
			quesToBeConsidered += counter;
			// }
			if(hasOptionalQuestion=='true' && quesToBeConsidered>section.maxOptQuesToAns ){
				proceed = false;
				cnfPop('InfoPopup');
				// $("#infoMsg2").html("You have attempted
				// "+quesToBeConsidered+" question, which is more than the
				// maximum limit ("+section.maxOptQuesToAns+") of this section.
				// Please reset the questions which are already answered");
				$("#infoMsg2").html($(globalXmlvar).find('maxQuestionsAlert').text());
				$(".quesToBeConsidered").html(quesToBeConsidered);
				$(".maxOptQuesToAns").html(section.maxOptQuesToAns);
			}
		}
		if(proceed)
			saveCurGroup();
	}
	var idValue = jQuery("#savenextGroup").val();
	auditlogCreation(idValue,"","savenextGroup");
	//console.log("auditlogCreation in saveGrpAllAns");

}

function saveCurGroup(){
	for(var i=0;i<mockVar.curSectionQuestions.length;i++){
		var quesStatus = mockVar.curSectionQuestions[i].quesParam.status;
		var quesAnswer = mockVar.curSectionQuestions[i].quesParam.answer;
		if(quesAnswer == "" && mockVar.curSectionQuestions[i].quesType != "SUBJECTIVE")
			quesAnswer = null;
		if(iOAP.secDetails[iOAP.curSection].groupAllQuestions == "true"){
			if(quesAnswer==null){
				if(quesStatus=="answered" && iOAP.secDetails[iOAP.curSection].answered>0){
					iOAP.secDetails[iOAP.curSection].notanswered++;
					iOAP.secDetails[iOAP.curSection].answered--;
				}
				mockVar.curSectionQuestions[i].quesParam.status="notanswered";
			}else{
				if(quesStatus!="answered"){
					if(quesStatus=="notanswered" && iOAP.secDetails[iOAP.curSection].notanswered>0)
						iOAP.secDetails[iOAP.curSection].notanswered--;
					iOAP.secDetails[iOAP.curSection].answered++;
				}
				if((quesStatus!="answered" && quesStatus!="markedAndAnswered") || (quesStatus=="markedAndAnswered" && mockVar.isMarkedForReviewConsidered=='NO')){
					if(typeof(mockVar.curSectionQuestions[i].isQuesMand)!= "undefined" && mockVar.curSectionQuestions[i].isQuesMand=="true")
						// mockVar.groups[mockVar.currentGrp].noOfMandatoryQuesUnAnswered
						// =
						// mockVar.groups[mockVar.currentGrp].noOfMandatoryQuesUnAnswered-1;
						mockVar.curSectionQuestions[i].isQuesMandUnanswered = false;
				}
				mockVar.curSectionQuestions[i].quesParam.status="answered";
			}
		}
	}
	fillSections();
}

function saveActQuesGrp(quesId){
	if(iOAP.secDetails[iOAP.curSection].questions[quesIdIndexes[quesId]].quesType=="SA" && iOAP.secDetails[iOAP.curSection].questions[quesIdIndexes[quesId]].keyboardType=="FileUpload"){
		fileUploadOnClick();
	}
	//fileUploadOnClick();
	if(iOAP.secDetails[iOAP.curSection].groupAllQuestions == "true"){
		if (typeof(Storage) !== "undefined"){
			if(sessionStorage.getItem( 'groupAllSec'+iOAP.groupId+iOAP.curSection )==null){
				sessionStorage.setItem( 'groupAllSec'+iOAP.groupId+iOAP.curSection , quesId);
			}else{
				sessionStorage.setItem( 'groupAllSec'+iOAP.groupId+iOAP.curSection , quesId)  ;
			}
		}
	}
}

function resumeActQuesGrp(){
	if(iOAP.secDetails[iOAP.curSection].groupAllQuestions == "true"){
		try{
		if (typeof(Storage) !== "undefined"){
			if(sessionStorage.getItem( 'groupAllSec'+iOAP.groupId+iOAP.curSection )!=null){
				var curQues = sessionStorage.getItem( 'groupAllSec'+iOAP.groupId+iOAP.curSection);
				var offset = 0;
				offset = document.getElementById('quesAnsContent'+curQues).offsetTop - $('.leftDiv').offset().top;
				$(".leftDiv").animate({
					scrollTop: offset
				}, 'slow');
			}
		}}catch(e){}
	}
}

