	function validateScoresInMock(){
		var returnValue="";
		var i=0;
		for(var groupNo=0;groupNo<mockVar.groups.length;groupNo++){
			if($('#groupScore'+groupNo).val()!=undefined){
				if($('#groupScore'+groupNo).val()!="" && parseFloat($('#groupScore'+groupNo).val())==parseFloat(groupScores[groupNo])){
					// returnValue=true;
				}else{
					if(i!=0)
					returnValue=returnValue+","+mockVar.groups[groupNo].groupName;
					else
					returnValue=returnValue+mockVar.groups[groupNo].groupName;
					i++;
				}
			}
		}
		if(returnValue==""){
			setCookie(mockVar.langName);
			document.cookie = "defLangName=" + mockVar.languages[mockVar.defaultLang] + ";";
			var encodedParam=mockVar.orgId + "@@" + mockVar.mockId;
			if(document.URL.indexOf("eID=")>-1){
				encodedParam=document.URL.split('quiz.html?')[1];
			}
			if(typeof(mockVar.isFeedBackRequired) == "undefined" || mockVar.isFeedBackRequired == "NO" || mockVar.isFeedBackRequired == "0"){
				if(mockVar.isSecured == "true" && sessionStorage.assessType == "Actual"){
					//deleteLauncher();
				}
				window.location.href = "close.html?"+encodedParam+"@@"+mockVar.subscribedFor+"#"+(($.cookie("isApp")=="true")?"isApp":"")+(($.cookie("isLauncher")=="true")?"isLauncher":"");
			}else{
				window.location.href = "FeedBack.html?"+encodedParam+"@@"+mockVar.subscribedFor+"@@"+mockVar.candMasterId+"@@"+mockVar.attemptId+"@@"+mockVar.useDefaultFeedback;
			}
		}else{
			cnfPop('scoreValidationPopUp');
			$("#scoreValidationMessage").html(mockLabels.scoreNotMatched+"<br>"+returnValue);
		}
	}
