	function autoMockBackUp(){
					$.ajax({
							url:'/lanscape/AdminAJAXServlet?action=saveAuditLog&macAddress='+macAddress,
							type: 'POST',
							async: true,
							data: JSON.stringify(AuditJson),
							/*
							 * headers: { Accept : "application/json;
							 * charset=utf-8" }, dataType: 'json',
							 */
							success: function (data) {
								missedCount=0;
								setTimeout(function(){autoMockBackUp();},document.URL.indexOf("navigationTime")>0?(parseInt(document.URL.split("navigationTime=")[1].split("&")[0])*1000):30000);
							},
							error : function(){
								missedCount++;
								setTimeout(function(){autoMockBackUp();},document.URL.indexOf("navigationTime")>0?(parseInt(document.URL.split("navigationTime=")[1].split("&")[0])*1000):30000);
							}
						});
					if(missedCount>=2 && !($("#backupAlerts").is(":visible"))){
						cnfPop('backupAlerts');
						$("#backupAlertMsg").html($(globalXmlvar).find('CouldNotConnectToServer').text());
						if(sessionStorage.isSecured=="true" &&  sessionStorage.LauncherApps != '6' && sessionStorage.operatingSystem !=undefined && (sessionStorage.operatingSystem=='Mac OS' || sessionStorage.operatingSystem=='Mac OS X' || sessionStorage.operatingSystem=='iOS') && sessionStorage.isPaperDevice == "false")
						{
							$(".shiftEsc").html($(globalXmlvar).find('shiftEscMac').text());
							//$(".okayOrNoButtonWindowClosePopup").show();

						}
						clearTimeout(mockVar.timeCounter);
					}
		}
	function removeTimer(id) {
		var index = timersArray.indexOf(id);
		if (index >= 0)
			timersArray=timersArray.splice(index, 0);
	}
	function clearAllInterruptionTimers(){
		for(var i=0;i<timersArray.length;i++){
			clearTimeout(timersArray[i]);
			removeTimer(timersArray[i]);
		}
	}
	function removeTenSecInterruptionTimer(id) {
		var index = tenSecTimersArrayForInterruption.indexOf(id);
		if (index >= 0)
			tenSecTimersArrayForInterruption=tenSecTimersArrayForInterruption.splice(index, 0);
	}
	function clearAllTenSecInterruptionTimer(){
		for(var i=0;i<tenSecTimersArrayForInterruption.length;i++){
			clearTimeout(tenSecTimersArrayForInterruption[i]);
			removeTimer(tenSecTimersArrayForInterruption[i]);
		}
	}
	function getTimeRemaining(endtime){
		  var total = Date.parse(endtime) - Date.parse(new Date());
		  var seconds = Math.floor( (total/1000) % 60 );
		  var minutes = Math.floor( (total/1000/60) % 60 );
		  var hours = Math.floor( (total/(1000*60*60)) % 24 );
		  var days = Math.floor( total/(1000*60*60*24) );

		 /*
			 * return { total, days, hours, minutes, seconds };
			 */
		  return total;
		}
	function initializeClock(endtime) {
		  var timeinterval = setInterval(function(){
		    var t = getTimeRemaining(endtime);
		   if (t/* .total */ < 0) {
		      clearInterval(timeinterval);
		      if(mockVar.maxInstruTime>0){
					document.getElementById("disclaimer").checked=true;
					readyToBegin(true);
				}
		    }else{
		    	 $(".instruTimeCounter").html("<b>"+mockLabels.timeLeft+"<span>"+convertTime(t/* .total *//1000, -1, -1, -1)+" "+timerFormatLabel+"</span></b>");
		    	 $("#mobileTimer").html("<b>"+mockLabels.timeLeft+"<span>"+convertTime(t/* .total *//1000 , -1, -1, -1)+" "+timerFormatLabel+"</span></b>");
		    	if(mockVar.maxInstruTime - (t/* .total *//1000) > mockVar.minInstruTime){
					$('#disclaimer').removeAttr("disabled");
					$('#disclaimer').removeAttr("title");
					$('#checkBoxEnableMessage').hide();
				}else{
					$('#disclaimer').attr('disabled',true);
					$('#disclaimer').attr('title',mockLabels.checkBoxEnableTitleMessage+convertTime(parseInt(mockVar.minInstruTime - (mockVar.maxInstruTime-(t/* .total *//1000))),-1, -1, -1)+" "+timerFormatLabel);
					$('#readylink').attr('title',mockLabels.checkBoxEnableTitleMessage+convertTime(parseInt(mockVar.minInstruTime - (mockVar.maxInstruTime-(t/* .total *//1000))),-1, -1, -1)+" "+timerFormatLabel);
					$('#agreementMessageDef').attr('title',mockLabels.checkBoxEnableTitleMessage+convertTime(parseInt(mockVar.minInstruTime - (mockVar.maxInstruTime-(t/* .total *//1000))),-1, -1, -1)+" "+timerFormatLabel);
					$('#agreementMessageCustom').attr('title',mockLabels.checkBoxEnableTitleMessage+convertTime(parseInt(mockVar.minInstruTime - (mockVar.maxInstruTime-(t/* .total *//1000))),-1, -1, -1)+" "+timerFormatLabel);
					$('#checkBoxEnableTime').html(convertTime(parseInt(mockVar.minInstruTime - (mockVar.maxInstruTime-(t/* .total *//1000))),-1, -1, -1)+" "+timerFormatLabel);
					if(mockVar.minInstruTime!=0)
					$('#checkBoxEnableMessage').show();
				}
				/*
				 * mockVar.instTimeCounter =
				 * setTimeout(function(){startInstruCounter(time-1);},1000);
				 */
		    	setInstruHeights();
		    }
		  },1000);
		}
	function includes(container, value) {
		var returnValue = false;
		var pos = container.indexOf(value);
		if (pos >= 0) {
			returnValue = true;
		}
		return returnValue;
	}
