	function getCustLangList(configFilePath){

		var res=[];
		var target = configFilePath+"?v="+ + new Date();
		$.ajax({
			type: "GET",
			url: target,
			async : false,
			dataType: "text",
			success: function(data) {
						
							res=data.split(",");
							sessionStorage.custLangVersion=res[0];
							res.shift();
							
							res=res.map(function(s){

		                           return  s.substr(0, s.length-4);

								});
				
					}
		});
		return res;
	}
	
	// function to cache media files in cache storage. parameter passed is
