function circleTimerDeakin(id,time,givenTime){
	try{
		if(id=="maxTime" && sessionStorage.isPaperUI != "1")
			return;
	   var  timeConsumed = givenTime-time;
		line = 100-(timeConsumed/givenTime)*100;
		if(line>0 && time>0){
		    document.getElementsByClassName('circle-fillD'+id)[0].setAttributeNS(null, 'stroke-dasharray', line + " 100");
	        $('.TimerCountdownD'+id).text(convertTime(time,-1));
		    //setTimeout(function(){circleTimerDeakin(time-1,givenTime)},1000)
		}else{
		     document.getElementsByClassName('circle-fillD'+id)[0].setAttributeNS(null, 'stroke-dasharray', "0" + " 100"); 
		     $('.TimerCountdownD'+id).text("00:00");
		     document.querySelector(".circle-fillD"+id).style.stroke = "#0ae886";
		}
	}catch(e){}
}
function playMediaWithoutJWPlayer(){
	var playBegin = false;
		$(".htmlAudioVideo").each(function(){
			var id = $(this).attr("id");
			quesTimerUpdatedAfterMediaCompleted = false;
			if(mockVar.curQuesBean.quesType == "SUBJECTIVE"){
				$("#"+id).css({"width":"900","height":"506.25"}); // changed: reason :this should be exact 16:9 or any other proper aspect : sreejith 
			}
			$('#'+id).get(0).play();
			$('audio, video').prop('volume', (volumeIndex)/10);
        	playBegin = true;
        	setTimeout(function(){
			$('#'+id).on('ended', function() {
				playBegin = false;
				mediaPlayCompleted = true;
				mediaPlayStarted = false;
				quesTimerUpdatedAfterMediaCompleted = true;
				if(false && startTheResponseTimeAfterMediaPlay  && typeof(mockVar.curQuesBean.audioVideoPresentAtQuesLevel) != "undefined"){
					if(mockVar.curQuesBean.comprehensionId==0 && mockVar.curQuesBean.laqId==0){
						mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].questions[iOAP.curQues].mediaPlayedCompleted = true;
						if(mockVar.curQuesBean.issubjectivequestion == 'false')
							mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].questions[iOAP.curQues].maxTime = 0;
						if(mockVar.curQuesBean.quesType != "SUBJECTIVE" && typeof(mockVar.curQuesBean.responseTime) != "undefined"){
							mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].questions[iOAP.curQues].maxTime = mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].questions[iOAP.curQues].responseTime;
						} else if(mockVar.curQuesBean.quesType == "SUBJECTIVE" ){
							mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].questions[iOAP.curQues].maxTime = 0;
						}
						
					}  else {
						if(mockVar.curQuesBean.comprehensionId != 0 && typeof(mockVar.compreLaqQues[quesIdIndexes[iOAP.secDetails[iOAP.curSection].questions[iOAP.curQues].comprehensionId]].responseTime) != "undefined" && mockVar.compreLaqQues[quesIdIndexes[iOAP.secDetails[iOAP.curSection].questions[iOAP.curQues].comprehensionId]].additionalQuesType != "" && mockVar.compreLaqQues[quesIdIndexes[iOAP.secDetails[iOAP.curSection].questions[iOAP.curQues].comprehensionId]].audioVideoPresentAtQuesLevel){
							mockVar.compreLaqQues[quesIdIndexes[iOAP.secDetails[iOAP.curSection].questions[iOAP.curQues].comprehensionId]].compremaxTime = mockVar.compreLaqQues[quesIdIndexes[iOAP.secDetails[iOAP.curSection].questions[iOAP.curQues].comprehensionId]].responseTime;
							mockVar.compreLaqQues[quesIdIndexes[iOAP.secDetails[iOAP.curSection].questions[iOAP.curQues].comprehensionId]].mediaPlayedCompleted = true;
						} else if(mockVar.curQuesBean.laqId != 0 && typeof(mockVar.compreLaqQues[quesIdIndexes[iOAP.secDetails[iOAP.curSection].questions[iOAP.curQues].laqId]].responseTime) != "undefined" && mockVar.compreLaqQues[quesIdIndexes[iOAP.secDetails[iOAP.curSection].questions[iOAP.curQues].laqId]].additionalQuesType != "" && mockVar.compreLaqQues[quesIdIndexes[iOAP.secDetails[iOAP.curSection].questions[iOAP.curQues].laqId]].audioVideoPresentAtQuesLevel){
							mockVar.compreLaqQues[quesIdIndexes[iOAP.secDetails[iOAP.curSection].questions[iOAP.curQues].laqId]].compremaxTime = mockVar.compreLaqQues[quesIdIndexes[iOAP.secDetails[iOAP.curSection].questions[iOAP.curQues].comprehensionId]].responseTime;
						} else if(mockVar.curQuesBean.comprehensionId != 0 && typeof(mockVar.compreLaqQues[quesIdIndexes[iOAP.secDetails[iOAP.curSection].questions[iOAP.curQues].comprehensionId]].responseTime) != "undefined" && (typeof(mockVar.compreLaqQues[quesIdIndexes[iOAP.secDetails[iOAP.curSection].questions[iOAP.curQues].comprehensionId]].additionalQuesType) == "undefined" || mockVar.compreLaqQues[quesIdIndexes[iOAP.secDetails[iOAP.curSection].questions[iOAP.curQues].comprehensionId]].additionalQuesType == "") && mockVar.curQuesBean.audioVideoPresentAtQuesLevel){
							if(mockVar.curQuesBean.quesType != "SUBJECTIVE" && typeof(mockVar.curQuesBean.responseTime) != "undefined"){
								mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].questions[iOAP.curQues].maxTime = mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].questions[iOAP.curQues].responseTime;
								mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].questions[iOAP.curQues].mediaPlayedCompleted = true;
							}
							
						}
					}
				}
		    });

        	},10);
		});
		
	}
function increaseBackupHitCount(NoOfHits, AvgTimeTaken){
	var target = "../IBACC/MockCandidateAction.do";
	var status = false;
	$.ajax({
		type: "POST",
		url: target,
		data: {
			action : "IncreaseBackupHitCount",
			noOfHits : NoOfHits,
			avgTimetaken : AvgTimeTaken,
			orgId : sessionStorage.orgId,
			candMasterId : sessionStorage.candMasterId,
			attemptId : sessionStorage.attemptId
		},
		dataType: "text",
		success: function(data) {	
					if(data=="success"){
						//console.log("Updated backup hit count successfully");
						status=true;
					}
					else console.log("failed to update backup hit count");
			}
	});
	return status;
}
