function alphaWordLimitForMessage(msgObj){
	
	var number = 0;
	var matches = msgObj.value.match(/\S+/g);
	
	if(matches) {
		number = matches.length;
	}
	if(number > 500)
         msgObj.value =  msgObj.oldValue ;
	else
		msgObj.oldValue = msgObj.value;
}
