function createScreenRecordFile(orgId,mockId,candMasterId,attemptNo,retryCount){
	var URL = "/IBACC/MockAssessmentIBAAction.do?action=createScreenRecordFile";
	var paramsvalue = {};
	paramsvalue["candMasterId"] = candMasterId;
	paramsvalue["attemptNo"] = attemptNo;
	paramsvalue["orgId"] = orgId ;
	paramsvalue["mockId"] = mockId;
	
	jQuery.ajax({
		url: URL,
		async: false,
		type: 'POST',
		data: paramsvalue,
		dataType: 'text',
		success: function(data) {
			console.log("Screen record File was successfully created");
		},
		error : function(){
			if(retryCount<3){
				console.log("Failed to create Screen Record file, Retrying");
				createScreenRecordFile(orgId,mockId,candMasterId,attemptNo,retryCount+1);
			}
			else{
				console.log("Failed to create Screen Record file");
			}
		}

	});
}
function deleteScreenRecordFile(orgId,mockId,candMasterId,attemptNo,retryCount){
	var URL = "/IBACC/MockAssessmentIBAAction.do?action=deleteScreenRecordFile";
	var paramsvalue = {};
	paramsvalue["candMasterId"] = candMasterId;
	paramsvalue["attemptNo"] = attemptNo;
	paramsvalue["orgId"] = orgId ;
	paramsvalue["mockId"] = mockId;
	
	jQuery.ajax({
		url: URL,
		async: false,
		type: 'POST',
		data: paramsvalue,
		dataType: 'text',
		success: function(data) {
			console.log("Screen record File was successfully deleted");
		},
		error : function(){
			if(retryCount<3){
				console.log("Failed to delete Screen Record file, Retrying");
				deleteScreenRecordFile(orgId,mockId,candMasterId,attemptNo,retryCount+1);
			}
			else{
				console.log("Failed to delete Screen Record file");
			}
		}

	});
}
function checkInterruption(e){
	if(allowInterruptions == "NO" && isFullScreenEnabled && clickOnOKButton && sessionStorage.isLauncher != "true" && (typeof(sessionStorage.isPaperDevice) == "undefined" || sessionStorage.isPaperDevice != "true")){
		clickOnOKButton = false;
		setTimeout(function(){clickOnOKButton = true;},1000);
		var AuditJsonObject = new Object();
		AuditJsonObject.ActionName = "Interruption Warning Message";
		AuditJsonObject.ActionDesc = "Assessment is interrupted";
		AuditJsonObject.GroupId = "NA";
		AuditJsonObject.SectionId = "NA";
		AuditJsonObject.QuestionId = "NA";
		AuditJsonObject.SelectedOptionId = "NA";
		AuditJsonObject.OptionSequence = "NA";
		AuditJsonObject.candidateName = sessionStorage.isOfflinePaper=='1' ? sessionStorage.username : $.cookie("username");
		AuditJsonObject.loginId = sessionStorage.isOfflinePaper=='1' ? sessionStorage.username : $.cookie("loginId");
		var currentDate = new Date();
		AuditJsonObject.Time = currentDate.yyyymmddHHmmss();
		AuditJsonObject.eventTimestamp = Date.now();
		AuditJsonObject.mockVarLoginId = mockVar.loginId;
		if(!isExaminer){
		AuditJson.push(AuditJsonObject);
		}
		// var className = $(e.target).attr('class');
		// className = "."+className;
		e = e || window.event;
		
		var isPlayer = false;
		var className = $(e.target).attr('class');
		if(typeof(className) != 'undefined' && className.indexOf("jp-") >=0){
			isPlayer = true;
			isfinalSubmit = true;
			clickOnOKButton = true;
		}
		
		if(mockVar.curQuesBean.keyboardType == "FileUpload")
			clickOnOKButton = true;
		var url = document.URL;
		// if(!isSetTimeoutCalled){
		setTimeout(function(){
			var currentInterruptedTime = new Date();
			temptInterruptionCountNo++;
			if(url.indexOf("quiz.html") > 0 && !isfinalSubmit && !isPlayer && mockVar.storeCandResponse == 1 && ( (mockVar.curQuesBean.keyboardType != 'AudioFile' || ( mockVar.curQuesBean.keyboardType == 'AudioFile' && !audioVideoResponsePending) )  && (mockVar.curQuesBean.keyboardType != 'VideoFile' || ( mockVar.curQuesBean.keyboardType == 'VideoFile' && !audioVideoResponsePending) )) && mockVar.curQuesBean.keyboardType != 'FileUpload' &&  mockVar.curQuesBean.plainOrRichText!="RichText" &&((typeof(previousTime) == "undefined" && temptInterruptionCountNo == 1) || (currentInterruptedTime.getTime() - previousTime.getTime()) > 500 )){
				// tempInterruptionTime = 9;
				previousTime = new Date();
				// console.log(previousTime);
				focused = (e || event).type == "focus";
				isPlayer = false;
				isfinalSubmit = false;
				// && !interruptionPopupLive
				if(!focused){
					noOfInterruptions=parseInt(noOfInterruptions+"")+1;
					mockVar.numberOfInterruptions = noOfInterruptions;
					// console.log("noOfInterruptions "+noOfInterruptions);
					remainingInterruptions=remainingInterruptions-1;
					if(remainingInterruptions>=0 && allowInterruptions=='NO'){
						saveBackUp(false);
						clearAllInterruptionTimers();
						InterruptionTimer(interruptionTimer);
						displayPopup('warningPopup');
						$("#seterror").html($(globalXmlvar).find('interruptionPopupMsg').text());
						$("#seterror").show();
						if(mockVar.proctorMessageReadByCandidate == 1)
							$("#proctorMessage").hide();
						interruptionPopupLive=true;
						/* tenSecInterruptionTimeOut= */tenSecTimersArrayForInterruption.push(setTimeout(function(){
							/*
							 * if(isOkClicked){ isOkClicked = false; } else{
							 */
							/*
							 * var params = url.split("quiz.html?"); var orgId =
							 * $.trim(params[1]).split("@@")[0]; var mockId =
							 * $.trim(params[1]).split("@@")[1]; var attemptId =
							 * $.trim(params[1]).split("@@")[2]; var
							 * candMasterId = $.trim(params[1]).split("@@")[3];
							 */
							if((previousInteruptionCount == 0 || previousInteruptionCount != noOfInterruptions)){
								// isSetTimeoutCalled = true;
								// alert("count"+parseInt(noOfInterruptions+"")
								// +" Previous:"
								// +parseInt(previousInteruptionCount+""));
								previousInteruptionCount = noOfInterruptions;
							if(url.indexOf(".html?") >= 0){
								var params = url.split(".html?");
								var paramsData = $.trim(params[1]).split("@@");
								orgId= paramsData[0];
								assessmentId = paramsData[1];
								attemptId = paramsData[2];
								candMasterId = paramsData[3];
							} else {
								orgId= $.cookie("orgId") == undefined ? sessionStorage.orgId : $.cookie("orgId");
								assessmentId = $.cookie("assessmentId") == undefined ? sessionStorage.assessmentId : $.cookie("assessmentId");
								attemptId = $.cookie("attemptId") == undefined ? sessionStorage.attemptId : $.cookie("attemptId");
								candMasterId = $.cookie("cand_master_id") == undefined ? sessionStorage.cand_master_id : $.cookie("cand_master_id");
							}
							if(candMasterId.indexOf("#") > 0)
								candMasterId = candMasterId.substring(0,candMasterId.indexOf("#"));
							// auditLogBackUp(true,candMasterId,attemptId,assessmentId,orgId);
							updateInterruptions(parseInt(noOfInterruptions+""),"","sendBackUp");
							explicitClose=true;
							// isSetTimeoutCalled = false;
							// window.close();
							if(mockVar.storeCandResponse==1){
								//window.location.href ="error.html?E125"+(($.cookie("isApp")=="true")?"isApp":"")+(($.cookie("isLauncher")=="true")?"isLauncher":"");
								saveBackUp(false,undefined,undefined,"E125");
							}else{
								//window.location.href ="error.html?E150"+(($.cookie("isApp")=="true")?"isApp":"")+(($.cookie("isLauncher")=="true")?"isLauncher":"");
								saveBackUp(false,undefined,undefined,"E150");
							}
							}
							/* } */
						},10000));
					}	else if(allowInterruptions=='NO'){
						updateInterruptions(parseInt(noOfInterruptions+""),"Locked");
						toErrorPage=true;
						if(sessionStorage.remoteProctoring==='1')
							window.location.href ="error.html?E116#"+errorPageContent+"@@"+mockVar.lockedSubmit+"@@"+(($.cookie("isApp")=="true")?"isApp":" ")+(($.cookie("isLauncher")=="true")?"isLauncher":"");
						else if(sessionStorage.remoteProctoring==='0')
							window.location.href ="error.html?E125#"+errorPageContent+"@@"+mockVar.lockedSubmit+"@@"+(($.cookie("isApp")=="true")?"isApp":" ")+(($.cookie("isLauncher")=="true")?"isLauncher":"");
					}
				}
			} else {
				isPlayer = false;
				isfinalSubmit = false;
			}
		},15);
		// }
	}
}
function replaceMathFormula(){
	$(".Wirisformula").each(function(){
		try{
		   var str = $(this).attr("data-mathml"); 
		   str=str.replaceAll("?","<").replaceAll("?",">").replaceAll('?','"').replaceAll('?','&').replaceAll('`',"'");
		   var tempStr = str.substring(0, str.indexOf("xmlns"));
		   tempStr = tempStr+str.substring( str.indexOf("MathML?")+7);tempStr=tempStr.replaceAll('?',"'");
			$(this).before(tempStr);
			$(this).remove();
		}catch(e){console.log(e);}
	});
	try{MathJax.typeset();}catch(e){console.log(e);}
}
function isPromise(value) {
    return value !== undefined && value !== null && typeof value.then === 'function';
}


//moved from iBA.js
function timeOutGroupCompre(){ 
	var	compreQuesIndex = '';
	var	laqQuesIndex = '';
	var compreQues="";
	var section = iOAP.secDetails[iOAP.curSection];
	if(mockVar.curQuesBean.comprehensionId !=0){
		compreQuesIndex = mockVar.compreLaqQues.inArray(section.questions[iOAP.curQues].comprehensionId, 'quesId');
		compreQues = mockVar.compreLaqQues[compreQuesIndex].quesId;
	}
	else if(mockVar.curQuesBean.laqId !=0){
		laqQuesIndex = mockVar.compreLaqQues.inArray(section.questions[iOAP.curQues].laqId, 'quesId');
		compreQues = mockVar.compreLaqQues[laqQuesIndex].quesId;
	}
	for(var i=0;i<section.questions.length;i++){
		if(section.questions[i].comprehensionId==compreQues || section.questions[i].laqId==compreQues ){
			
			section.questions[i].maxTimeReached = true;
			section.questions[i].isQuesMandUnanswered = false;
			currentQuestionIndex = i;
			auditlogCreation("","Question Level Timer Exhausted","QuestionTimedOut");
			if(section.questions[i].reVisitQues == "true" || (section.questions[i].reVisitQues == "false" && section.questions[i].flagforReVistQues==true)){
				section.questions[i].flagforReVistQues=false;
				section.secCount = section.secCount+1;
				if(section.secCount==iOAP.secDetails[iOAP.curSection].questions.length)
					mockVar.groups[mockVar.currentGrp].groupCount = mockVar.groups[mockVar.currentGrp].groupCount+1;
				section.questions[i].reVisitQues="false";
			}
		}
		}
}


