function formQuestionTextForVoiceOver(quesTxt){
	inputTxt= "";
	inputTxt= quesTxt;
	try{
		inputTxt = inputTxt.replaceAll(/<style(.*?)<\/style>/gi, ""); 
		 inputTxt = inputTxt.replaceAll(/(<|<\/)(?!gaptype)[^<]*>/gi, "");
		var element = document.createElement('div');
		element.innerHTML = inputTxt;
		inputTxt= element.innerText;
		/*var replacements = {
				 "www.": " www dot ",".net": " dot net ",".com": " dot com ",".gov": " dot gov ",".uk": " dot uk ",".us": " dot us ",".in": " dot in ",".org": " dot org ",".edu": " dot edu ",".info": " dot info ",".mil": " dot mil ",".biz": " dot biz ",".co": " dot co "
				};
		for (var word in replacements) {
			 if (replacements.hasOwnProperty(word)) {
				 inputTxt = inputTxt.replaceAll(word, replacements[word]);
			 }
			}*/
		var pattern = /\b(?:www\.[^\s/$.?#]+\.[^\s]*)|(?:[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,})\b/g; // email and website address
		var matches = inputTxt.match(pattern);
		if(matches!=null){
			matches.forEach(match => {
				   var replacement = match.replace(/\./g, ' dot ');
				   inputTxt = inputTxt.replace(match, replacement);
			});
	     }
		//inputTxt= inputTxt.replace(/(?<=\d),(?=\d)/g, ""); //comma within a number ex: 18,000 --> 18000
		var pattern1=/(\d),(\d)/g;
		var matches1=inputTxt.match(pattern1);
		if(matches!=null){
		matches1.forEach(match=>{
			var rep=match.replace(/\,/g,'');
		inputTxt=inputTxt.replace(match,rep)
		})
	}
		inputTxt= inputTxt.replace(/\s{2,}/g, " . "); // pause for extra space 
	}catch(e){
		console.log(e);
	}
	return inputTxt.replaceAll('<','&lt;').replaceAll('>','&gt;');
}


