function setScoreCardProperty(str, scoreCardTableRows) {
	  // add scoreCardTableRows to existing style attributes
	  let updatedHtml = str.replace(
	    /<table([^>]*?)style='"['"]/gi,
	    (match, beforeStyle, styleContent) => {
	      return `<table${beforeStyle}style="${styleContent}; --score_card_table_rows:${scoreCardTableRows}"`;
	    }
	  );

	  // add style attribute if missing
	  updatedHtml = updatedHtml.replace(
	    /<table((?!style)[^>]*?)>/gi,
	    `<table$1 style="--score_card_table_rows:${scoreCardTableRows}">`
	  );

	  return updatedHtml;
	}


