function updateSaveButton() {
	try{
			if(iOAP.secDetails[iOAP.curSection].groupAllQuestions == "false"){
				if(iOAP.secDetails.length == 1){
					if(mockVar.curQuesBean.comprehensionId !=0 || mockVar.curQuesBean.laqId !=0){
						var mockCompreLaqIndex='';
						if(mockVar.curQuesBean.comprehensionId !=0 ){
							mockCompreLaqIndex = mockVar.compreLaqQues.inArray(mockVar.curQuesBean.comprehensionId, 'quesId');
						}else if(mockVar.curQuesBean.laqId !=0 ){
							mockCompreLaqIndex = mockVar.compreLaqQues.inArray(mockVar.curQuesBean.laqId, 'quesId');
						}
						if(mockVar.compreLaqQues[mockCompreLaqIndex].groupComprehensionLaqQuestions == "true"){
							var quesCount = 0;
							for(var i=0;i<mockVar.curSectionQuestions.length;i++){
								if(mockVar.curSectionQuestions[i].comprehensionId == mockVar.compreLaqQues[mockCompreLaqIndex].quesId){
									quesCount++;
								}
							}
							if(quesCount == mockVar.curSectionQuestions.length){
								if(titleHover)
								$(".savenextGroup").attr("title",mockLabels.btnSave);
								$('.savenextGroup').val(mockLabels.btnSave);
							}
							else{
                                if(titleHover)
								$(".savenextGroup").attr("title",mockLabels.btnSaveNext);
								$('.savenextGroup').val(mockLabels.btnSaveNext);
							
                            }
						}
					}
				}
			}
		
	}
	catch (err) { 
        console.log('updateSaveButton error:', err);     
    }
}

function clean(str) {
  return str
    .replace(/\u200B|\u200C|\u200D/g, "") 
    .replace(/\u00A0/g, " ");
}

function markStatusForPredefinedText(curQuestion,singleORgrptogether)
{
	statusToReturn = ''
	if(curQuestion.keyboardType === 'Alphanumeric' && mockVar.groups[mockVar.currentGrp].secDetails[iOAP.curSection].questions[iOAP.curQues].quesLangBeans[mockVar.langIndex].preDefinedText !== '')
		{
		  var replacenbspStr;
		  if(curQuestion.plainOrRichText === 'RichText')
		  {
			  if(singleORgrptogether == "single")
			  {
				  replacenbspStr = CKEDITOR.instances['answer'].getData().split("\uFFFD").join("").split("&nbsp;").join("").split("<br />").join('');
			  }
			  else
			  {
				  replacenbspStr = CKEDITOR.instances['answer'+curQuestion.quesId].getData().split("\uFFFD").join("").split("&nbsp;").join("").split("<br />").join('');
			  }
			  if(clean(replacenbspStr)===clean(tempRichAnswer[curQuestion.quesId].split("\uFFFD").join("").split("&nbsp;").join("").split("<br />").join('')))
			  {
				  statusToReturn="notanswered";
			  }
			  else
			  {
				  statusToReturn="answered";
			  }
		  }
		  else if(mockVar.curQuesBean.plainOrRichText === "PlainText")
		  {
			  //var pichTextEmtpyFlags = (mockVar.curQuesBean.quesParam.answer==='');
			  if(curQuestion.quesParam.answer === curQuestion.quesLangBeans[mockVar.langIndex].preDefinedText)
			  {
				  statusToReturn="notanswered";
			  }
			  else
			  {
				  statusToReturn="answered";
			  }
		  }
		}
		return statusToReturn;
}
