function calculateSHA256(blob, timestamp, videoType, failedCalculateHashCount) {
//	console.log("SHA256 START", timestamp, "Size:", blob.size);
    blob.arrayBuffer()
        .then(function(buffer) {
            return crypto.subtle.digest("SHA-256", buffer);
        })
        .then(function(hashBuffer) {
            var checksum = Array.from(
                new Uint8Array(hashBuffer)
            )
            .map(function(b) {
                return b.toString(16).padStart(2, '0');
            })
            .join('');
//            console.log("SHA256 END",timestamp,checksum);
            if(videoType === "CandVideos" || videoType === "RoomVideos"){
            	pushRemoteProcData(blob, timestamp, checksum);
            }
            else if(videoType === "ScreenVideos")
        	{
            	pushScreenProcData(blob, timestamp, checksum);
        	}
            else if(videoType === "CandImages" || videoType === "RoomImages")
        	{
            	pushImageForRemoteProctoringAfterHash(blob, timestamp, checksum);
        	}
            
        })
        .catch(function(error) {
        	failedCalculateHashCount++;
        	if(failedCalculateHashCount<3){
	            console.error("Checksum calculation failed", error);
	            calculateSHA256(blob, timestamp, videoType,failedCalculateHashCount);
	//            pushRemoteProcData(
	//                blob,
	//                timestamp,
	//                ""
	//            );
        	}
        	else{
        		if(videoType === "RoomVideos" || videoType === "RoomImages"){
        			window.location.href = "/OnlineAssessment/error.html?"+"ELowSizeVideo"+(($.cookie("isApp")=="true")?"isApp":"")+(($.cookie("isLauncher")=="true")?"isLauncher":"");               	
    			}
        		else{
        			auditlogCreation("Calculate SHA", "Unable to Calculate SHA", "Calculate SHA", true, "ELowSizeVideo");
        		}
        	}
        });
}
function returnExistingStyles(imgInstance) {
	var attrs = "";
	imgInstance.replace(/(\w+)\s*=\s*(['"])(.*?)\2/g, function(match, attr, quote, value) {
        if (!["src", "name"].includes(attr.toLowerCase())) {
            attrs += " " + attr + "='" + value + "'";
        }
    });
    return attrs.trim();
}
